@layer legacy {
.app {
  --rojo: var(--ui-primary);
  --celeste: var(--ui-accent-border);
  --azul: var(--ui-accent);
  --blanco: var(--ui-surface);
  --gris: var(--ui-border-strong);
  --gris-oscuro: var(--ui-chart-neutral);
  --ink: var(--ui-text);
  --ink-soft: var(--ui-accent-hover);
  --muted: var(--ui-chart-neutral);
  --surface: color-mix(in srgb, var(--ui-surface) 94%, transparent);
  --surface-soft: color-mix(in srgb, var(--ui-surface-alt) 88%, transparent);
  --surface-tint: color-mix(in srgb, var(--ui-accent-border) 13%, transparent);
  --line: color-mix(in srgb, var(--ui-border-strong) 76%, transparent);
  --line-strong: color-mix(in srgb, var(--ui-accent-border) 48%, transparent);
  --card-shadow: 0 10px 24px color-mix(in srgb, var(--ui-text) 7%, transparent);
  --card-shadow-soft: 0 4px 14px color-mix(in srgb, var(--ui-text) 5%, transparent);

  min-height: 100vh;
  min-height: 100dvh;
  width: 100%;
}

[hidden] {
  display: none !important;
}

.titulacion-page {
  display: flex;
  flex-direction: column;
  gap: 18px;
  width: 100%;
  max-width: 100%;
  overflow-x: hidden;
}

.titulacion-page .student-grid,
.titulacion-page .student-card,
.titulacion-page .student-card--wide {
  width: 100%;
  max-width: none;
}

.titulacion-page .student-grid--content {
  grid-template-columns: minmax(0, 1fr);
}

.titulacion-hero {
  align-items: stretch;
}

.titulacion-hero aside {
  min-width: 220px;
}

.titulacion-grid {
  grid-template-columns: minmax(0, 1fr);
}

.titulacion-grid--split {
  grid-template-columns: minmax(280px, 0.9fr) minmax(320px, 1.1fr);
}

.titulacion-grid--split .student-card--wide {
  grid-column: 1 / -1;
}

.titulacion-search-form {
  grid-template-columns: minmax(420px, 1fr) minmax(160px, auto) minmax(170px, auto) minmax(240px, auto);
  align-items: end;
}

.titulacion-search-button,
.titulacion-refresh-button {
  min-height: 44px;
  padding: 0 22px;
  border: 1px solid color-mix(in srgb, var(--ui-accent) 48%, transparent);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-primary);
  box-shadow: var(--ui-shadow-sm);
  color: var(--ui-on-primary);
  font-size: var(--ui-size-16);
  font-weight: var(--ui-weight-bold);
  letter-spacing: 0;
}

.titulacion-search-button:hover,
.titulacion-search-button:focus-visible,
.titulacion-refresh-button:hover,
.titulacion-refresh-button:focus-visible {
  border-color: color-mix(in srgb, var(--ui-accent) 72%, transparent);
  background: var(--ui-primary);
  box-shadow: var(--ui-shadow-sm);
  color: var(--ui-on-primary);
  transform: translateY(-1px);
}

.titulacion-refresh-button {
  border-color: color-mix(in srgb, var(--ui-accent) 34%, transparent);
  background: var(--ui-surface);
  box-shadow: none;
  color: var(--ui-accent);
}

.titulacion-search-button:disabled,
.titulacion-refresh-button:disabled {
  border-color: color-mix(in srgb, var(--ui-border-strong) 42%, transparent);
  background: var(--ui-neutral-soft);
  box-shadow: none;
  color: var(--ui-border-strong);
  transform: none;
  cursor: not-allowed;
}

.titulacion-active-students-card {
  padding: 12px;
  overflow: hidden;
}

.titulacion-stats {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.titulacion-aptos-table {
  width: 100%;
  max-width: 100%;
  overflow-x: auto;
  border-radius: var(--ui-radius-panel);
}

.titulacion-aptos-table table {
  width: 100%;
  min-width: 1480px;
  table-layout: fixed;
  border-collapse: separate;
  border-spacing: 0;
}

.titulacion-aptos-table thead th {
  position: sticky;
  top: 0;
  z-index: 2;
  padding: 10px 12px;
  border-bottom: 1px solid color-mix(in srgb, var(--ui-accent-border) 42%, transparent);
  background: var(--ui-accent-soft);
  color: var(--ink);
  font-size: var(--ui-size-13);
  font-weight: var(--ui-weight-bold);
  line-height: 1.2;
  text-align: left;
  vertical-align: bottom;
  white-space: normal;
}

.titulacion-aptos-table tbody td {
  padding: 10px 12px;
  border-bottom: 1px solid color-mix(in srgb, var(--ui-border-strong) 48%, transparent);
  background: color-mix(in srgb, var(--ui-surface) 98%, transparent);
  color: var(--ink);
  font-size: var(--ui-size-14);
  line-height: 1.28;
  vertical-align: middle;
}

.titulacion-aptos-table tbody tr:nth-child(even) td {
  background: var(--ui-surface-alt);
}

.titulacion-aptos-table tbody tr:hover td {
  background: color-mix(in srgb, var(--ui-accent-border) 13%, transparent);
}

.titulacion-aptos-table th:last-child,
.titulacion-aptos-table td:last-child {
  text-align: center;
}

.titulacion-sort-button {
  display: flex;
  width: 100%;
  min-height: 34px;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  border: 0;
  background: transparent;
  color: inherit;
  padding: 0;
  text-align: left;
  font: inherit;
  cursor: pointer;
}

.titulacion-sort-button span {
  min-width: 0;
  overflow-wrap: anywhere;
}

.titulacion-sort-button small {
  flex: 0 0 auto;
  min-width: 46px;
  padding: 3px 6px;
  border: 1px solid color-mix(in srgb, var(--ui-accent) 25%, transparent);
  border-radius: var(--ui-radius-sm);
  background: var(--ui-surface);
  color: var(--ui-accent);
  font-size: var(--ui-size-11);
  font-weight: var(--ui-weight-bold);
  line-height: 1;
  text-align: center;
}

.titulacion-sort-button:hover small,
.titulacion-sort-button:focus-visible small {
  border-color: color-mix(in srgb, var(--ui-accent) 55%, transparent);
  background: var(--ui-accent-soft);
}

.titulacion-col-name {
  width: 19%;
}

.titulacion-col-id {
  width: 10%;
}

.titulacion-col-career {
  width: 17%;
}

.titulacion-col-progress {
  width: 12%;
}

.titulacion-col-english {
  width: 14%;
}

.titulacion-col-hours {
  width: 14%;
}

.titulacion-col-action {
  width: 7%;
}

.titulacion-aptos-table td:nth-child(1),
.titulacion-aptos-table td:nth-child(3) {
  white-space: normal;
  word-break: normal;
}

.titulacion-aptos-table td:nth-child(4),
.titulacion-aptos-table td:nth-child(5),
.titulacion-aptos-table td:nth-child(6),
.titulacion-aptos-table td:nth-child(7) {
  white-space: normal;
}

.titulacion-progress-card {
  overflow: hidden;
}

.titulacion-progress-table td:nth-child(4) {
  min-width: 220px;
}

.titulacion-progress-meter,
.titulacion-mini-progress {
  position: relative;
  overflow: hidden;
  width: 100%;
  height: 10px;
  border-radius: var(--ui-radius-panel);
  background: var(--ui-neutral-soft);
}

.titulacion-progress-meter span,
.titulacion-mini-progress span {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: var(--ui-accent);
}

.titulacion-progress-table td:nth-child(4) strong,
.titulacion-aptos-table td strong {
  display: block;
  margin-top: 6px;
  color: var(--ui-text);
  font-size: var(--ui-size-13);
  font-weight: var(--ui-weight-bold);
  line-height: 1.25;
}

.titulacion-mini-progress {
  width: 100%;
  height: 8px;
}

.titulacion-review-button {
  width: 100%;
  min-height: 34px;
  padding: 0 10px;
  border-color: color-mix(in srgb, var(--ui-accent-border) 65%, transparent);
  background: var(--ui-surface-alt);
  color: var(--ink);
  font-size: var(--ui-size-13);
  font-weight: var(--ui-weight-bold);
}

.titulacion-pagination {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  align-items: center;
  justify-content: space-between;
  padding: 12px 0 0;
}

.titulacion-pagination--top {
  padding-top: 0;
  padding-bottom: 10px;
  border-bottom: 1px solid color-mix(in srgb, var(--ui-border-strong) 58%, transparent);
}

.titulacion-pagination > span,
.titulacion-pagination strong {
  color: var(--ui-text);
  font-size: var(--ui-size-14);
  font-weight: var(--ui-weight-bold);
}

.titulacion-pagination > div {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
  justify-content: flex-end;
}

.titulacion-pagination .secondary-action {
  min-height: 32px;
  padding: 0 12px;
  border-radius: var(--ui-radius-control);
  font-size: var(--ui-size-13);
}

.titulacion-modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 2500;
  display: grid;
  place-items: center;
  padding: 20px;
  background: color-mix(in srgb, var(--ui-text) 42%, transparent);
}

.titulacion-review-modal {
  display: grid;
  gap: 16px;
  width: min(980px, 96vw);
  max-height: 92vh;
  overflow: auto;
  padding: 18px;
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface);
  box-shadow: var(--ui-shadow-dialog);
}

.titulacion-review-summary {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
}

.titulacion-review-summary div {
  display: grid;
  gap: 5px;
  min-width: 0;
  padding: 12px;
  border: 1px solid color-mix(in srgb, var(--ui-text) 10%, transparent);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface-alt);
}

.titulacion-review-summary span,
.titulacion-review-actions span {
  color: var(--ui-chart-neutral);
  font-size: var(--ui-size-12);
  font-weight: var(--ui-weight-bold);
}

.titulacion-review-summary strong {
  min-width: 0;
  overflow-wrap: anywhere;
  color: var(--ui-text);
  font-size: var(--ui-size-16);
}

.titulacion-review-actions {
  display: grid;
  grid-template-columns: minmax(240px, 1fr) auto;
  gap: 12px;
  align-items: end;
}

.titulacion-review-edit {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
  padding: 12px;
  border: 1px solid color-mix(in srgb, var(--ui-text) 10%, transparent);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface-alt);
}

.titulacion-review-edit > strong {
  grid-column: 1 / -1;
  color: var(--ui-text);
}

.titulacion-review-edit label {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--ui-text);
  font-weight: var(--ui-weight-bold);
}

.titulacion-review-actions label {
  display: grid;
  gap: 6px;
}

.status-pill {
  display: inline-flex;
  min-width: 82px;
  min-height: 28px;
  align-items: center;
  justify-content: center;
  border-radius: var(--ui-radius-panel);
  padding: 0 10px;
  font-size: var(--ui-size-12);
  font-weight: var(--ui-weight-bold);
}

.status-pill.is-ok {
  background: var(--ui-success-soft);
  color: var(--ui-success);
}

.status-pill.is-warning {
  background: var(--ui-primary-soft);
  color: var(--ui-primary);
}

.status-pill.is-muted {
  background: var(--ui-background);
  color: var(--ui-text-secondary);
}

.titulacion-start-panel {
  display: grid;
  grid-template-columns: minmax(320px, 1.1fr) minmax(280px, 0.9fr);
  gap: 18px;
  align-items: center;
  padding: 18px;
  border: 1px solid color-mix(in srgb, var(--ui-text) 10%, transparent);
  border-left: 5px solid var(--ui-accent);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface);
  box-shadow: var(--ui-shadow-sm);
}

.titulacion-start-panel div {
  display: grid;
  gap: 8px;
  min-width: 0;
}

.titulacion-start-panel span {
  color: var(--ui-accent);
  font-size: var(--ui-size-12);
  font-weight: var(--ui-weight-bold);
  text-transform: uppercase;
}

.titulacion-start-panel h3 {
  margin: 0;
  color: var(--ui-text);
  font-size: var(--ui-size-18);
}

.titulacion-start-panel p {
  max-width: 760px;
  margin: 0;
  color: var(--ui-text-secondary);
  font-weight: var(--ui-weight-bold);
  line-height: 1.45;
}

.titulacion-start-panel ol {
  display: grid;
  gap: 8px;
  margin: 0;
  padding: 0 0 0 22px;
  color: var(--ui-text);
  font-weight: var(--ui-weight-bold);
}

.titulacion-flow-board {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
}

.titulacion-flow-board--two {
  grid-template-columns: repeat(2, minmax(280px, 1fr));
}

.titulacion-flow-board button {
  display: grid;
  gap: 6px;
  min-width: 0;
  min-height: 104px;
  padding: 14px;
  border: 1px solid color-mix(in srgb, var(--ui-text) 12%, transparent);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface);
  text-align: left;
  cursor: pointer;
}

.titulacion-flow-board button.is-active {
  border-color: color-mix(in srgb, var(--ui-accent) 55%, transparent);
  background: var(--ui-accent-soft);
}

.titulacion-flow-board button.is-locked {
  cursor: not-allowed;
  opacity: 0.58;
}

.titulacion-flow-board span {
  color: var(--ui-text);
  font-size: var(--ui-size-13);
  font-weight: var(--ui-weight-bold);
}

.titulacion-flow-board strong {
  color: var(--ui-text);
  font-size: var(--ui-size-16);
}

.titulacion-flow-board small {
  color: var(--ui-chart-neutral);
  font-weight: var(--ui-weight-bold);
  line-height: 1.35;
}

.titulacion-area-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  padding: 6px;
  border: 1px solid color-mix(in srgb, var(--ui-text) 10%, transparent);
  border-radius: var(--ui-radius-panel);
  background: color-mix(in srgb, var(--ui-surface) 82%, transparent);
}

.titulacion-area-tabs button {
  min-height: 38px;
  border: 0;
  border-radius: var(--ui-radius-panel);
  padding: 0 14px;
  background: transparent;
  color: var(--ui-text);
  font-weight: var(--ui-weight-bold);
  cursor: pointer;
}

.titulacion-area-tabs button.is-active {
  background: var(--ui-accent);
  color: var(--ui-on-primary);
}

.titulacion-area-tabs button:disabled {
  cursor: not-allowed;
  opacity: 0.5;
}

.titulacion-prereq-list {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
  margin-bottom: 14px;
}

.titulacion-prereq-list > div {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 6px 10px;
  align-items: center;
  min-width: 0;
  padding: 14px;
  border: 1px solid color-mix(in srgb, var(--ui-text) 10%, transparent);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface-alt);
}

.titulacion-prereq-list > div.is-ok {
  border-color: color-mix(in srgb, var(--ui-accent) 32%, transparent);
  background: var(--ui-accent-soft);
}

.titulacion-prereq-list > div.is-warning {
  border-color: color-mix(in srgb, var(--ui-primary) 26%, transparent);
  background: var(--ui-danger-soft);
}

.titulacion-prereq-list strong {
  grid-row: span 2;
  min-width: 76px;
  color: var(--ui-text);
  font-size: var(--ui-size-13);
  font-weight: var(--ui-weight-bold);
}

.titulacion-prereq-list span {
  min-width: 0;
  color: var(--ui-text);
  font-weight: var(--ui-weight-bold);
}

.titulacion-prereq-list small {
  min-width: 0;
  color: var(--ui-chart-neutral);
  font-weight: var(--ui-weight-bold);
}

.titulacion-prereq-list label {
  grid-column: 2;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--ui-text);
  font-weight: var(--ui-weight-bold);
}

.titulacion-action-row {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-bottom: 16px;
}

.titulacion-action-row button {
  min-height: 42px;
}

.titulacion-checklist {
  display: grid;
  gap: 10px;
}

.titulacion-compare {
  display: grid;
  gap: 10px;
  margin-bottom: 14px;
}

.titulacion-compare-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
}

.titulacion-compare-head strong {
  color: var(--ui-text);
}

.titulacion-compare-head span {
  color: var(--ui-chart-neutral);
  font-size: var(--ui-size-13);
  font-weight: var(--ui-weight-bold);
}

.titulacion-compare-table {
  display: grid;
  overflow: hidden;
  border: 1px solid color-mix(in srgb, var(--ui-text) 10%, transparent);
  border-radius: var(--ui-radius-panel);
}

.titulacion-compare-table div {
  display: grid;
  grid-template-columns: minmax(120px, 0.8fr) minmax(0, 1.1fr) minmax(0, 1.1fr) auto;
  gap: 10px;
  align-items: center;
  padding: 9px 10px;
  border-bottom: 1px solid color-mix(in srgb, var(--ui-text) 8%, transparent);
  background: var(--ui-surface);
}

.titulacion-compare-table div:last-child {
  border-bottom: 0;
}

.titulacion-compare-table span {
  color: var(--ui-text-secondary);
  font-size: var(--ui-size-12);
  font-weight: var(--ui-weight-bold);
}

.titulacion-compare-table strong {
  min-width: 0;
  overflow-wrap: anywhere;
  color: var(--ui-text);
  font-size: var(--ui-size-13);
}

.titulacion-compare-table em {
  justify-self: end;
  min-width: 62px;
  border-radius: var(--ui-radius-panel);
  padding: 4px 8px;
  text-align: center;
  font-size: var(--ui-size-12);
  font-style: normal;
  font-weight: var(--ui-weight-bold);
}

.titulacion-compare-table .is-ok em {
  background: var(--ui-success-soft);
  color: var(--ui-success);
}

.titulacion-compare-table .is-warning em {
  background: var(--ui-warning-soft);
  color: var(--ui-warning);
}

.titulacion-checklist label,
.titulacion-fixed-check {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  min-height: 44px;
  padding: 10px 12px;
  border: 1px solid color-mix(in srgb, var(--ui-text) 11%, transparent);
  border-radius: var(--ui-radius-panel);
  background: color-mix(in srgb, var(--ui-surface-alt) 84%, transparent);
  color: var(--ui-text);
  font-weight: var(--ui-weight-bold);
}

.titulacion-checklist label {
  justify-content: flex-start;
}

.titulacion-checklist input[type='checkbox'] {
  width: 18px;
  height: 18px;
  accent-color: var(--ui-accent);
}

.titulacion-fixed-check strong {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 82px;
  min-height: 28px;
  border-radius: var(--ui-radius-panel);
  background: var(--ui-accent-soft);
  color: var(--ui-accent);
  font-size: var(--ui-size-12);
}

.titulacion-notes-form {
  grid-template-columns: repeat(2, minmax(0, 1fr));
  align-items: end;
}

.titulacion-final-grade {
  display: grid;
  gap: 4px;
  padding: 10px 12px;
  border-radius: var(--ui-radius-panel);
  border: 1px solid color-mix(in srgb, var(--ui-accent) 20%, transparent);
  background: var(--ui-info-soft);
}

.titulacion-final-grade span {
  color: var(--ui-text-secondary);
  font-size: var(--ui-size-13);
  font-weight: var(--ui-weight-bold);
}

.titulacion-final-grade strong {
  color: var(--ui-text);
  font-size: var(--ui-size-20);
}

.titulacion-doc-form {
  grid-template-columns: minmax(180px, 0.8fr) minmax(240px, 1fr) minmax(220px, 1fr) auto;
  align-items: end;
}

.titulacion-doc-table {
  margin-top: 16px;
}

.titulacion-mechanism-card {
  display: grid;
  gap: 16px;
}

.titulacion-process-summary {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
  padding: 12px;
  border: 1px solid color-mix(in srgb, var(--ui-accent-border) 42%, transparent);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface-alt);
}

.titulacion-process-summary div {
  display: grid;
  gap: 5px;
  min-width: 0;
}

.titulacion-process-summary span {
  color: var(--ui-chart-neutral);
  font-size: var(--ui-size-12);
  font-weight: var(--ui-weight-bold);
}

.titulacion-process-summary strong {
  color: var(--ink);
  font-size: var(--ui-size-16);
}

.titulacion-process-summary .secondary-action {
  display: inline-flex;
  width: max-content;
  min-height: 34px;
  align-items: center;
  justify-content: center;
  padding: 7px 12px;
  text-decoration: none;
}

.titulacion-mechanism-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
  align-items: end;
}

.titulacion-mechanism-grid label {
  display: grid;
  gap: 6px;
  min-width: 0;
}

.titulacion-mechanism-grid label span {
  color: var(--ui-text);
  font-size: var(--ui-size-12);
  font-weight: var(--ui-weight-bold);
}

.titulacion-mechanism-grid input,
.titulacion-mechanism-grid select {
  width: 100%;
  min-width: 0;
  min-height: 42px;
  border: 1px solid color-mix(in srgb, var(--ui-text) 14%, transparent);
  border-radius: var(--ui-radius-panel);
  padding: 0 12px;
  color: var(--ui-text);
  background: var(--ui-surface);
}

.titulacion-span-2 {
  grid-column: span 2;
}

.titulacion-topic-suggestions {
  display: grid;
  gap: 8px;
}

.titulacion-topic-suggestions > span {
  color: var(--ui-text);
  font-size: var(--ui-size-12);
  font-weight: var(--ui-weight-bold);
}

.titulacion-topic-suggestions > div {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.titulacion-topic-suggestions .secondary-action {
  min-height: 34px;
  padding: 7px 10px;
  font-size: var(--ui-size-12);
}

.titulacion-subpanel {
  display: grid;
  gap: 12px;
  padding-top: 14px;
  border-top: 1px solid color-mix(in srgb, var(--ui-text) 10%, transparent);
}

.titulacion-process-setup-panel {
  padding: 16px;
  border: 1px solid color-mix(in srgb, var(--ui-accent) 22%, transparent);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface);
}

.titulacion-responsables-panel {
  padding: 16px;
  border: 1px solid color-mix(in srgb, var(--ui-border-strong) 34%, transparent);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface);
}

.titulacion-responsables-layout {
  display: grid;
  grid-template-columns: minmax(360px, 0.85fr) minmax(420px, 1.15fr);
  gap: 16px;
  align-items: start;
}

.titulacion-responsables-form,
.titulacion-responsables-list {
  min-width: 0;
  display: grid;
  gap: 10px;
}

.titulacion-responsables-form {
  padding: 14px;
  border: 1px solid color-mix(in srgb, var(--ui-accent) 18%, transparent);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface-alt);
}

.titulacion-responsables-table {
  max-height: none;
  border-radius: var(--ui-radius-panel);
}

.titulacion-responsables-table table {
  min-width: 760px;
}

.titulacion-responsables-table th {
  background: var(--ui-accent-soft);
  white-space: nowrap;
}

.titulacion-responsables-table td {
  vertical-align: top;
}

.titulacion-empty-state {
  min-height: 92px;
  display: grid;
  place-items: center;
  border: 1px dashed color-mix(in srgb, var(--ui-border-strong) 50%, transparent);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface-alt);
  color: var(--ui-chart-neutral);
  font-size: var(--ui-size-14);
  font-weight: var(--ui-weight-bold);
}

.titulacion-empty-state--large {
  min-height: 132px;
  padding: 18px;
  text-align: center;
}

.titulacion-info-note {
  padding: 10px 12px;
  border: 1px solid color-mix(in srgb, var(--ui-accent-border) 65%, transparent);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-accent-soft);
  color: var(--ui-muted);
  font-size: var(--ui-size-13);
  font-weight: var(--ui-weight-bold);
}

.titulacion-subpanel .card-head {
  margin-bottom: 0;
}

.titulacion-chip-list {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.titulacion-chip-list span,
.titulacion-chip-list small {
  display: inline-flex;
  align-items: center;
  min-height: 30px;
  padding: 6px 10px;
  border-radius: var(--ui-radius-panel);
  background: var(--ui-accent-soft);
  color: var(--ui-text);
  font-size: var(--ui-size-13);
  font-weight: var(--ui-weight-bold);
}

.titulacion-generation-card {
  display: grid;
  gap: 16px;
}

.titulacion-generation-summary {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
}

.titulacion-generation-summary div {
  display: grid;
  gap: 6px;
  min-width: 0;
  padding: 12px;
  border: 1px solid color-mix(in srgb, var(--ui-text) 10%, transparent);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface-alt);
}

.titulacion-generation-summary span {
  color: var(--ui-chart-neutral);
  font-size: var(--ui-size-12);
  font-weight: var(--ui-weight-bold);
}

.titulacion-generation-summary strong {
  min-width: 0;
  overflow-wrap: anywhere;
  color: var(--ui-text);
  font-size: var(--ui-size-16);
}

.titulacion-prevalidation p {
  margin: 0 0 14px;
  color: var(--ui-text);
  font-weight: var(--ui-weight-bold);
}

@media (max-width: 1180px) {
  .titulacion-stats {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .titulacion-flow-board {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .titulacion-flow-board--two {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .titulacion-generation-summary {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .titulacion-search-form,
  .titulacion-doc-form,
  .titulacion-mechanism-grid,
  .titulacion-prereq-list {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .titulacion-grid--split {
    grid-template-columns: minmax(0, 1fr);
  }

  .titulacion-start-panel {
    grid-template-columns: minmax(0, 1fr);
  }

  .titulacion-review-summary,
  .titulacion-review-actions,
  .titulacion-review-edit {
    grid-template-columns: minmax(0, 1fr);
  }

  .titulacion-pagination,
  .titulacion-pagination > div {
    justify-content: stretch;
  }
}

@media (max-width: 720px) {
  .titulacion-page {
    gap: 14px;
  }

  .titulacion-hero aside {
    min-width: 0;
  }

  .titulacion-stats,
  .titulacion-generation-summary,
  .titulacion-flow-board,
  .titulacion-flow-board--two,
  .titulacion-search-form,
  .titulacion-doc-form,
  .titulacion-notes-form,
  .titulacion-mechanism-grid,
  .titulacion-prereq-list {
    grid-template-columns: minmax(0, 1fr);
  }

  .titulacion-pagination .secondary-action {
    flex: 1 1 120px;
  }

  .titulacion-search-form .primary-action,
  .titulacion-search-form .secondary-action,
  .titulacion-doc-form .primary-action,
  .titulacion-notes-form .primary-action,
  .titulacion-mechanism-grid .primary-action,
  .titulacion-mechanism-grid .secondary-action {
    width: 100%;
  }

  .titulacion-span-2 {
    grid-column: auto;
  }

  .titulacion-compare-head {
    align-items: flex-start;
    flex-direction: column;
  }

  .titulacion-compare-table div {
    grid-template-columns: minmax(0, 1fr);
  }

  .titulacion-compare-table em {
    justify-self: start;
  }

  .titulacion-checklist label,
  .titulacion-fixed-check {
    align-items: flex-start;
  }
}

/* Practicas institucionales */

.practicas-page {
  width: min(1180px, calc(100vw - 28px));
  margin: 0 auto;
}

.practicas-hero {
  min-height: 0;
}

.practicas-controls {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 12px;
  align-items: center;
}

.practicas-process-tabs {
  margin: 0;
}

/* Creación controlada de oferta académica desde plantillas Moodle. */

.moodle-course-cloning .moodle-section__heading p {
  max-width: 860px;
  margin: 7px 0 0;
  color: var(--ui-text-secondary);
}

.moodle-cloning-step,
.moodle-cloning-review,
.moodle-cloning-result {
  margin-top: 16px;
  overflow: hidden;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface);
}

.moodle-cloning-step__heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  min-height: 68px;
  padding: 13px 16px;
  border-bottom: 1px solid var(--ui-border);
  background: var(--ui-surface-alt);
}

.moodle-cloning-step__heading > div {
  min-width: 0;
}

.moodle-cloning-step__heading span:not(.moodle-cloning-status) {
  display: block;
  color: var(--ui-chart-neutral);
  font-size: var(--ui-size-11);
  font-weight: var(--ui-weight-bold);
  text-transform: uppercase;
}

.moodle-cloning-step__heading h3 {
  margin: 4px 0 0;
  overflow-wrap: anywhere;
  font-size: var(--ui-size-18);
}

.moodle-cloning-type {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  margin: 14px 16px 0;
  overflow: hidden;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-panel);
}

.moodle-cloning-type button {
  display: grid;
  min-height: 58px;
  place-content: center;
  gap: 3px;
  padding: 8px 14px;
  border: 0;
  border-right: 1px solid var(--ui-border);
  border-radius: 0;
  background: var(--ui-surface);
  color: var(--ui-text);
  font: inherit;
  font-weight: var(--ui-weight-bold);
  cursor: pointer;
}

.moodle-cloning-type button:last-child {
  border-right: 0;
}

.moodle-cloning-type button.is-active {
  background: var(--ui-neutral-soft);
  color: var(--ui-accent-hover);
  box-shadow: inset 0 -3px 0 var(--ui-accent);
}

.moodle-cloning-type small {
  color: var(--ui-chart-neutral);
  font-size: var(--ui-size-11);
}

.moodle-cloning-filters {
  display: grid;
  grid-template-columns: minmax(150px, 0.6fr) minmax(190px, 0.8fr) minmax(260px, 1.4fr) auto;
  align-items: end;
  gap: 10px;
  padding: 14px 16px;
}

.moodle-cloning-filters label,
.moodle-cloning-destination-fields label {
  display: grid;
  min-width: 0;
  gap: 6px;
}

.moodle-cloning-filters label > span,
.moodle-cloning-destination-fields label > span,
.moodle-cloning-route-example > span {
  color: var(--ui-chart-neutral);
  font-size: var(--ui-size-12);
  font-weight: var(--ui-weight-bold);
}

.moodle-cloning-filters input,
.moodle-cloning-filters select,
.moodle-cloning-destination-fields input {
  width: 100%;
  min-width: 0;
  min-height: 42px;
  padding: 8px 11px;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface);
  color: var(--ui-text);
  font: inherit;
}

.moodle-cloning-filters input:focus,
.moodle-cloning-filters select:focus,
.moodle-cloning-destination-fields input:focus {
  border-color: var(--ui-accent);
  outline: 3px solid color-mix(in srgb, var(--ui-accent) 12%, transparent);
}

.moodle-cloning-filter-actions {
  display: flex;
  gap: 8px;
}

.moodle-cloning-template-list {
  display: grid;
  max-height: 390px;
  overflow-y: auto;
  border-top: 1px solid var(--ui-border);
}

.moodle-cloning-template-list > label {
  display: grid;
  grid-template-columns: auto minmax(220px, 0.9fr) minmax(280px, 1.2fr);
  align-items: center;
  gap: 12px;
  min-height: 68px;
  padding: 10px 16px;
  border-bottom: 1px solid var(--ui-neutral-soft);
  background: var(--ui-surface);
  cursor: pointer;
}

.moodle-cloning-template-list > label:last-of-type {
  border-bottom: 0;
}

.moodle-cloning-template-list > label.is-selected {
  background: var(--ui-accent-soft);
  box-shadow: inset 4px 0 var(--ui-accent);
}

.moodle-cloning-template-list input {
  width: 18px;
  height: 18px;
  margin: 0;
  accent-color: var(--ui-accent);
}

.moodle-cloning-template-list label > span {
  display: grid;
  min-width: 0;
  gap: 3px;
}

.moodle-cloning-template-list strong,
.moodle-cloning-template-list b,
.moodle-cloning-template-list small {
  overflow-wrap: anywhere;
}

.moodle-cloning-template-list b {
  color: var(--ui-text);
  font-size: var(--ui-size-13);
}

.moodle-cloning-template-list small,
.moodle-cloning-destination-fields small,
.moodle-cloning-plan-list small {
  color: var(--ui-chart-neutral);
  font-size: var(--ui-size-12);
  line-height: 1.35;
}

.moodle-cloning-destination-fields {
  display: grid;
  grid-template-columns: repeat(4, minmax(180px, 1fr));
  gap: 12px;
  padding: 16px;
}

.moodle-cloning-route-example {
  display: grid;
  gap: 5px;
  margin: 0 16px 16px;
  padding: 11px 13px;
  border-left: 4px solid var(--ui-accent);
  background: var(--ui-accent-soft);
}

.moodle-cloning-route-example strong {
  overflow-wrap: anywhere;
  color: var(--ui-text);
  font-size: var(--ui-size-13);
}

.moodle-cloning-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 16px;
  margin-top: 16px;
  padding: 12px 14px;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface-alt);
}

.moodle-cloning-actions > span {
  margin-right: auto;
  color: var(--ui-muted);
  font-size: var(--ui-size-13);
  font-weight: var(--ui-weight-bold);
}

.moodle-cloning-summary {
  display: grid;
  grid-template-columns: repeat(5, minmax(110px, 1fr));
  border-bottom: 1px solid var(--ui-border);
}

.moodle-cloning-summary > div {
  display: grid;
  min-height: 72px;
  align-content: center;
  gap: 4px;
  padding: 10px 14px;
  border-right: 1px solid var(--ui-border);
}

.moodle-cloning-summary > div:last-child {
  border-right: 0;
}

.moodle-cloning-summary span {
  color: var(--ui-chart-neutral);
  font-size: var(--ui-size-11);
  font-weight: var(--ui-weight-bold);
  text-transform: uppercase;
}

.moodle-cloning-summary strong {
  font-size: var(--ui-size-18);
}

.moodle-cloning-review-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.moodle-cloning-review-grid > div {
  min-width: 0;
  padding: 16px;
  border-right: 1px solid var(--ui-border);
}

.moodle-cloning-review-grid > div:last-child {
  border-right: 0;
}

.moodle-cloning-review-grid h4 {
  margin: 0 0 10px;
}

.moodle-cloning-plan-list {
  display: grid;
  max-height: 320px;
  overflow-y: auto;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-panel);
}

.moodle-cloning-result > .moodle-cloning-plan-list {
  margin: 16px;
}

.moodle-cloning-plan-list > div {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  gap: 4px 10px;
  min-height: 54px;
  padding: 9px 10px;
  border-bottom: 1px solid var(--ui-neutral-soft);
}

.moodle-cloning-plan-list > div:last-child {
  border-bottom: 0;
}

.moodle-cloning-plan-list strong,
.moodle-cloning-plan-list small {
  min-width: 0;
  overflow-wrap: anywhere;
}

.moodle-cloning-plan-list small {
  grid-column: 2;
}

.moodle-cloning-status {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 26px;
  padding: 4px 8px;
  border: 1px solid var(--ui-border-strong);
  border-radius: var(--ui-radius-control);
  background: var(--ui-background);
  color: var(--ui-text-secondary);
  font-size: var(--ui-size-11);
  font-weight: var(--ui-weight-bold);
  white-space: nowrap;
}

.moodle-cloning-status.is-success {
  border-color: var(--ui-success-border);
  background: var(--ui-success-soft);
  color: var(--ui-success);
}

.moodle-cloning-status.is-warning,
.moodle-cloning-status.is-pending {
  border-color: var(--ui-warning-border);
  background: var(--ui-warning-soft);
  color: var(--ui-warning);
}

.moodle-cloning-status.is-error {
  border-color: var(--ui-primary-border);
  background: var(--ui-danger-soft);
  color: var(--ui-primary);
}

@media (max-width: 1100px) {
  .moodle-cloning-filters,
  .moodle-cloning-destination-fields {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .moodle-cloning-filter-actions {
    align-self: stretch;
  }

  .moodle-cloning-filter-actions .moodle-button {
    flex: 1;
  }
}

@media (max-width: 720px) {
  .moodle-course-cloning {
    padding: 14px;
  }

  .moodle-course-cloning .moodle-section__heading,
  .moodle-cloning-step__heading,
  .moodle-cloning-actions {
    align-items: stretch;
    flex-direction: column;
  }

  .moodle-course-cloning .moodle-section__heading .moodle-button,
  .moodle-cloning-actions .moodle-button {
    width: 100%;
  }

  .moodle-cloning-filters,
  .moodle-cloning-destination-fields,
  .moodle-cloning-review-grid,
  .moodle-cloning-summary {
    grid-template-columns: 1fr;
  }

  .moodle-cloning-template-list > label {
    grid-template-columns: auto minmax(0, 1fr);
  }

  .moodle-cloning-template-list > label > span:last-child {
    grid-column: 2;
  }

  .moodle-cloning-review-grid > div,
  .moodle-cloning-summary > div {
    border-right: 0;
    border-bottom: 1px solid var(--ui-border);
  }

  .moodle-cloning-review-grid > div:last-child,
  .moodle-cloning-summary > div:last-child {
    border-bottom: 0;
  }
}

.practicas-process-selector {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
  margin-top: 14px;
}

.practicas-process-selector button,
.practicas-workspace-tabs button {
  display: grid;
  align-content: start;
  gap: 5px;
  min-width: 0;
  min-height: 92px;
  padding: 13px 15px;
  border: 1px solid var(--line-strong);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface);
  color: var(--ink);
  text-align: left;
  cursor: pointer;
}

.practicas-process-selector button:hover,
.practicas-workspace-tabs button:hover {
  border-color: var(--celeste-strong);
  background: var(--ui-surface-alt);
}

.practicas-process-selector button:focus-visible,
.practicas-workspace-tabs button:focus-visible {
  outline: 3px solid color-mix(in srgb, var(--ui-accent) 20%, transparent);
  outline-offset: 2px;
}

.practicas-process-selector button.is-active,
.practicas-workspace-tabs button.is-active {
  border-color: var(--celeste-strong);
  box-shadow: inset 4px 0 0 var(--celeste-strong);
  background: var(--ui-accent-soft);
}

.practicas-process-selector button > span {
  color: var(--celeste-strong);
  font-size: var(--ui-size-12);
  font-weight: var(--ui-weight-bold);
  letter-spacing: 0;
}

.practicas-process-selector button > strong,
.practicas-workspace-tabs button > strong {
  overflow-wrap: anywhere;
  font-size: var(--ui-size-16);
  line-height: 1.25;
}

.practicas-process-selector button > small,
.practicas-workspace-tabs button > small {
  color: var(--ink-soft);
  font-size: var(--ui-size-12);
  line-height: 1.4;
}

.practicas-workspace-tabs {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 10px;
  margin-top: 14px;
}

.practicas-workspace-tabs button {
  min-height: 82px;
}

.practicas-summary {
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
}

.practicas-summary article {
  display: grid;
  gap: 6px;
  min-width: 0;
}

.practicas-summary span {
  color: var(--ink-soft);
  font-size: var(--ui-size-12);
  font-weight: var(--ui-weight-bold);
  letter-spacing: 0;
  text-transform: uppercase;
}

.practicas-summary strong {
  color: var(--ink);
  font-size: var(--ui-size-28);
}

.practicas-summary p {
  margin: 0;
}

.practicas-enrollment-boundary {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  margin-top: 14px;
  overflow: hidden;
  border: 1px solid color-mix(in srgb, var(--ui-accent-border) 68%, transparent);
  border-left: 4px solid var(--celeste-strong);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface-alt);
}

.practicas-enrollment-boundary > div {
  min-width: 0;
  padding: 12px 14px;
}

.practicas-enrollment-boundary > div + div {
  border-left: 1px solid color-mix(in srgb, var(--ui-accent-border) 48%, transparent);
