.app--auth {
  position: relative;
  background: var(--ui-surface);
  overflow: hidden;
}

.auth-scene {
  min-height: 100vh;
  min-height: 100dvh;
  display: grid;
  place-items: center;
  padding: 0;
  position: relative;
}

.star-layer {
  position: absolute;
  inset: 0;
  background-image: none;
  animation: drift 18s linear infinite;
}

.planet {
  position: absolute;
  border-radius: 50%;
  pointer-events: none;
}

.planet--main {
  width: 460px;
  height: 460px;
  left: -130px;
  top: -120px;
  background: var(--ui-surface);
  box-shadow: inset -30px -30px 70px color-mix(in srgb, var(--ui-text) 22%, transparent), 0 0 90px color-mix(in srgb, var(--ui-accent-border) 45%, transparent);
}

.planet--small {
  width: 170px;
  height: 170px;
  left: 320px;
  top: 230px;
  background: var(--ui-surface);
  box-shadow: var(--ui-shadow-sm);
}

.planet--tiny {
  width: 70px;
  height: 70px;
  left: 80px;
  bottom: 130px;
  background: var(--ui-surface);
  opacity: 0.85;
}

.shooting {
  position: absolute;
  width: 180px;
  height: 2px;
  background: var(--ui-surface);
  transform: rotate(-35deg);
  filter: drop-shadow(0 0 10px color-mix(in srgb, var(--ui-surface) 80%, transparent));
  animation: shoot 6s ease-in-out infinite;
}

.shooting--one {
  top: 100px;
  left: 45%;
}

.shooting--two {
  top: 380px;
  left: 18%;
  animation-delay: 2.4s;
}

.auth-frame {
  width: 100%;
  min-height: 100vh;
  min-height: 100dvh;
  border-radius: 0;
  overflow: hidden;
  border: none;
  box-shadow: none;
  position: relative;
  z-index: 2;
}

.auth-layout {
  display: grid;
  grid-template-columns: 1.2fr 0.8fr;
  min-height: 100vh;
  min-height: 100dvh;
}

.showcase-panel {
  padding: clamp(20px, 3.2vw, 36px);
  display: flex;
  flex-direction: column;
  justify-content: center;
  color: var(--blanco);
  background: var(--ui-surface);
}

.showcase-copy h1 {
  margin: 0;
  max-width: 480px;
  font-size: var(--ui-size-40);
  line-height: 1;
  letter-spacing: 0;
  text-transform: uppercase;
}

.showcase-copy h1 span {
  color: var(--celeste);
}

.showcase-copy p {
  max-width: 430px;
  margin: 18px 0 0;
  color: color-mix(in srgb, var(--ui-surface) 82%, transparent);
  font-size: var(--ui-size-14);
  line-height: 1.55;
}

.eyebrow {
  display: block;
  font-size: var(--ui-size-11);
  letter-spacing: 0;
  opacity: 0.75;
  text-transform: uppercase;
}

.login-panel {
  background: color-mix(in srgb, var(--ui-chart-neutral) 85%, transparent);
  color: var(--blanco);
  display: grid;
  place-items: center;
  min-width: 0;
}

.login-panel__inner {
  width: min(440px, 88%);
  max-width: 100%;
}

.login-panel h2 {
  margin: 0;
  font-size: var(--ui-size-40);
  line-height: 0.95;
  letter-spacing: 0;
  color: var(--blanco);
}

.login-copy {
  margin-top: 16px;
  margin-bottom: 26px;
  font-size: var(--ui-size-14);
  color: color-mix(in srgb, var(--ui-surface) 90%, transparent);
}

.login-form {
  display: grid;
  gap: 14px;
  width: 100%;
  max-width: 100%;
  box-sizing: border-box;
}

.profile-selection {
  display: grid;
  gap: 12px;
  width: 100%;
}

.profile-selection__summary {
  margin: 0 0 2px;
  color: color-mix(in srgb, var(--ui-surface) 82%, transparent);
  font-size: var(--ui-size-13);
  line-height: 1.45;
}

.profile-option {
  width: 100%;
  min-height: 76px;
  display: grid;
  grid-template-columns: 46px minmax(0, 1fr) 20px;
  align-items: center;
  gap: 13px;
  padding: 12px 14px;
  border: 1px solid color-mix(in srgb, var(--ui-surface) 30%, transparent);
  border-radius: var(--ui-radius-panel);
  background: color-mix(in srgb, var(--ui-surface) 8%, transparent);
  color: var(--blanco);
  text-align: left;
  cursor: pointer;
  transition: border-color 160ms ease, background-color 160ms ease, transform 160ms ease;
}

.profile-option:hover:not(:disabled),
.profile-option:focus-visible {
  border-color: color-mix(in srgb, var(--ui-surface) 70%, transparent);
  background: color-mix(in srgb, var(--ui-surface) 15%, transparent);
  transform: translateY(-1px);
}

.profile-option:focus-visible {
  outline: 2px solid var(--celeste);
  outline-offset: 2px;
}

.profile-option:disabled,
.profile-logout:disabled {
  cursor: wait;
  opacity: 0.6;
}

.profile-option__icon {
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: var(--rojo);
  border: 1px solid color-mix(in srgb, var(--ui-surface) 45%, transparent);
  font-size: var(--ui-size-16);
  font-weight: var(--ui-weight-bold);
}

.profile-option__copy {
  min-width: 0;
  display: grid;
  gap: 4px;
}

.profile-option__copy strong {
  font-size: var(--ui-size-16);
  line-height: 1.2;
}

.profile-option__copy small {
  color: color-mix(in srgb, var(--ui-surface) 78%, transparent);
  font-size: var(--ui-size-12);
  line-height: 1.35;
}

.profile-option__copy > span {
  color: color-mix(in srgb, var(--ui-surface) 68%, transparent);
  font-size: var(--ui-size-11);
  line-height: 1.3;
}

.profile-option__arrow {
  font-size: var(--ui-size-28);
  line-height: 1;
  text-align: right;
}

.profile-logout {
  min-height: 42px;
  border: 1px solid color-mix(in srgb, var(--ui-surface) 28%, transparent);
  border-radius: var(--ui-radius-panel);
  background: transparent;
  color: var(--blanco);
  font-weight: var(--ui-weight-bold);
  cursor: pointer;
}

.profile-logout:hover:not(:disabled),
.profile-logout:focus-visible {
  background: color-mix(in srgb, var(--ui-surface) 10%, transparent);
}

.auth-status-actions {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
  margin-top: 14px;
}

.field {
  display: grid;
  gap: 7px;
  min-width: 0;
}

.field span {
  font-size: var(--ui-size-12);
  font-weight: var(--ui-weight-medium);
  letter-spacing: 0;
  color: var(--blanco);
}

.field input,
.password-shell input {
  width: 100%;
  border: 1px solid color-mix(in srgb, var(--ui-surface) 25%, transparent);
  border-radius: var(--ui-radius-panel);
  padding: 12px 14px;
  font-size: var(--ui-size-14);
  color: var(--blanco);
  background: color-mix(in srgb, var(--ui-surface) 8%, transparent);
  box-sizing: border-box;
}

.field input::placeholder,
.password-shell input::placeholder {
  color: color-mix(in srgb, var(--ui-surface) 75%, transparent);
}

.password-shell {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 10px;
  min-width: 0;
  width: 100%;
  box-sizing: border-box;
}

.password-toggle {
  border: none;
  border-radius: var(--ui-radius-panel);
  padding: 0 12px;
  font-size: var(--ui-size-12);
  font-weight: var(--ui-weight-bold);
  color: var(--blanco);
  background: var(--rojo);
  cursor: pointer;
}

.submit-button {
  border: none;
  border-radius: var(--ui-radius-panel);
  padding: 12px 16px;
  margin-top: 4px;
  font-size: var(--ui-size-24);
  font-weight: var(--ui-weight-medium);
  color: var(--blanco);
  cursor: pointer;
  background: var(--ui-primary);
}

.submit-button:disabled {
  opacity: 0.75;
  cursor: wait;
}

.public-evaluation-button {
  border: 1px solid color-mix(in srgb, var(--ui-accent-border) 75%, transparent);
  border-radius: var(--ui-radius-panel);
  padding: 12px 16px;
  color: var(--blanco);
  background: color-mix(in srgb, var(--ui-surface) 8%, transparent);
  cursor: pointer;
  font-size: var(--ui-size-14);
  font-weight: var(--ui-weight-bold);
}

.public-evaluation-button:hover,
.public-evaluation-button:focus-visible {
  border-color: var(--celeste);
  background: color-mix(in srgb, var(--ui-accent-border) 20%, transparent);
}

.error-banner {
  margin: 0;
  padding: 8px 10px;
  border-radius: var(--ui-radius-panel);
  font-size: var(--ui-size-13);
  color: var(--blanco);
  background: color-mix(in srgb, var(--ui-primary) 65%, transparent);
}

.app--dashboard {
  padding: 8px;
  background: var(--ui-surface);
}

.student-shell {
  width: 100%;
  margin: 0;
  display: grid;
  grid-template-columns: 315px minmax(0, 1fr);
  gap: 10px;
}

.student-shell--wide {
  width: 100%;
}

.student-sidebar {
  position: sticky;
  top: 8px;
  max-height: calc(100vh - 16px);
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--ui-radius-panel);
  padding: 12px;
  display: grid;
  grid-template-rows: auto 1fr;
  gap: 12px;
  box-shadow: var(--ui-shadow-sm);
}

.student-sidebar__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  min-width: 0;
}

.student-sidebar__panel {
  min-height: 0;
  display: grid;
  grid-template-rows: auto 1fr auto;
  gap: 12px;
  overflow: hidden;
}

.student-mobile-menu-button,
.student-mobile-menu-backdrop {
  display: none;
}

.student-brand {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}

.student-brand__logo {
  width: 36px;
  height: 36px;
  border-radius: var(--ui-radius-panel);
  background: var(--ui-primary);
  color: var(--blanco);
  font-weight: var(--ui-weight-bold);
  display: grid;
  place-items: center;
  box-shadow: var(--ui-shadow-sm);
}

.student-brand strong {
  display: block;
  font-size: var(--ui-size-18);
  color: var(--ink);
}

.student-brand span {
  font-size: var(--ui-size-12);
  color: var(--gris-oscuro);
}

.student-nav {
  display: grid;
  gap: 8px;
  align-content: start;
  min-height: 0;
  overflow: auto;
  padding-right: 4px;
}

.student-nav__section {
  display: grid;
  gap: 6px;
}

.student-nav__group-title {
  margin: 12px 10px 0;
  color: var(--ui-disabled-text);
  font-size: var(--ui-size-11);
  font-weight: var(--ui-weight-bold);
  letter-spacing: 0;
  text-transform: uppercase;
}

.student-nav__group-title:first-child {
  margin-top: 0;
}

.student-nav__group-button {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
  border: 1px solid var(--line);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-primary);
  color: var(--ink);
  cursor: pointer;
  padding: 10px 12px;
  text-align: left;
  font-size: var(--ui-size-13);
  font-weight: var(--ui-weight-bold);
  box-shadow: var(--ui-shadow-sm);
  transition: border-color 160ms ease, background 160ms ease, transform 160ms ease;
}

.student-nav__group-button:hover {
  border-color: var(--line-strong);
  background: var(--ui-surface);
  transform: translateY(-1px);
}

.student-nav__group-copy {
  display: grid;
  gap: 3px;
  min-width: 0;
}

.student-nav__group-copy strong,
.student-nav__group-copy small {
  display: block;
}

.student-nav__group-copy strong {
  font-size: var(--ui-size-13);
}

.student-nav__group-copy small {
  color: var(--ui-chart-neutral);
  font-size: var(--ui-size-11);
  font-weight: var(--ui-weight-medium);
  line-height: 1.3;
}

.student-nav__group-meta {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  color: var(--ui-chart-neutral);
  font-size: var(--ui-size-11);
  font-weight: var(--ui-weight-bold);
  white-space: nowrap;
}

.student-nav__group-meta b {
  font-size: var(--ui-size-14);
}

.student-nav__group-button--active {
  border-color: color-mix(in srgb, var(--ui-primary) 36%, transparent);
  color: var(--rojo);
  background: var(--ui-primary);
  box-shadow: inset 4px 0 0 color-mix(in srgb, var(--ui-primary) 72%, transparent), var(--card-shadow-soft);
}

.student-nav__group-button--active .student-nav__group-copy small,
.student-nav__group-button--active .student-nav__group-meta {
  color: var(--ui-danger);
}

.student-nav__submenu {
  display: grid;
  gap: 4px;
  padding-left: 8px;
  border-left: 2px solid color-mix(in srgb, var(--ui-accent-border) 34%, transparent);
  margin-left: 8px;
}

.student-nav__submenu-row {
  display: grid;
  gap: 5px;
  min-width: 0;
}

.student-nav__submenu-title {
  color: var(--ui-chart-neutral);
  font-size: var(--ui-size-11);
  font-weight: var(--ui-weight-bold);
  letter-spacing: 0;
  text-transform: uppercase;
}

.student-nav__item {
  border: 1px solid transparent;
  border-radius: var(--ui-radius-panel);
  background: transparent;
  color: var(--ink-soft);
  text-align: left;
  padding: 9px 10px;
  font-size: var(--ui-size-13);
  cursor: pointer;
  display: grid;
  gap: 3px;
  line-height: 1.25;
  transition: background 160ms ease, border-color 160ms ease;
}

.student-nav__item:hover {
  border-color: color-mix(in srgb, var(--ui-accent-border) 32%, transparent);
  background: color-mix(in srgb, var(--ui-accent-border) 10%, transparent);
}

.student-nav__item:hover strong {
  color: var(--ink);
}

.student-nav__item:hover span {
  color: var(--ui-text-secondary);
}

.student-nav__item strong,
.student-nav__item span {
  display: block;
}

.student-nav__item strong {
  font-size: var(--ui-size-12);
}

.student-nav__item span {
  color: var(--ui-chart-neutral);
  font-size: var(--ui-size-11);
  line-height: 1.3;
}

.student-nav__item--active {
  border-color: color-mix(in srgb, var(--ui-primary) 42%, transparent);
  background: var(--ui-surface);
  color: var(--rojo);
  font-weight: var(--ui-weight-medium);
  box-shadow: inset 4px 0 0 color-mix(in srgb, var(--ui-primary) 72%, transparent), 0 8px 18px color-mix(in srgb, var(--ui-primary) 12%, transparent);
}

.student-nav__item--active:hover {
  border-color: color-mix(in srgb, var(--ui-primary) 52%, transparent);
  background: var(--ui-surface);
  color: var(--rojo);
}

.student-nav__item--active strong,
.student-nav__item--active:hover strong {
  color: var(--ui-primary);
}

.student-nav__item--active span,
.student-nav__item--active:hover span {
  color: var(--ui-accent-hover);
}

.student-note-card {
  background: var(--surface-tint);
  border: 1px solid var(--line-strong);
  border-radius: var(--ui-radius-panel);
  padding: 12px;
  align-self: end;
}

.student-note-card h3 {
  margin: 0 0 8px;
  font-size: var(--ui-size-14);
}

.student-note-card p {
  margin: 0;
  font-size: var(--ui-size-13);
  color: var(--ui-text-secondary);
}

.student-main {
  min-width: 0;
  display: grid;
  gap: 12px;
}

.student-topbar {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--ui-radius-panel);
  padding: 14px 16px;
  display: flex;
  justify-content: space-between;
  gap: 16px;
  align-items: center;
  box-shadow: var(--ui-shadow-sm);
}

.student-topbar h1,
.student-topbar h2 {
  margin: 2px 0 0;
  font-size: var(--ui-size-32);
  line-height: 1;
  color: var(--ink);
}

.student-topbar__right {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}

.student-search {
  width: min(390px, 44vw);
  border: 1px solid var(--line);
  border-radius: var(--ui-radius-panel);
  padding: 10px 12px;
  background: var(--ui-surface);
}

.student-user-pill {
  border-radius: var(--ui-radius-panel);
  border: 1px solid var(--line);
  padding: 8px 12px;
  background: var(--ui-surface);
}

.student-user-pill strong {
  display: block;
  font-size: var(--ui-size-13);
  color: var(--ui-text);
}

.student-user-pill span {
  font-size: var(--ui-size-11);
  color: var(--gris-oscuro);
}

.student-user-pill--floating {
  width: fit-content;
}

.report-description {
  margin: 18px 0 0;
  font-size: var(--ui-size-13);
  line-height: 1.7;
  color: var(--ui-accent-hover);
  max-width: 780px;
}

.student-grid {
  display: grid;
  gap: 14px;
}

.student-grid--stats {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.student-grid--content {
  grid-template-columns: repeat(12, minmax(0, 1fr));
}

.student-card {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--ui-radius-panel);
  padding: 14px;
  min-width: 0;
  box-shadow: var(--ui-shadow-sm);
}

.student-card--stat p {
  margin: 0;
  color: var(--ui-muted);
  font-size: var(--ui-size-13);
}

.student-card--stat h2 {
  margin: 8px 0 4px;
  font-size: var(--ui-size-32);
  color: var(--ui-text);
}

.student-card--stat small {
  color: var(--rojo);
}

.student-card--wide {
  grid-column: span 8;
}

.student-card:not(.student-card--wide) {
  grid-column: span 4;
}

.card-head {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  align-items: center;
  margin-bottom: 10px;
}

.card-head h3 {
  margin: 0;
  font-size: var(--ui-size-18);
  color: var(--ink);
}

.card-head span {
  font-size: var(--ui-size-12);
  color: var(--gris-oscuro);
}

.subject-list,
.task-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 10px;
}

.subject-list li {
  display: grid;
  gap: 6px;
}

.subject-meta {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  font-size: var(--ui-size-14);
}

.subject-meta strong {
  color: var(--ui-text);
}

.subject-meta span {
  color: var(--rojo);
  font-weight: var(--ui-weight-medium);
}

.subject-bar {
  height: 8px;
  border-radius: var(--ui-radius-panel);
  background: var(--ui-neutral-soft);
  overflow: hidden;
}

.subject-bar span {
  display: block;
  height: 100%;
  background: var(--ui-accent);
  border-radius: var(--ui-radius-panel);
}

.mini-chart {
  height: 160px;
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 8px;
  padding-top: 8px;
}

.mini-chart span {
  flex: 1;
  border-radius: var(--ui-radius-panel) var(--ui-radius-panel) 0 0;
  background: var(--ui-surface);
}

.dashboard-executive-grid,
.dashboard-chart-grid {
  display: grid;
  grid-template-columns: repeat(12, minmax(0, 1fr));
  gap: 18px;
  align-items: stretch;
}

.dashboard-executive-grid .dashboard-summary-panel {
  grid-column: span 4;
}

.dashboard-executive-grid .dashboard-trend-panel {
  grid-column: 1 / -1;
}

.dashboard-chart-card {
  grid-column: span 8;
}

.dashboard-executive-grid .dashboard-pie-card {
  grid-column: span 4;
}

.dashboard-executive-grid .dashboard-active-type-card {
  grid-column: span 4;
}

.dashboard-executive-grid .dashboard-active-row {
  display: grid;
  grid-column: 5 / -1;
  grid-template-columns: minmax(0, 1.35fr) minmax(320px, 0.75fr);
  gap: 18px;
  align-items: stretch;
}

.dashboard-executive-grid .dashboard-active-row .dashboard-pie-card,
.dashboard-executive-grid .dashboard-active-row .dashboard-active-type-card {
  grid-column: auto;
  min-width: 0;
}

.dashboard-executive-grid .dashboard-bars-card {
  grid-column: 1 / -1;
}

.dashboard-admissions-grid {
  grid-template-columns: repeat(12, minmax(0, 1fr));
  gap: 14px;
}

.dashboard-admissions-grid .dashboard-summary-panel {
  grid-column: span 4;
}

.dashboard-admissions-grid .dashboard-pie-card {
  grid-column: span 4;
}

.dashboard-admissions-grid .dashboard-admissions-kpi-card {
  grid-column: span 4;
}

.dashboard-admissions-grid .dashboard-summary-panel,
.dashboard-admissions-grid .dashboard-pie-card,
.dashboard-admissions-grid .dashboard-admissions-kpi-card {
  min-height: 278px;
}

.dashboard-admissions-grid .dashboard-summary-panel .card-head,
.dashboard-admissions-grid .dashboard-pie-card .card-head,
.dashboard-admissions-grid .dashboard-admissions-kpi-card .card-head,
.dashboard-admissions-grid .dashboard-bars-card .card-head {
  margin-bottom: 10px;
}

.dashboard-admissions-grid .dashboard-metric-tiles {
  grid-template-columns: repeat(2, minmax(132px, 1fr));
  gap: 10px;
}

.dashboard-admissions-grid .dashboard-metric-tile {
  min-height: 96px;
  padding: 14px;
}

.dashboard-admissions-grid .dashboard-state-list {
  gap: 8px;
}

.dashboard-admissions-grid .dashboard-state-list--static button {
  min-height: 40px;
  padding: 8px 10px;
}

.dashboard-admissions-grid .dashboard-bars-card {
  grid-column: 1 / -1;
}

.dashboard-admissions-grid .dashboard-bars-card:not(.student-card--wide) {
  min-height: 260px;
}

.dashboard-admissions-grid .dashboard-bars {
  height: 220px;
  padding: 20px 18px 6px;
  align-items: end;
}

.dashboard-admissions-grid .dashboard-bars div {
  gap: 6px;
}

.dashboard-admissions-grid .dashboard-bars div > span {
  max-height: 160px;
}

.dashboard-admissions-grid .student-card--wide {
  grid-column: 1 / -1;
}

.dashboard-admissions-kpis {
  display: grid;
  gap: 10px;
}

.dashboard-admissions-kpis div {
  display: grid;
  gap: 4px;
  padding: 13px 14px;
  border: 1px solid color-mix(in srgb, var(--ui-accent-border) 55%, transparent);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface);
}

.dashboard-admissions-kpis span {
  color: var(--ui-text-secondary);
  font-size: var(--ui-size-12);
  font-weight: var(--ui-weight-bold);
}

.dashboard-admissions-kpis strong {
  color: var(--ui-text);
  font-size: var(--ui-size-24);
  line-height: 1;
}

.dashboard-admissions-kpis small {
  color: var(--ui-muted);
  font-weight: var(--ui-weight-bold);
}

@media (min-width: 1200px) {
  .dashboard-admissions-grid .dashboard-summary-panel,
  .dashboard-admissions-grid .dashboard-pie-card,
  .dashboard-admissions-grid .dashboard-admissions-kpi-card {
    grid-column: span 4;
  }
}

@media (max-width: 1180px) {
  .dashboard-admissions-grid .dashboard-summary-panel,
  .dashboard-admissions-grid .dashboard-pie-card {
    grid-column: span 6;
  }

  .dashboard-admissions-grid .dashboard-admissions-kpi-card {
    grid-column: 1 / -1;
    min-height: 0;
  }

  .dashboard-admissions-kpis {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

@media (max-width: 760px) {
  .dashboard-admissions-grid {
    grid-template-columns: 1fr;
  }

  .dashboard-admissions-grid .dashboard-summary-panel,
  .dashboard-admissions-grid .dashboard-pie-card,
  .dashboard-admissions-grid .dashboard-admissions-kpi-card,
  .dashboard-admissions-grid .dashboard-bars-card,
  .dashboard-admissions-grid .student-card--wide {
    grid-column: 1 / -1;
    min-height: 0;
  }

  .dashboard-admissions-grid .dashboard-metric-tiles,
  .dashboard-admissions-kpis {
    grid-template-columns: 1fr;
  }

  .dashboard-admissions-grid .dashboard-bars {
    height: 190px;
    overflow-x: auto;
  }
}

.dashboard-metric-tiles {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
  margin-top: 12px;
}

.dashboard-metric-tile {
  min-height: 82px;
  border-radius: var(--ui-radius-panel);
  padding: 12px;
  display: grid;
  align-content: center;
  gap: 5px;
  border: 1px solid color-mix(in srgb, var(--ui-border-strong) 32%, transparent);
}

.dashboard-metric-tile--clickable {
  width: 100%;
  text-align: left;
  cursor: pointer;
}

.dashboard-metric-tile--clickable:hover,
.dashboard-metric-tile--clickable:focus-visible {
  border-color: color-mix(in srgb, var(--ui-accent-border) 90%, transparent);
  box-shadow: var(--ui-shadow-sm);
}

.dashboard-metric-tile span {
  color: var(--ui-text-secondary);
  font-size: var(--ui-size-12);
  font-weight: var(--ui-weight-bold);
}

.dashboard-metric-tile strong {
  color: var(--ui-text);
  font-size: var(--ui-size-24);
  line-height: 1;
}

.dashboard-metric-tile small {
  color: var(--ui-muted);
  font-size: var(--ui-size-12);
  font-weight: var(--ui-weight-bold);
}

.dashboard-metric-tile--red {
  background: color-mix(in srgb, var(--ui-primary) 11%, transparent);
}

.dashboard-metric-tile--cyan {
  background: color-mix(in srgb, var(--ui-accent-border) 24%, transparent);
}

.dashboard-metric-tile--purple {
  background: color-mix(in srgb, var(--ui-chart-violet) 14%, transparent);
}

.dashboard-metric-tile--gold {
  background: color-mix(in srgb, var(--ui-chart-gold) 16%, transparent);
}

.dashboard-line-chart {
  min-height: 360px;
  overflow: hidden;
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface);
  border: 1px solid color-mix(in srgb, var(--ui-border-strong) 62%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--ui-surface) 42%, transparent);
}

.dashboard-line-chart svg {
  width: 100%;
  min-height: 360px;
  height: auto;
  display: block;
}

.dashboard-year-filters {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin: 12px 0 6px;
}

.dashboard-year-filters--compact {
  margin: 6px 0 0;
}

.dashboard-year-filters button {
  border: 1px solid color-mix(in srgb, var(--ui-border-strong) 85%, transparent);
  border-radius: var(--ui-radius-panel);
  padding: 7px 12px;
  background: color-mix(in srgb, var(--ui-surface) 90%, transparent);
  color: var(--ui-text);
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  font-weight: var(--ui-weight-bold);
}

.dashboard-year-filter--year {
  border-color: color-mix(in srgb, var(--trend-color) 65%, var(--ui-surface));
  color: var(--trend-color);
}

.dashboard-year-filter--year::before {
  content: '';
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--trend-color);
  box-shadow: var(--ui-shadow-sm);
}

.dashboard-year-filters button:hover,
.dashboard-year-filter--active {
  border-color: color-mix(in srgb, var(--ui-accent) 80%, transparent);
  background: color-mix(in srgb, var(--ui-accent-border) 18%, transparent);
}

.dashboard-year-filter--year.dashboard-year-filter--active {
  border-color: var(--trend-color);
  background: color-mix(in srgb, var(--trend-color) 15%, var(--ui-surface));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--trend-color) 45%, transparent);
}

.dashboard-axis {
  stroke: color-mix(in srgb, var(--ui-muted) 34%, transparent);
  stroke-width: 0.8;
}

.dashboard-chart-surface {
  fill: color-mix(in srgb, var(--ui-surface) 34%, transparent);
}

.dashboard-grid-line {
  stroke: color-mix(in srgb, var(--ui-muted) 18%, transparent);
  stroke-width: 0.7;
  stroke-dasharray: 4 5;
}

.dashboard-axis-label {
  fill: color-mix(in srgb, var(--ui-text-secondary) 72%, transparent);
  font-size: var(--ui-size-11);
  text-anchor: start;
}

.dashboard-line {
  fill: none;
  stroke: var(--ui-accent);
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
  filter: drop-shadow(0 2px 5px color-mix(in srgb, var(--ui-accent) 12%, transparent));
}

.dashboard-area {
  pointer-events: none;
}

.dashboard-point {
  fill: var(--ui-surface);
  stroke: var(--ui-accent);
  stroke-width: 2;
}

.dashboard-trend-point {
  cursor: pointer;
  outline: none;
}

.dashboard-trend-point:focus .dashboard-point,
.dashboard-trend-point:hover .dashboard-point {
  fill: color-mix(in srgb, var(--ui-accent-border) 26%, transparent);
  stroke-width: 3;
}

.dashboard-point-label {
  fill: var(--ui-text);
  font-size: var(--ui-size-12);
  font-weight: var(--ui-weight-bold);
  text-anchor: middle;
}

.dashboard-month-axis-label {
