  font-size: var(--ui-size-12);
  font-weight: var(--ui-weight-bold);
}

.gestion-sis-flow-step__actions button:hover,
.gestion-sis-flow-step__actions button:focus-visible {
  border-color: color-mix(in srgb, var(--ui-accent) 55%, transparent);
  background: color-mix(in srgb, var(--ui-accent) 11%, transparent);
  color: var(--ui-accent-hover);
}

.gestion-sis-module-strip__head em {
