  border: 1px solid color-mix(in srgb, var(--ui-accent-border) 44%, transparent);
  border-radius: var(--ui-radius-panel);
  padding: 6px 10px;
  background: color-mix(in srgb, var(--ui-accent-border) 14%, transparent);
  color: var(--ui-accent);
  font-size: var(--ui-size-12);
  font-style: normal;
  font-weight: var(--ui-weight-bold);
}

.gestion-sis-process-select {
  min-width: min(320px, 100%);
