  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface);
  color: var(--ui-text);
  cursor: pointer;
  padding: 14px 14px 14px 54px;
  text-align: left;
  transition: border-color 0.16s ease, box-shadow 0.16s ease, transform 0.16s ease;
}

.gestion-sis-process-card:hover,
.gestion-sis-process-card:focus-visible {
  border-color: color-mix(in srgb, var(--ui-accent-border) 88%, transparent);
