  font-size: var(--ui-size-12);
  line-height: 1.38;
}

.gestion-sis-process-card small {
  margin-top: auto;
  color: var(--ui-primary);
  font-size: var(--ui-size-11);
  font-weight: var(--ui-weight-bold);
}

.gestion-sis-process-card__count {
  position: absolute;
  top: 14px;
  left: 14px;
  width: 30px;
  height: 30px;
  display: inline-grid;
  place-items: center;
  border-radius: var(--ui-radius-panel);
  background: color-mix(in srgb, var(--ui-accent-border) 20%, transparent);
  color: var(--ui-accent);
  font-size: var(--ui-size-12);
  font-weight: var(--ui-weight-bold);
}

.gestion-sis-process-card--active {
  border-color: color-mix(in srgb, var(--ui-primary) 72%, transparent);
  background: var(--ui-surface);
  box-shadow: var(--ui-shadow-sm);
}

.gestion-sis-process-card--active .gestion-sis-process-card__count {
  background: color-mix(in srgb, var(--ui-primary) 12%, transparent);
  color: var(--ui-primary);
}

.gestion-sis-process-panel,
.gestion-sis-list {
