}

.gestion-sis-process-list {
  display: grid;
  gap: 8px;
}

.gestion-sis-process-list button {
  min-height: 82px;
  display: grid;
  gap: 4px;
  border: 1px solid color-mix(in srgb, var(--ui-border-strong) 82%, transparent);
  border-radius: var(--ui-radius-panel);
  background: color-mix(in srgb, var(--ui-surface) 76%, transparent);
  color: var(--ui-text);
