  padding: 11px 12px;
  text-align: left;
}

.gestion-sis-process-list strong,
.gestion-sis-process-list span,
.gestion-sis-process-list small {
  display: block;
}

.gestion-sis-process-list strong {
  font-size: var(--ui-size-14);
}

.gestion-sis-process-list span {
  color: var(--ui-muted);
  font-size: var(--ui-size-12);
