.screen-access-subscreen .senescyt-update-subscreen__actions > span {
  flex: 0 0 auto;
  border: 1px solid color-mix(in srgb, var(--ui-accent-border) 50%, transparent);
  border-radius: var(--ui-radius-panel);
  background: color-mix(in srgb, var(--ui-accent-border) 12%, transparent);
  padding: 8px 11px;
  color: var(--ui-text-secondary);
  letter-spacing: 0;
  white-space: nowrap;
}

.screen-access-subscreen__body {
  min-height: 0;
  overflow-x: hidden;
  overflow-y: auto;
  overscroll-behavior: contain;
  scrollbar-gutter: stable;
  padding: clamp(10px, 1.4vw, 18px) clamp(12px, 1.7vw, 22px) clamp(14px, 1.7vw, 22px);
}

.screen-access-subscreen__body:focus-visible {
  outline: 2px solid color-mix(in srgb, var(--ui-accent) 55%, transparent);
  outline-offset: -3px;
}

.screen-access-subscreen__body > .senescyt-update-summary {
  margin: 0 0 12px;
}

.screen-access-subscreen__body > .status-message {
  margin-bottom: 12px;
}

.screen-access-subscreen__body > .screen-access-actions {
  position: sticky;
  top: 0;
  z-index: 3;
  margin: 0 -4px 12px;
  border-bottom: 1px solid color-mix(in srgb, var(--ui-border-strong) 72%, transparent);
  background: color-mix(in srgb, var(--ui-surface) 97%, transparent);
  padding: 8px 4px 10px;
}

.screen-access-subscreen__body::-webkit-scrollbar {
  width: 12px;
}

.screen-access-subscreen__body::-webkit-scrollbar-track {
  background: var(--ui-background);
}

.screen-access-subscreen__body::-webkit-scrollbar-thumb {
  border: 3px solid var(--ui-background);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-disabled-text);
}

.screen-access-editor-toolbar {
  display: grid;
  grid-template-columns: minmax(280px, 1fr) auto;
  gap: 12px;
  align-items: end;
  margin: 12px 0;
  padding: 12px;
  border: 1px solid color-mix(in srgb, var(--ui-accent-border) 52%, transparent);
  border-radius: var(--ui-radius-panel);
  background: var(--surface-tint);
}

.screen-access-editor-toolbar label {
  display: grid;
  min-width: 0;
  gap: 6px;
  color: var(--ui-muted);
  font-size: var(--ui-size-12);
  font-weight: var(--ui-weight-bold);
}

.screen-access-editor-toolbar input {
  width: 100%;
  min-width: 0;
  min-height: 42px;
  border: 1px solid var(--line);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface);
  color: var(--ink);
  padding: 0 12px;
  font: inherit;
}

.screen-access-editor-toolbar > div {
  display: grid;
  min-width: 150px;
  gap: 3px;
  justify-items: end;
  color: var(--ui-chart-neutral);
  font-size: var(--ui-size-11);
  font-weight: var(--ui-weight-bold);
}

.screen-access-editor-toolbar > div strong {
  color: var(--ink);
  font-size: var(--ui-size-14);
}

.screen-access-layout {
  display: grid;
  grid-template-columns: minmax(240px, 0.28fr) minmax(0, 1fr);
  gap: 12px;
  align-items: start;
}

.screen-access-roles,
.screen-access-panel {
  min-height: 0;
}

.screen-access-role {
  width: 100%;
  display: grid;
  gap: 4px;
  margin-bottom: 8px;
  border: 1px solid color-mix(in srgb, var(--ui-border-strong) 90%, transparent);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface);
  color: var(--ink);
  cursor: pointer;
  padding: 10px 12px;
  text-align: left;
}

.screen-access-role strong,
.screen-access-role span {
  display: block;
}

.screen-access-role strong {
  font-size: var(--ui-size-14);
}

.screen-access-role span {
  color: var(--ui-chart-neutral);
  font-size: var(--ui-size-12);
  font-weight: var(--ui-weight-bold);
  line-height: 1.35;
}

.screen-access-role--active {
  border-color: color-mix(in srgb, var(--ui-accent) 60%, transparent);
  background: color-mix(in srgb, var(--ui-accent) 10%, transparent);
}

.screen-access-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
  margin-bottom: 12px;
}

.screen-access-actions__status {
  display: grid;
  min-width: min(100%, 300px);
  flex: 1 1 320px;
  gap: 2px;
  color: var(--ui-chart-neutral);
  font-size: var(--ui-size-11);
}

.screen-access-actions__status strong {
  color: var(--ink);
  font-size: var(--ui-size-13);
}

.screen-access-actions button {
  min-height: 40px;
  border: 1px solid color-mix(in srgb, var(--ui-accent-border) 56%, transparent);
  border-radius: var(--ui-radius-panel);
  background: var(--surface-tint);
  color: var(--ink);
  cursor: pointer;
  padding: 8px 14px;
  font: inherit;
  font-size: var(--ui-size-13);
  font-weight: var(--ui-weight-bold);
}

.screen-access-actions .primary-action {
  border-color: transparent;
  background: var(--ui-primary);
  color: var(--ui-on-primary);
}

.screen-access-actions button:disabled {
  cursor: not-allowed;
  opacity: 0.5;
}

.screen-access-groups {
  display: block;
  columns: 2 560px;
  column-fill: balance;
  column-gap: 12px;
}

/* Matrícula Moodle-Teams */

.moodle-teams-page {
  display: grid;
  gap: 14px;
  min-width: 0;
}

.moodle-teams-workflow,
.moodle-teams-preview,
.moodle-teams-result {
  min-width: 0;
}

.moodle-teams-workflow {
  display: grid;
  gap: 14px;
}

.moodle-teams-workflow .card-head > div,
.moodle-teams-preview-head > div {
  min-width: 0;
}

.moodle-teams-step {
  display: block;
  margin-bottom: 4px;
  color: var(--ui-muted);
  font-size: var(--ui-size-12);
  font-weight: var(--ui-weight-bold);
  letter-spacing: 0;
  text-transform: uppercase;
}

.moodle-teams-search {
  display: grid;
  grid-template-columns: minmax(260px, 1fr) auto auto;
  align-items: end;
  gap: 10px;
}

.moodle-teams-search label,
.moodle-teams-course-selector label {
  display: grid;
  gap: 6px;
  min-width: 0;
  color: var(--ui-text-secondary);
  font-size: var(--ui-size-12);
  font-weight: var(--ui-weight-bold);
}

.moodle-teams-search input,
.moodle-teams-course-selector select {
  width: 100%;
  min-width: 0;
  min-height: 44px;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface);
  color: var(--ui-text);
  padding: 0 13px;
  font: inherit;
  font-weight: var(--ui-weight-medium);
}

.moodle-teams-search button,
.moodle-teams-course-selector button,
.moodle-teams-final-actions button,
.moodle-teams-modal-actions button {
  min-height: 40px;
  white-space: nowrap;
}

.moodle-teams-primary {
