  background: var(--ui-primary);
  color: var(--ui-on-primary);
}

.moodle-teams-course-selector {
  display: grid;
  grid-template-columns: minmax(320px, 1fr) 150px auto;
  align-items: end;
  gap: 10px;
  padding: 14px;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-panel);
