  align-content: center;
  min-height: 44px;
  border-left: 3px solid var(--ui-accent);
  padding-left: 12px;
}

.moodle-teams-course-count strong {
  color: var(--ui-text);
  font-size: var(--ui-size-18);
}

.moodle-teams-course-count span,
.moodle-teams-selection {
  color: var(--ui-muted);
  font-size: var(--ui-size-12);
}

.moodle-teams-selection {
  margin: 0;
}

.moodle-teams-preview {
  display: grid;
  gap: 14px;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface);
  padding: 16px;
}

.moodle-teams-preview-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  border-bottom: 1px solid var(--ui-border);
  padding-bottom: 14px;
}

.moodle-teams-preview-head h2,
.moodle-teams-preview-head p,
.moodle-teams-section-head h3 {
  margin: 0;
}

.moodle-teams-preview-head p {
  margin-top: 5px;
  color: var(--ui-muted);
}

.moodle-teams-team-state {
  display: grid;
  gap: 4px;
  width: min(100%, 440px);
  border-left: 4px solid var(--ui-accent);
  background: var(--ui-accent-soft);
  padding: 10px 12px;
}

.moodle-teams-team-state.is-new {
  border-left-color: var(--ui-danger);
  background: var(--ui-primary-soft);
}

.moodle-teams-team-state span {
  color: var(--ui-muted);
  font-size: var(--ui-size-12);
  font-weight: var(--ui-weight-bold);
  text-transform: uppercase;
}

.moodle-teams-team-state strong {
  overflow-wrap: anywhere;
  color: var(--ui-text);
}

.moodle-teams-summary {
  display: grid;
  grid-template-columns: repeat(6, minmax(110px, 1fr));
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-panel);
  overflow: hidden;
}

.moodle-teams-summary > div {
  display: grid;
  gap: 5px;
  min-height: 76px;
  align-content: center;
  border-right: 1px solid var(--ui-border);
  padding: 10px 12px;
}

.moodle-teams-summary > div:last-child {
  border-right: 0;
}

.moodle-teams-summary span {
  color: var(--ui-muted);
  font-size: var(--ui-size-12);
  font-weight: var(--ui-weight-bold);
  text-transform: uppercase;
}

.moodle-teams-summary strong {
  color: var(--ui-text);
  font-size: var(--ui-size-24);
}

.moodle-teams-alert {
  border: 1px solid;
  border-radius: var(--ui-radius-panel);
  padding: 12px 14px;
}

.moodle-teams-alert ul {
  margin: 7px 0 0;
  padding-left: 20px;
}

.moodle-teams-alert--warning {
  border-color: var(--ui-warning-border);
  background: var(--ui-warning-soft);
  color: var(--ui-warning);
}

.moodle-teams-alert--error {
  border-color: var(--ui-primary-border);
  background: var(--ui-danger-soft);
  color: var(--ui-primary);
}

.moodle-teams-participants {
  min-width: 0;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-panel);
  overflow: hidden;
}

.moodle-teams-student-controls {
  display: grid;
  grid-template-columns: minmax(260px, 1fr) 130px auto auto;
  align-items: end;
  gap: 10px;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-accent-soft);
  padding: 12px;
}

.moodle-teams-student-controls label {
  display: grid;
  gap: 6px;
  min-width: 0;
  color: var(--ui-text-secondary);
  font-size: var(--ui-size-12);
  font-weight: var(--ui-weight-bold);
}

.moodle-teams-student-controls input[type='search'] {
  width: 100%;
  min-width: 0;
  min-height: 42px;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface);
  color: var(--ui-text);
  padding: 0 13px;
  font: inherit;
  font-weight: var(--ui-weight-medium);
}

.moodle-teams-student-controls button {
  min-height: 40px;
  white-space: nowrap;
}

.moodle-teams-selection-count {
  display: grid;
  align-content: center;
  min-height: 42px;
  border-left: 3px solid var(--ui-accent);
  padding-left: 11px;
}

.moodle-teams-selection-count strong {
  color: var(--ui-text);
  font-size: var(--ui-size-18);
}

.moodle-teams-selection-count span,
.moodle-teams-selection-count small {
  color: var(--ui-muted);
  font-size: var(--ui-size-11);
}

.moodle-teams-section-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  background: var(--ui-accent-soft);
  padding: 11px 13px;
}

.moodle-teams-section-head h3 {
  font-size: var(--ui-size-16);
}

.moodle-teams-section-head strong {
  color: var(--ui-accent);
}

.moodle-teams-table-wrap {
  max-width: 100%;
  overflow-x: auto;
}

.moodle-teams-table {
  width: 100%;
  min-width: 760px;
  border-collapse: collapse;
  table-layout: fixed;
}

.moodle-teams-table th,
.moodle-teams-table td {
  border-top: 1px solid var(--ui-border);
  border-right: 1px solid var(--ui-border);
  padding: 10px 12px;
  text-align: left;
  vertical-align: middle;
  overflow-wrap: anywhere;
}

.moodle-teams-table th:last-child,
.moodle-teams-table td:last-child {
  border-right: 0;
}

.moodle-teams-table th {
  color: var(--ui-text-secondary);
  font-size: var(--ui-size-11);
  text-transform: uppercase;
}

.moodle-teams-table td {
  color: var(--ui-text);
}

.moodle-teams-table tr.is-selected td {
  background: var(--ui-accent-soft);
}

.moodle-teams-table .moodle-teams-select-column {
  width: 92px;
  text-align: center;
}

.moodle-teams-table .moodle-teams-select-column input {
  width: 18px;
  height: 18px;
  margin: 0;
  accent-color: var(--ui-accent);
}

.moodle-teams-table td strong,
.moodle-teams-table td small {
  display: block;
}

.moodle-teams-table td small {
  margin-top: 4px;
  color: var(--ui-chart-neutral);
}

.moodle-teams-status {
  display: inline-block;
  border-radius: var(--ui-radius-control);
  padding: 5px 8px;
  font-size: var(--ui-size-12);
  font-weight: var(--ui-weight-bold);
}

.moodle-teams-status.is-ready,
.moodle-teams-status.is-existing {
  background: var(--ui-neutral-soft);
  color: var(--ui-success);
}

.moodle-teams-status.is-existing {
  background: var(--ui-accent-soft);
  color: var(--ui-accent);
}

.moodle-teams-status.is-ignored {
  background: var(--ui-background);
  color: var(--ui-muted);
}

.moodle-teams-status.is-error {
  background: var(--ui-primary-soft);
  color: var(--ui-primary);
}

.moodle-teams-empty {
  color: var(--ui-chart-neutral);
  text-align: center !important;
  padding: 24px !important;
}

.moodle-teams-ignored {
  border: 1px dashed var(--ui-border-strong);
  border-radius: var(--ui-radius-panel);
  padding: 11px;
}

.moodle-teams-ignored summary {
  cursor: pointer;
  color: var(--ui-text-secondary);
  font-weight: var(--ui-weight-bold);
}

.moodle-teams-ignored .moodle-teams-participants {
  margin-top: 11px;
}

.moodle-teams-final-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  border-top: 1px solid var(--ui-border);
  padding-top: 14px;
}

.moodle-teams-result {
  display: grid;
  grid-template-columns: minmax(260px, 1fr) repeat(3, minmax(100px, 150px)) auto;
  align-items: center;
  gap: 12px;
  border: 1px solid var(--ui-success-border);
  border-left: 5px solid var(--ui-success);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-success-soft);
  padding: 14px;
}

.moodle-teams-result > div {
  display: grid;
  gap: 3px;
}

.moodle-teams-result span {
  color: var(--ui-muted);
  font-size: var(--ui-size-12);
}

.moodle-teams-result a {
  color: var(--ui-accent-hover);
  font-weight: var(--ui-weight-bold);
}

.moodle-teams-modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 1200;
  display: grid;
  place-items: center;
  background: color-mix(in srgb, var(--ui-text) 62%, transparent);
  padding: 20px;
}

.moodle-teams-modal {
  display: grid;
  gap: 16px;
  width: min(100%, 680px);
  max-height: calc(100vh - 40px);
  overflow-y: auto;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface);
  box-shadow: var(--ui-shadow-dialog);
  padding: 20px;
}

.moodle-teams-modal h2,
.moodle-teams-modal p {
  margin: 0;
}

.moodle-teams-name-field {
  display: grid;
  gap: 7px;
  min-width: 0;
}

.moodle-teams-name-field > span {
  color: var(--ui-muted);
  font-size: var(--ui-size-12);
  font-weight: var(--ui-weight-bold);
  text-transform: uppercase;
}

.moodle-teams-name-field input {
  width: 100%;
  min-width: 0;
  min-height: 44px;
  border: 1px solid var(--ui-border-strong);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface);
  color: var(--ui-text);
  font: inherit;
  font-weight: var(--ui-weight-bold);
  padding: 10px 12px;
}

.moodle-teams-name-field input:focus {
  border-color: var(--ui-accent);
  outline: 2px solid color-mix(in srgb, var(--ui-accent) 18%, transparent);
  outline-offset: 1px;
}

.moodle-teams-name-field input[aria-invalid="true"] {
  border-color: var(--ui-danger);
}

.moodle-teams-name-field small {
  color: var(--ui-chart-neutral);
  text-align: right;
}

.moodle-teams-modal dl {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  margin: 0;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-panel);
  overflow: hidden;
}

.moodle-teams-modal dl > div {
  display: grid;
  gap: 5px;
  border-right: 1px solid var(--ui-border);
  border-bottom: 1px solid var(--ui-border);
  padding: 11px;
}

.moodle-teams-modal dt {
  color: var(--ui-chart-neutral);
  font-size: var(--ui-size-12);
  font-weight: var(--ui-weight-bold);
  text-transform: uppercase;
}

.moodle-teams-modal dd {
  margin: 0;
  overflow-wrap: anywhere;
  color: var(--ui-text);
  font-weight: var(--ui-weight-bold);
}

.moodle-teams-modal-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
}

.moodle-teams-result-modal {
  width: min(100%, 940px);
}

.moodle-teams-result-modal__head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 18px;
  border-bottom: 1px solid var(--ui-border);
  padding-bottom: 15px;
}

.moodle-teams-result-modal__head > div,
.moodle-teams-result-modal__head p {
  min-width: 0;
  overflow-wrap: anywhere;
}

.moodle-teams-result-modal__head > div {
  display: grid;
  gap: 6px;
  min-width: 0;
}

.moodle-teams-result-modal__head button {
  flex: 0 0 auto;
}

.moodle-teams-result-summary {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  border: 1px solid var(--ui-border-strong);
  border-radius: var(--ui-radius-panel);
  overflow: hidden;
  background: var(--ui-success-soft);
}

.moodle-teams-result-summary > div {
  display: grid;
  gap: 5px;
  border-right: 1px solid var(--ui-border-strong);
  padding: 14px 16px;
}

.moodle-teams-result-summary > div:last-child {
  border-right: 0;
}

.moodle-teams-result-summary > div.has-errors {
  background: var(--ui-danger-soft);
}

.moodle-teams-result-summary span {
  color: var(--ui-muted);
  font-size: var(--ui-size-12);
  font-weight: var(--ui-weight-bold);
  text-transform: uppercase;
}

.moodle-teams-result-summary strong {
  color: var(--ui-text);
  font-size: var(--ui-size-24);
}

.moodle-teams-result-details {
  display: grid;
  gap: 9px;
}

.moodle-teams-result-detail {
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface);
  overflow: hidden;
}

.moodle-teams-result-detail summary {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  min-height: 58px;
  cursor: pointer;
  list-style: none;
  padding: 10px 14px;
}

.moodle-teams-result-detail summary::-webkit-details-marker {
  display: none;
}

.moodle-teams-result-detail summary::before {
  content: "+";
  display: grid;
  place-items: center;
  flex: 0 0 26px;
  width: 26px;
  height: 26px;
  border: 1px solid var(--ui-accent-border);
  border-radius: 50%;
  color: var(--ui-accent);
  font-weight: var(--ui-weight-bold);
}

.moodle-teams-result-detail[open] summary::before {
  content: "−";
}

.moodle-teams-result-detail summary > span {
  display: grid;
  flex: 1 1 auto;
  gap: 3px;
  min-width: 0;
