  }

  .moodle-teams-result-detail td {
    border: 0;
    padding: 4px 0;
  }

  .moodle-teams-result-link {
    justify-self: stretch;
    text-align: center;
  }

  .moodle-teams-team-state {
    width: auto;
  }

  .moodle-teams-summary {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .moodle-teams-summary > div,
  .moodle-teams-summary > div:nth-child(3) {
    border-right: 1px solid var(--ui-border);
    border-bottom: 1px solid var(--ui-border);
  }

  .moodle-teams-summary > div:nth-child(even) {
    border-right: 0;
  }

  .moodle-teams-summary > div:nth-last-child(-n + 2) {
    border-bottom: 0;
  }

  .moodle-teams-modal dl > div {
    border-right: 0;
  }
}

.screen-access-group {
  display: inline-block;
  width: 100%;
  min-width: 0;
  margin: 0 0 12px;
  border: 1px solid var(--line);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface);
  padding: 12px;
  break-inside: avoid;
  page-break-inside: avoid;
  vertical-align: top;
}

.screen-access-group__head {
  display: flex;
  gap: 12px;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 10px;
}

.screen-access-priority-group {
  border-color: color-mix(in srgb, var(--ui-accent) 52%, transparent);
  background: var(--ui-surface);
  box-shadow: inset 4px 0 0 color-mix(in srgb, var(--ui-accent) 82%, transparent);
}

.screen-access-priority-group .screen-access-group__head p {
  margin: 5px 0 0;
  color: var(--ui-muted);
  font-size: var(--ui-size-12);
  font-weight: var(--ui-weight-bold);
}

.screen-access-priority-grid {
  grid-template-columns: repeat(3, minmax(220px, 1fr));
}

.screen-access-group h4 {
  display: flex;
  gap: 12px;
  align-items: center;
  margin: 0;
  color: var(--ink);
  font-size: var(--ui-size-14);
}

.screen-access-group h4 span {
  color: var(--ui-chart-neutral);
  font-size: var(--ui-size-11);
}

.screen-access-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 250px), 1fr));
  gap: 8px;
}

.screen-access-item {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 10px;
  align-items: start;
  min-height: 74px;
  border: 1px solid color-mix(in srgb, var(--ui-border-strong) 85%, transparent);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface);
