}

/* Moodle: alertas de calificaciones pendientes. */

.moodle-grade-alert-loading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 14px 16px;
  border: 1px solid var(--ui-border);
  border-left: 4px solid var(--ui-accent);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-accent-soft);
  color: var(--ui-text);
}

.moodle-grade-alert-loading strong,
.moodle-grade-alert-loading span {
  display: block;
}

.moodle-grade-alert-loading span {
  color: var(--ui-text-secondary);
  font-size: var(--ui-size-14);
}

.moodle-grade-alert-indicator {
  display: grid;
  width: 100%;
  grid-template-columns: 44px minmax(0, 1fr) auto;
  align-items: center;
  gap: 14px;
  margin: 14px 0;
  padding: 14px 16px;
  border: 1px solid var(--ui-warning-border);
  border-left: 4px solid var(--ui-danger);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-warning-soft);
  box-shadow: var(--ui-shadow-sm);
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: pointer;
  transition: border-color 160ms ease, box-shadow 160ms ease, transform 160ms ease;
}

.moodle-grade-alert-indicator:hover {
  border-color: var(--ui-chart-gold);
  box-shadow: var(--ui-shadow-sm);
  transform: translateY(-1px);
}

.moodle-grade-alert-indicator--error {
  border-color: var(--ui-primary-border);
  border-left-color: var(--ui-danger);
  background: var(--ui-danger-soft);
}

.moodle-grade-alert-indicator:focus-visible {
  outline: 3px solid color-mix(in srgb, var(--ui-accent) 24%, transparent);
  outline-offset: 2px;
}

.moodle-grade-alert-indicator__count {
  display: inline-grid;
  width: 44px;
  height: 44px;
  place-items: center;
  border-radius: 50%;
  background: var(--ui-danger);
  color: var(--ui-on-primary);
  font-size: var(--ui-size-14);
  font-weight: var(--ui-weight-bold);
}

.moodle-grade-alert-indicator__copy {
  display: grid;
  min-width: 0;
  gap: 3px;
}

.moodle-grade-alert-indicator__copy strong,
.moodle-grade-alert-indicator__copy span {
  overflow-wrap: anywhere;
}

.moodle-grade-alert-indicator__action {
  display: inline-flex;
  min-height: 40px;
  align-items: center;
  justify-content: center;
  padding: 9px 14px;
  border: 1px solid var(--ui-border-strong);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface);
  color: var(--ui-text);
  font-weight: var(--ui-weight-bold);
  white-space: nowrap;
}

.moodle-grade-alert-indicator__copy span {
  color: var(--ui-muted);
  font-size: var(--ui-size-14);
}

.unified-alert-indicator {
  border-color: var(--ui-warning-border);
  background: var(--ui-warning-soft);
}

.moodle-confirm-dialog.unified-alert-center {
  display: grid;
  width: min(1280px, calc(100vw - 40px));
  max-height: calc(100dvh - 40px);
  grid-template-rows: auto minmax(0, 1fr);
  overflow: hidden;
}

.moodle-confirm-dialog__header.unified-alert-center__header {
  align-items: center;
}

.unified-alert-center__header > div {
  min-width: 0;
}

.unified-alert-center__header p {
  margin: 6px 0 0;
  color: var(--ui-muted);
  font-size: var(--ui-size-14);
}

.moodle-confirm-dialog__body.unified-alert-center__body {
  min-height: 0;
  overflow-y: auto;
  overscroll-behavior: contain;
  scrollbar-gutter: stable;
}

.unified-alert-center__summary {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  overflow: hidden;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface-alt);
}

.unified-alert-center__summary > div {
  display: grid;
  min-width: 0;
  gap: 4px;
  padding: 14px 16px;
  border-right: 1px solid var(--ui-border);
}

.unified-alert-center__summary > div:last-child {
  border-right: 0;
}

.unified-alert-center__summary span,
.unified-alert-center__section > header span,
.unified-alert-center__row span {
  color: var(--ui-muted);
  font-size: var(--ui-size-12);
  font-weight: var(--ui-weight-bold);
  text-transform: uppercase;
}

.unified-alert-center__summary strong {
  color: var(--ui-text);
  font-size: var(--ui-size-24);
}

.unified-alert-center__summary small,
.unified-alert-center__row small {
  color: var(--ui-chart-neutral);
  line-height: 1.4;
}

.unified-alert-center__errors {
  margin-top: 14px;
  padding: 10px 13px;
  border-left: 4px solid var(--ui-danger);
  background: var(--ui-danger-soft);
  color: var(--ui-primary-hover);
}

.unified-alert-center__errors p {
  margin: 3px 0;
}

.unified-alert-center__section {
  margin-top: 20px;
  border-top: 1px solid var(--ui-border);
}

.unified-alert-center__section > header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 16px 0 12px;
}

.unified-alert-center__section > header h3 {
  margin: 4px 0 0;
  color: var(--ui-text);
  font-size: var(--ui-size-16);
}

.unified-alert-center__filter {
  display: grid;
  grid-template-columns: minmax(280px, 1.6fr) minmax(240px, 1fr);
  gap: 12px;
  margin-bottom: 12px;
}

.unified-alert-center__filter label,
.unified-alert-center__filter > div {
  display: grid;
  min-width: 0;
  align-content: center;
  gap: 5px;
  padding: 10px 12px;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface-alt);
}

.unified-alert-center__filter span {
  color: var(--ui-muted);
  font-size: var(--ui-size-12);
  font-weight: var(--ui-weight-bold);
