}

.unified-alert-center__filter input {
  width: 100%;
  min-width: 0;
  height: 40px;
  padding: 8px 11px;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-control);
  color: var(--ui-text);
  background: var(--ui-surface);
  font: inherit;
}

.unified-alert-center__filter input:focus-visible {
  border-color: var(--ui-accent);
  outline: 3px solid color-mix(in srgb, var(--ui-accent) 18%, transparent);
  outline-offset: 1px;
}

.unified-alert-center__filter strong,
.unified-alert-center__filter small {
  overflow-wrap: anywhere;
}

.unified-alert-center__filter strong {
  color: var(--ui-text);
}

.unified-alert-center__filter small {
  color: var(--ui-chart-neutral);
}

.unified-alert-center__list {
  overflow: hidden;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface);
}

.unified-alert-center__row {
  display: grid;
  grid-template-columns: minmax(240px, 1.2fr) minmax(220px, 1fr) minmax(260px, 1.25fr);
  border-bottom: 1px solid var(--ui-border);
}

.unified-alert-center__row:last-child {
  border-bottom: 0;
}

.unified-alert-center__row > div {
  display: grid;
  min-width: 0;
  align-content: start;
  gap: 5px;
  padding: 12px 14px;
  border-right: 1px solid var(--ui-border);
}

.unified-alert-center__row > div:last-child {
  border-right: 0;
}

.unified-alert-center__row strong,
.unified-alert-center__row small {
  overflow-wrap: anywhere;
}

.unified-alert-center__row strong {
  color: var(--ui-text);
  line-height: 1.35;
}

.unified-alert-center__list-empty {
  padding: 22px 16px;
  color: var(--ui-muted);
  text-align: center;
}

.unified-alert-center__pager {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 10px;
  padding-top: 12px;
}

.unified-alert-center__pager span {
  color: var(--ui-muted);
  font-size: var(--ui-size-13);
  font-weight: var(--ui-weight-bold);
}

.unified-alert-center__empty {
  margin-top: 18px;
