  grid-template-columns: minmax(0, 1fr) 150px;
  align-items: end;
  gap: 14px;
  margin-bottom: 14px;
  padding: 14px;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface-alt);
}

.moodle-grade-course-issues__toolbar label,
.moodle-grade-course-issues__toolbar > div {
  display: grid;
  min-width: 0;
  gap: 6px;
}

.moodle-grade-course-issues__toolbar span {
  color: var(--ui-muted);
  font-size: var(--ui-size-12);
  font-weight: var(--ui-weight-bold);
  text-transform: uppercase;
}

.moodle-grade-course-issues__toolbar input {
  width: 100%;
  min-height: 44px;
  padding: 9px 12px;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface);
  color: var(--ui-text);
