}

.moodle-grade-course-issues__toolbar > div {
  min-height: 44px;
  align-content: center;
  padding: 7px 12px;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface);
}

.moodle-grade-course-issues__toolbar > div strong {
  color: var(--ui-text);
  font-size: var(--ui-size-18);
}

.moodle-grade-course-issues-table {
  min-width: 1120px;
  table-layout: fixed;
}

.moodle-grade-course-issues-table th:nth-child(1) { width: 5%; }

.moodle-grade-course-issues-table th:nth-child(2) { width: 18%; }

.moodle-grade-course-issues-table th:nth-child(3) { width: 22%; }

.moodle-grade-course-issues-table th:nth-child(4) { width: 13%; }

.moodle-grade-course-issues-table th:nth-child(5) { width: 32%; }

.moodle-grade-course-issues-table th:nth-child(6) { width: 10%; }

.moodle-grade-course-issues-table td strong,
.moodle-grade-course-issues-table td small,
.moodle-grade-course-issue-relations-table td strong,
.moodle-grade-course-issue-relations-table td small {
  display: block;
  overflow-wrap: anywhere;
}

.moodle-grade-course-issues-table td small,
.moodle-grade-course-issue-relations-table td small {
  margin-top: 4px;
  color: var(--ui-chart-neutral);
}

.moodle-grade-course-issues-table__message {
  overflow-wrap: anywhere;
  color: var(--ui-warning);
}

.moodle-grade-course-issues-table__detail {
  width: 100%;
  min-width: 86px;
  white-space: nowrap;
}

.moodle-grade-course-issues__notice {
  display: grid;
  gap: 5px;
  margin-bottom: 16px;
  padding: 13px 14px;
  border: 1px solid var(--ui-warning-border);
  border-left: 4px solid var(--ui-chart-gold);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-warning-soft);
}

.moodle-grade-course-issues__notice strong {
  color: var(--ui-text);
  font-size: var(--ui-size-16);
}

.moodle-grade-course-issues__notice span {
  color: var(--ui-warning);
  overflow-wrap: anywhere;
}

.moodle-grade-course-issues__grid {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.moodle-grade-course-issues__relations {
  margin-top: 22px;
  padding-top: 18px;
  border-top: 1px solid var(--ui-border);
}

.moodle-grade-course-issues__relations h3 {
  margin: 0;
  color: var(--ui-text);
  font-size: var(--ui-size-16);
}

.moodle-grade-course-issues__relations .moodle-table-wrap {
  margin-top: 12px;
}

.moodle-grade-course-issue-relations-table {
  min-width: 1080px;
  table-layout: fixed;
}

.moodle-grade-course-issue-relations-table th:nth-child(1) { width: 20%; }

.moodle-grade-course-issue-relations-table th:nth-child(2) { width: 22%; }

.moodle-grade-course-issue-relations-table th:nth-child(3) { width: 18%; }

.moodle-grade-course-issue-relations-table th:nth-child(4) { width: 17%; }

.moodle-grade-course-issue-relations-table th:nth-child(5) { width: 23%; }

@media (max-width: 1100px) {
  .moodle-grade-alert-summary {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .moodle-grade-alert-summary > div:nth-child(4n) {
    border-right: 1px solid var(--ui-border);
  }

  .moodle-grade-alert-summary > div:nth-child(2n) {
    border-right: 0;
  }

  .moodle-grade-alert-summary > div:nth-child(-n + 6) {
    border-bottom: 1px solid var(--ui-border);
  }

  .moodle-grade-alert-toolbar {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .moodle-grade-alert-toolbar__status {
    grid-column: 1 / -1;
  }

  .moodle-grade-alert-validation dl,
  .moodle-grade-alert-detail__grid,
  .moodle-grade-alert-detail__grid--result {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 720px) {
  .moodle-grade-alert-loading,
  .moodle-grade-alert-pagination,
  .moodle-grade-alert-errors {
    align-items: stretch;
    flex-direction: column;
  }

  .moodle-grade-alert-errors .moodle-button {
    width: 100%;
  }

  .moodle-grade-alert-indicator {
    grid-template-columns: 40px minmax(0, 1fr);
  }

  .moodle-grade-alert-indicator__count {
    width: 40px;
    height: 40px;
  }

  .moodle-grade-alert-indicator__action {
    grid-column: 1 / -1;
    width: 100%;
  }

  .moodle-grade-alert-summary,
  .moodle-grade-alert-toolbar,
  .moodle-grade-course-issues__toolbar {
    grid-template-columns: 1fr;
  }

  .moodle-grade-alert-summary > div,
  .moodle-grade-alert-summary > div:nth-child(2n),
  .moodle-grade-alert-summary > div:nth-child(4n),
  .moodle-grade-alert-summary > div:nth-child(-n + 6) {
    border-right: 0;
    border-bottom: 1px solid var(--ui-border);
  }

  .moodle-grade-alert-summary > div:last-child {
    border-bottom: 0;
  }

  .moodle-grade-alert-toolbar__status {
    grid-column: auto;
    grid-template-columns: 1fr;
  }

  .moodle-grade-alert-validation__heading,
  .moodle-grade-alert-detail__section-heading {
    align-items: flex-start;
    flex-direction: column;
  }

  .moodle-grade-alert-validation dl,
  .moodle-grade-alert-detail__grid,
  .moodle-grade-alert-detail__grid--result {
    grid-template-columns: 1fr;
  }

  .moodle-confirm-overlay {
    padding: 10px;
  }

  .moodle-grade-course-issues__body {
    max-height: calc(100vh - 150px);
  }

  .moodle-grade-alert-detail__body {
    max-height: none;
  }

  .moodle-grade-alert-detail__notice {
    grid-template-columns: 1fr;
  }
}

/* Histórico central de integraciones */

.integration-history-page {
  min-height: 100%;
  color: var(--ui-text);
  background: var(--ui-background);
  letter-spacing: 0;
}

.integration-history-hero {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  padding: 26px 28px;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface);
}

.integration-history-hero > div:first-child {
  min-width: 0;
}

.integration-history-hero > div:first-child > span,
.integration-history-section-head span {
  display: block;
  margin-bottom: 7px;
  color: var(--ui-chart-neutral);
  font-size: var(--ui-size-11);
  font-weight: var(--ui-weight-bold);
  text-transform: uppercase;
  letter-spacing: 0;
}

.integration-history-hero h1 {
  margin: 0;
  font-size: var(--ui-size-32);
  line-height: 1.15;
}

.integration-history-hero p {
  max-width: 860px;
  margin: 10px 0 0;
  color: var(--ui-text-secondary);
  line-height: 1.5;
}

.integration-history-user {
  display: grid;
  flex: 0 0 auto;
  gap: 5px;
  min-width: 190px;
  padding: 14px 16px;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface-alt);
}

.integration-history-user strong {
  overflow-wrap: anywhere;
}

.integration-history-user span {
  color: var(--ui-chart-neutral);
  font-size: var(--ui-size-12);
}

.integration-history-summary {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  margin-top: 14px;
  overflow: hidden;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface);
