.integration-history-summary article {
  min-width: 0;
  min-height: 104px;
  padding: 17px 18px;
  border-right: 1px solid var(--ui-border);
}

.integration-history-summary article:last-child {
  border-right: 0;
}

.integration-history-summary span {
  display: block;
  min-height: 34px;
  color: var(--ui-muted);
  font-size: var(--ui-size-12);
  font-weight: var(--ui-weight-bold);
  line-height: 1.35;
  text-transform: uppercase;
