.integration-history-tabs button,
.integration-history-page button {
  min-height: 40px;
  padding: 9px 15px;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-control);
  color: var(--ui-text);
  background: var(--ui-surface-alt);
  font: inherit;
  font-weight: var(--ui-weight-bold);
  cursor: pointer;
