.integration-history-table th:nth-child(5) { width: 75px; }

.integration-history-table th:nth-child(6) { width: 175px; }

.integration-history-table th:nth-child(7) { width: 230px; }

.integration-history-table th:nth-child(8) { width: 80px; }

.integration-history-table--reports th:nth-child(2) { width: 230px; }

.integration-history-table--reports th:nth-child(3) { width: 210px; }

.integration-history-table--reports th:nth-child(4) { width: 230px; }

.integration-history-table--reports th:nth-child(5),
.integration-history-table--reports th:nth-child(6) { width: 105px; }

.integration-history-badge {
  display: inline-flex;
  align-items: center;
  min-height: 26px;
  padding: 4px 8px;
  border-radius: var(--ui-radius-control);
  color: var(--ui-accent-hover);
  background: var(--ui-neutral-soft);
  font-size: var(--ui-size-11);
  font-weight: var(--ui-weight-bold);
}

.integration-history-badge--insert,
.integration-history-badge--success {
  color: var(--ui-success);
  background: var(--ui-neutral-soft);
}

.integration-history-badge--update {
  color: var(--ui-warning);
  background: var(--ui-warning-soft);
}

.integration-history-badge--delete {
  color: var(--ui-primary);
  background: var(--ui-primary-soft);
}

.integration-history-empty {
  height: 96px;
  color: var(--ui-chart-neutral);
  text-align: center !important;
  vertical-align: middle !important;
}

.integration-history-loading {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  min-height: 120px;
  color: var(--ui-accent-hover);
  background: color-mix(in srgb, var(--ui-surface) 88%, transparent);
  font-weight: var(--ui-weight-bold);
}

.integration-history-pagination {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  padding: 14px 0 0;
}

.integration-history-pagination > div {
  display: flex;
  align-items: center;
  gap: 7px;
}

.integration-history-pagination span {
  min-width: 112px;
  text-align: center;
  font-weight: var(--ui-weight-bold);
}

.integration-history-coverage {
  margin-top: 14px;
  padding-top: 12px;
  border-top: 1px solid var(--ui-border);
  color: var(--ui-chart-neutral);
  font-size: var(--ui-size-12);
}

.integration-history-modal-backdrop {
  position: fixed;
  z-index: 2200;
  inset: 0;
  display: grid;
  place-items: center;
  padding: 24px;
  background: color-mix(in srgb, var(--ui-text) 58%, transparent);
}

.integration-history-modal {
  width: min(1080px, 100%);
  max-height: calc(100vh - 48px);
  overflow: auto;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface);
  box-shadow: var(--ui-shadow-dialog);
}

.integration-history-modal > header {
  position: sticky;
  z-index: 2;
  top: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding: 17px 20px;
  border-bottom: 1px solid var(--ui-border);
  background: var(--ui-surface-alt);
}

.integration-history-modal > header span,
.integration-history-detail-field > span {
  display: block;
  margin-bottom: 5px;
  color: var(--ui-chart-neutral);
  font-size: var(--ui-size-11);
  font-weight: var(--ui-weight-bold);
  text-transform: uppercase;
}

.integration-history-modal h2 {
  margin: 0;
  font-size: var(--ui-size-20);
}

.integration-history-modal-state {
  margin: 20px;
}

.integration-history-modal .integration-history-alert {
  margin: 20px;
}

.integration-history-detail-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1px;
  padding: 1px;
  background: var(--ui-border);
}

.integration-history-detail-field {
  min-width: 0;
  min-height: 82px;
  padding: 13px 15px;
  background: var(--ui-surface);
}

.integration-history-detail-field--wide {
  grid-column: 1 / -1;
}

.integration-history-detail-field strong {
  display: block;
  overflow-wrap: anywhere;
}

.integration-history-detail-field pre {
  max-height: 310px;
  margin: 0;
  overflow: auto;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  color: var(--ui-text);
  font: 12px/1.5 Consolas, monospace;
}

/* Consulta administrativa de documentos de cumplimiento docente */

.compliance-documents-summary {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.compliance-invoice-entry {
  display: grid;
  grid-template-columns: minmax(300px, 0.9fr) minmax(420px, 1.5fr) auto;
  align-items: end;
  gap: 18px;
  padding: 18px 20px;
  border: 1px solid var(--ui-border);
  border-left: 4px solid var(--ui-accent);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface-alt);
  box-shadow: var(--ui-shadow-sm);
}

.compliance-invoice-entry__intro,
.compliance-invoice-entry__target {
  display: grid;
  gap: 6px;
  min-width: 0;
}

.compliance-invoice-entry__intro > span,
.compliance-invoice-entry__target > span {
  color: var(--ui-muted);
  font-size: var(--ui-size-11);
  font-weight: var(--ui-weight-bold);
  text-transform: uppercase;
}

.compliance-invoice-entry__intro h2,
.compliance-invoice-entry__intro p {
  margin: 0;
}

.compliance-invoice-entry__intro h2 {
  font-size: var(--ui-size-20);
}

.compliance-invoice-entry__intro p,
.compliance-invoice-entry__target small {
  color: var(--ui-muted);
  line-height: 1.45;
  overflow-wrap: anywhere;
}

.compliance-invoice-entry__target select {
  width: 100%;
  min-height: 44px;
  padding: 9px 12px;
  border: 1px solid var(--ui-border-strong);
  border-radius: var(--ui-radius-control);
  color: var(--ui-text);
  background: var(--ui-surface);
  font: inherit;
}

.integration-history-page .compliance-invoice-entry__action {
  min-width: 180px;
  min-height: 44px;
  white-space: nowrap;
}

.compliance-documents-filters {
  grid-template-columns: minmax(280px, 2fr) minmax(190px, 1fr) repeat(2, minmax(155px, 0.8fr)) auto;
}

.compliance-documents-table {
  min-width: 1200px;
}

.compliance-documents-table th:nth-child(1) { width: 145px; }

.compliance-documents-table th:nth-child(2) { width: 220px; }

.compliance-documents-table th:nth-child(3) { width: 260px; }

.compliance-documents-table th:nth-child(4) { width: 275px; }

.compliance-documents-table th:nth-child(5) { width: 110px; }

.compliance-documents-table th:nth-child(6) { width: 270px; }

.compliance-documents-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
}

.compliance-documents-link {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 34px;
  padding: 7px 10px;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-control);
  color: var(--ui-text);
  background: var(--ui-surface-alt);
  font-size: var(--ui-size-12);
  font-weight: var(--ui-weight-bold);
  text-decoration: none;
}

.compliance-documents-link:hover {
  border-color: var(--ui-accent-border);
  background: var(--ui-neutral-soft);
}

.compliance-documents-link--primary {
  border-color: var(--ui-accent);
  color: var(--ui-on-primary);
  background: var(--ui-accent);
}

.compliance-documents-link--primary:hover {
  color: var(--ui-on-primary);
  background: var(--ui-accent-hover);
}

.integration-history-page .compliance-documents-upload {
  min-height: 34px;
  padding: 7px 10px;
  border-color: var(--ui-chart-gold);
  color: var(--ui-warning);
  background: var(--ui-warning-soft);
  font-size: var(--ui-size-12);
}

.integration-history-page .compliance-documents-upload:hover:not(:disabled) {
  border-color: var(--ui-warning);
  color: var(--ui-primary-hover);
  background: var(--ui-warning-soft);
}

.compliance-documents-unavailable {
  color: var(--ui-disabled-text);
  font-size: var(--ui-size-12);
  font-weight: var(--ui-weight-bold);
}

.compliance-document-type--notas {
  color: var(--ui-info);
  background: var(--ui-neutral-soft);
}

.compliance-document-type--contrato {
  color: var(--ui-warning);
  background: var(--ui-warning-soft);
}

.compliance-document-type--paquete {
  color: var(--ui-text-secondary);
  background: var(--ui-neutral-soft);
}

.compliance-document-type--factura_xml {
  color: var(--ui-success);
  background: var(--ui-neutral-soft);
}

.compliance-document-type--ride {
  color: var(--ui-warning);
  background: var(--ui-warning-soft);
}

.compliance-document-type--carpeta {
  color: var(--ui-text-secondary);
  background: var(--ui-neutral-soft);
}

.compliance-invoice-modal {
  width: min(820px, 100%);
  overflow: hidden;
}

.compliance-invoice-modal__body {
  display: grid;
  gap: 16px;
  max-height: calc(100vh - 132px);
  padding: 20px;
  overflow-y: auto;
}

.compliance-invoice-context {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1px;
  overflow: hidden;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-border);
}

.compliance-invoice-context > div {
  display: grid;
  align-content: start;
  gap: 5px;
  min-width: 0;
  padding: 13px 14px;
  background: var(--ui-surface-alt);
}

.compliance-invoice-context span,
.compliance-invoice-files label > span {
  color: var(--ui-muted);
  font-size: var(--ui-size-11);
  font-weight: var(--ui-weight-bold);
  text-transform: uppercase;
}

.compliance-invoice-context strong,
.compliance-invoice-context small {
  overflow-wrap: anywhere;
}

.compliance-invoice-context small,
.compliance-invoice-files small {
  color: var(--ui-chart-neutral);
  line-height: 1.4;
}

.compliance-invoice-help {
  margin: 0;
  padding: 11px 13px;
  border-left: 3px solid var(--ui-accent);
  color: var(--ui-accent-hover);
  background: var(--ui-accent-soft);
  line-height: 1.45;
}

.compliance-invoice-files {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.compliance-invoice-files label {
  display: grid;
  align-content: start;
  gap: 8px;
  min-width: 0;
  padding: 14px;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface);
}

.compliance-invoice-files input[type='file'] {
  width: 100%;
  min-width: 0;
  padding: 8px;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-control);
  color: var(--ui-text);
  background: var(--ui-surface-alt);
  font: inherit;
}

.compliance-invoice-modal .integration-history-alert {
  margin: 0;
}

.compliance-invoice-modal__actions {
  display: flex;
  justify-content: flex-end;
  gap: 9px;
  padding-top: 2px;
}

@media (max-width: 1280px) {
  .integration-history-summary {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .integration-history-summary article:nth-child(3) {
    border-right: 0;
  }

  .integration-history-summary article:nth-child(-n + 3) {
    border-bottom: 1px solid var(--ui-border);
  }

  .integration-history-filters {
    grid-template-columns: minmax(240px, 2fr) repeat(2, minmax(150px, 1fr));
  }

  .integration-history-filter-actions {
    justify-content: flex-end;
  }

  .compliance-documents-filters {
    grid-template-columns: minmax(240px, 2fr) repeat(2, minmax(160px, 1fr));
  }

  .compliance-invoice-entry {
    grid-template-columns: minmax(280px, 0.8fr) minmax(360px, 1.2fr);
  }

  .compliance-invoice-entry__action {
    grid-column: 2;
    justify-self: end;
  }
}

@media (max-width: 760px) {
  .integration-history-hero {
    align-items: stretch;
    flex-direction: column;
    padding: 20px;
  }

  .integration-history-hero h1 {
    font-size: var(--ui-size-28);
  }

  .integration-history-user {
    width: 100%;
  }

  .integration-history-summary {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .integration-history-summary article,
  .integration-history-summary article:nth-child(3) {
    border-right: 1px solid var(--ui-border);
    border-bottom: 1px solid var(--ui-border);
  }

  .integration-history-summary article:nth-child(2n) {
    border-right: 0;
  }

  .integration-history-summary article:nth-last-child(-n + 2) {
    border-bottom: 0;
  }

  .integration-history-tabs,
  .integration-history-filters,
  .integration-history-detail-grid {
    grid-template-columns: 1fr;
  }

  .compliance-documents-summary {
    grid-template-columns: 1fr;
  }

  .compliance-documents-summary article,
  .compliance-documents-summary article:nth-child(2n),
  .compliance-documents-summary article:nth-child(3) {
    border-right: 0;
    border-bottom: 1px solid var(--ui-border);
  }

  .compliance-documents-summary article:last-child {
    border-bottom: 0;
  }

  .compliance-invoice-entry {
    grid-template-columns: 1fr;
    align-items: stretch;
  }

  .compliance-invoice-entry__action {
    grid-column: auto;
    justify-self: stretch;
    width: 100%;
  }

  .integration-history-tabs button {
    border-right: 0;
    border-bottom: 1px solid var(--ui-border);
  }

  .integration-history-tabs button:last-child {
    border-bottom: 0;
  }

  .integration-history-workspace {
    padding: 16px;
  }

  .integration-history-section-head,
  .integration-history-pagination {
    align-items: stretch;
    flex-direction: column;
  }

  .integration-history-section-head > button,
  .integration-history-filter-actions button {
    flex: 1;
  }

  .integration-history-pagination > div {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .integration-history-pagination span {
    grid-column: 1 / -1;
    grid-row: 1;
  }

  .integration-history-modal-backdrop {
    padding: 10px;
  }

  .integration-history-modal {
    max-height: calc(100vh - 20px);
  }

  .integration-history-detail-field--wide {
    grid-column: auto;
  }

  .compliance-invoice-context,
  .compliance-invoice-files {
    grid-template-columns: 1fr;
  }

  .compliance-invoice-modal__actions {
    display: grid;
    grid-template-columns: 1fr;
  }
}

/* Actualizacion de correo institucional */

.institutional-email-page {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  grid-auto-flow: row;
  align-content: start;
  gap: 14px;
  width: 100%;
  max-width: 100%;
  min-width: 0;
}

.institutional-email-page > * {
  grid-column: 1 / -1;
  width: 100%;
  min-width: 0;
}

.institutional-email-page > .student-topbar {
  min-height: 0;
  padding: 18px 20px;
}

.institutional-email-page > .student-topbar .report-description {
  max-width: none;
  margin-top: 8px;
}

.institutional-email-submenu {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface);
}

.institutional-email-submenu button {
  display: grid;
  gap: 4px;
  min-width: 0;
  min-height: 66px;
  border: 0;
  border-right: 1px solid var(--line);
  border-radius: 0;
  padding: 12px 16px;
  background: var(--ui-surface);
  color: var(--ui-muted);
  text-align: left;
  cursor: pointer;
}

.institutional-email-submenu button:last-child {
  border-right: 0;
}

.institutional-email-submenu button:hover,
.institutional-email-submenu button:focus-visible {
  background: var(--ui-surface-alt);
}

.institutional-email-submenu button:focus-visible {
  outline: 2px solid color-mix(in srgb, var(--ui-accent) 32%, transparent);
  outline-offset: -2px;
}

.institutional-email-submenu button.is-active {
  box-shadow: inset 0 -3px 0 var(--ui-accent);
  background: var(--ui-success-soft);
  color: var(--ui-accent-hover);
}

.institutional-email-submenu strong,
.institutional-email-submenu span {
  display: block;
  min-width: 0;
  overflow-wrap: anywhere;
}

.institutional-email-submenu strong {
  color: var(--ink);
  font-size: var(--ui-size-14);
}

.institutional-email-submenu span {
  font-size: var(--ui-size-12);
  line-height: 1.35;
}

.institutional-email-search-card,
.institutional-email-bulk-card {
  width: 100%;
  min-width: 0;
}

.institutional-email-search-card .card-head h3,
.institutional-email-bulk-card .card-head h3 {
  margin: 2px 0 0;
  color: var(--ink);
}

.institutional-email-bulk-card .card-head {
  align-items: flex-end;
  margin-bottom: 0;
}

.institutional-email-bulk-card .card-head > span {
  padding-bottom: 2px;
  text-align: right;
}

.institutional-email-search {
  display: grid;
  grid-template-columns: minmax(280px, 1fr) auto auto;
  gap: 10px;
  align-items: end;
  margin-top: 14px;
}

.institutional-email-search label,
.institutional-email-file,
.institutional-email-action-control,
.institutional-email-edit-form label {
  display: grid;
  gap: 6px;
  min-width: 0;
  color: var(--ui-muted);
  font-size: var(--ui-size-12);
  font-weight: var(--ui-weight-bold);
}

.institutional-email-search input,
.institutional-email-file input,
.institutional-email-edit-form input {
  width: 100%;
  min-width: 0;
  min-height: 43px;
  border: 1px solid var(--line);
  border-radius: var(--ui-radius-panel);
  padding: 9px 11px;
  background: var(--ui-surface);
  color: var(--ink);
  font: inherit;
}

.institutional-email-search input:focus,
.institutional-email-file input:focus,
.institutional-email-edit-form input:focus {
  border-color: var(--ui-accent);
  outline: 2px solid color-mix(in srgb, var(--ui-accent) 14%, transparent);
  outline-offset: 1px;
}

.institutional-email-table-wrap {
  max-height: min(58vh, 660px);
}

.institutional-email-table {
  min-width: 1120px;
  table-layout: fixed;
}

.institutional-email-table th:nth-child(1) { width: 250px; }

.institutional-email-table th:nth-child(2) { width: 130px; }

.institutional-email-table th:nth-child(3) { width: 220px; }

.institutional-email-table th:nth-child(4) { width: 250px; }

.institutional-email-table th:nth-child(5) { width: 165px; }

.institutional-email-table th:nth-child(6) { width: 185px; }

.institutional-email-table th:nth-child(7) { width: 120px; }

.institutional-email-table thead th {
  position: sticky;
  top: 0;
  z-index: 3;
  box-shadow: var(--ui-shadow-sm);
}

.institutional-email-table th:first-child,
.institutional-email-table td:first-child {
  width: 250px;
  text-align: left;
  color: var(--ink-soft);
}

.institutional-email-table td {
  vertical-align: middle;
  overflow-wrap: anywhere;
}

.institutional-email-table td strong,
.institutional-email-table td small {
  display: block;
}

.institutional-email-table td small {
  margin-top: 4px;
  color: var(--ui-chart-neutral);
}

.institutional-email-address {
  word-break: break-word;
}

.institutional-email-empty {
  padding: 24px !important;
  text-align: center !important;
  color: var(--ui-chart-neutral);
}

.institutional-email-badge {
  display: inline-flex;
  align-items: center;
  min-height: 28px;
  border-radius: var(--ui-radius-control);
  padding: 5px 8px;
  font-size: var(--ui-size-11);
  font-weight: var(--ui-weight-bold);
  line-height: 1.2;
}

.institutional-email-badge--ready {
  color: var(--ui-success);
  background: var(--ui-success-soft);
}

.institutional-email-badge--pending {
  color: var(--ui-warning);
  background: var(--ui-warning-soft);
}

.institutional-email-badge--warning {
  color: var(--ui-warning);
  background: var(--ui-warning-soft);
}

.institutional-email-badge--error {
  color: var(--ui-primary);
  background: var(--ui-primary-soft);
}

.institutional-email-pagination {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 14px;
  margin-top: 12px;
  color: var(--ui-muted);
  font-size: var(--ui-size-12);
  font-weight: var(--ui-weight-bold);
}

.institutional-email-pagination > div {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
  flex-wrap: wrap;
}

.institutional-email-pagination strong {
  min-width: 105px;
  text-align: center;
  color: var(--ink);
}

.institutional-email-bulk-actions {
  display: grid;
  grid-template-columns: minmax(220px, 0.7fr) minmax(360px, 2fr) minmax(190px, 0.6fr);
  align-items: stretch;
  gap: 12px;
  margin-top: 16px;
}

.institutional-email-action-control,
.institutional-email-file {
  grid-template-rows: 17px 44px;
  align-content: end;
}

.institutional-email-action-control > span,
.institutional-email-file > span {
  display: flex;
  align-items: center;
  min-width: 0;
  line-height: 17px;
}

.institutional-email-action-control > button,
.institutional-email-file > input {
  width: 100%;
  height: 44px;
  min-height: 44px;
  margin: 0;
}

.institutional-email-action-control > button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.institutional-email-bulk-guide {
  margin: 12px 0 0;
  padding: 10px 12px;
  border-left: 3px solid var(--ui-accent);
  background: var(--ui-surface-alt);
  color: var(--ui-text-secondary);
  font-size: var(--ui-size-13);
  line-height: 1.45;
}

.institutional-email-file input {
  padding: 4px 6px;
  overflow: hidden;
}

.institutional-email-file input::file-selector-button {
  height: 34px;
  margin: 0 10px 0 0;
  border: 1px solid var(--line-strong);
  border-radius: var(--ui-radius-control);
  padding: 0 12px;
  background: color-mix(in srgb, var(--ui-accent-border) 15%, transparent);
  color: var(--ink);
  cursor: pointer;
  font: inherit;
  font-weight: var(--ui-weight-bold);
}

.institutional-email-file input::file-selector-button:hover {
  background: color-mix(in srgb, var(--ui-accent-border) 24%, transparent);
}

.institutional-email-analysis-summary {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  margin-top: 14px;
  padding: 10px;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface-alt);
}

.institutional-email-analysis-summary > span {
  min-width: 120px;
  color: var(--ui-muted);
  font-size: var(--ui-size-12);
}

.institutional-email-analysis-summary strong {
  margin-left: 4px;
  color: var(--ink);
  font-size: var(--ui-size-16);
}

.institutional-email-analysis-summary .primary-action {
  margin-left: auto;
}

.institutional-email-preview-wrap {
  max-height: 420px;
}

.institutional-email-preview-table {
  min-width: 1200px;
}

.institutional-email-modal-overlay {
  position: fixed;
  inset: 0;
  z-index: 1300;
  display: grid;
  place-items: center;
  padding: 20px;
  background: color-mix(in srgb, var(--ui-text) 58%, transparent);
  backdrop-filter: blur(2px);
}

.institutional-email-notification-overlay {
  position: fixed;
  inset: 0;
  z-index: 1450;
  display: grid;
  place-items: center;
  padding: 20px;
  background: color-mix(in srgb, var(--ui-text) 38%, transparent);
  backdrop-filter: blur(2px);
}

.institutional-email-notification {
  position: relative;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  gap: 14px;
  width: min(560px, 100%);
  overflow: hidden;
  border: 1px solid var(--ui-success-border);
  border-radius: var(--ui-radius-panel);
  padding: 20px 20px 24px;
  background: var(--ui-surface);
  box-shadow: var(--ui-shadow-sm);
}

.institutional-email-notification__mark {
  display: grid;
  place-items: center;
  width: 42px;
  height: 42px;
  border-radius: 50%;
  background: var(--ui-success-soft);
  color: var(--ui-success);
  font-size: var(--ui-size-24);
  font-weight: var(--ui-weight-bold);
}

.institutional-email-notification .eyebrow {
  margin: 0 0 4px;
  color: var(--ui-success);
}

.institutional-email-notification h3 {
  margin: 0;
  color: var(--ink);
  font-size: var(--ui-size-18);
  line-height: 1.35;
}

.institutional-email-notification small {
  display: block;
  margin-top: 6px;
  color: var(--ui-chart-neutral);
}

.institutional-email-notification__timer {
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;
  height: 4px;
  transform-origin: left center;
  background: var(--ui-accent);
  animation: institutional-email-notification-timer 3s linear forwards;
}

@keyframes institutional-email-notification-timer {
  from { transform: scaleX(1); }
  to { transform: scaleX(0); }
}

@media (prefers-reduced-motion: reduce) {
  .institutional-email-notification__timer {
    animation: none;
  }
}

.institutional-email-modal,
.institutional-email-confirm-modal {
  width: min(920px, 100%);
  max-height: calc(100vh - 40px);
  overflow: auto;
  border: 1px solid var(--line);
  border-radius: var(--ui-radius-panel);
  padding: 18px;
  background: var(--ui-surface);
  box-shadow: var(--ui-shadow-dialog);
}

.institutional-email-confirm-modal {
  width: min(580px, 100%);
}

.institutional-email-modal > header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 14px;
  padding-bottom: 14px;
  border-bottom: 1px solid var(--line);
}

.institutional-email-modal h3,
.institutional-email-confirm-modal h3 {
  margin: 2px 0 0;
  color: var(--ink);
}

.institutional-email-student-summary {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
  margin: 14px 0;
}

.institutional-email-student-summary > span {
  min-width: 0;
  padding: 10px;
  border: 1px solid var(--line);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface-alt);
}

.institutional-email-student-summary small,
.institutional-email-student-summary strong {
  display: block;
}

.institutional-email-student-summary small {
  margin-bottom: 5px;
  color: var(--ui-chart-neutral);
}

.institutional-email-student-summary strong {
  overflow-wrap: anywhere;
  color: var(--ink);
}

.institutional-email-edit-form {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.institutional-email-password-field {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 8px;
}

.institutional-email-security-note {
  grid-column: 1 / -1;
  margin: 0;
  padding: 9px 10px;
  border-left: 3px solid var(--ui-accent);
  background: var(--ui-accent-soft);
  color: var(--ui-text-secondary);
  font-size: var(--ui-size-12);
}

.institutional-email-modal-actions {
  grid-column: 1 / -1;
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  margin-top: 4px;
}

.institutional-email-confirm-modal > p:not(.eyebrow) {
  color: var(--ui-text-secondary);
  line-height: 1.6;
}

@media (max-width: 980px) {
  .institutional-email-bulk-actions {
    grid-template-columns: 1fr 1fr;
  }

  .institutional-email-file {
    grid-column: 1 / -1;
    grid-row: 1;
  }

  .institutional-email-student-summary {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 720px) {
  .institutional-email-page > .student-topbar {
    padding: 15px;
  }

  .institutional-email-search,
  .institutional-email-bulk-actions,
  .institutional-email-edit-form {
    grid-template-columns: 1fr;
  }

  .institutional-email-submenu {
    grid-template-columns: 1fr;
  }

  .institutional-email-submenu button {
    border-right: 0;
    border-bottom: 1px solid var(--line);
  }

  .institutional-email-submenu button:last-child {
    border-bottom: 0;
  }

  .institutional-email-file,
  .institutional-email-security-note,
  .institutional-email-modal-actions {
    grid-column: 1;
  }

  .institutional-email-pagination {
    align-items: stretch;
    flex-direction: column;
  }

  .institutional-email-pagination > div,
  .institutional-email-modal-actions {
    justify-content: stretch;
  }

  .institutional-email-pagination button,
  .institutional-email-modal-actions button,
  .institutional-email-bulk-actions button,
  .institutional-email-search button {
    flex: 1;
    width: 100%;
  }

  .institutional-email-student-summary {
    grid-template-columns: 1fr;
  }

  .institutional-email-analysis-summary .primary-action {
    width: 100%;
    margin-left: 0;
  }

  .institutional-email-modal-overlay {
    padding: 8px;
  }

  .institutional-email-modal,
  .institutional-email-confirm-modal {
    max-height: calc(100vh - 16px);
    padding: 14px;
  }
}

.screen-access-item .screen-access-item__code {
  color: var(--ui-accent);
  font-family: var(--ui-font-mono);
  font-size: var(--ui-size-11);
  overflow-wrap: anywhere;
}

.screen-access-item--checked {
  border-color: color-mix(in srgb, var(--ui-accent) 42%, transparent);
  background: color-mix(in srgb, var(--ui-accent) 8%, transparent);
}

@media (max-width: 1180px) {
  .screen-access-groups {
    columns: 1;
  }
}

@media (max-width: 860px) {
  .screen-access-layout {
    grid-template-columns: 1fr;
  }

  .screen-access-toolbar {
    grid-template-columns: 1fr 1fr;
  }

  .screen-access-toolbar label,
  .screen-access-sync-copy {
    grid-column: 1 / -1;
  }

  .screen-access-sync-copy {
    justify-items: start;
    border-top: 1px solid var(--line);
    border-left: 0;
    padding-top: 10px;
    padding-left: 0;
    text-align: left;
  }

  .screen-access-role-catalog {
    grid-template-columns: 1fr;
  }

  .screen-access-editor-toolbar {
    grid-template-columns: 1fr;
  }

  .screen-access-editor-toolbar > div {
    justify-items: start;
  }

  .senescyt-update-subscreen.screen-access-subscreen {
    height: calc(100dvh - 20px);
    max-height: calc(100dvh - 20px);
  }

  .screen-access-subscreen__body > .senescyt-update-summary {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 720px) {
  .screen-access-source {
    width: 100%;
    min-width: 0;
    justify-items: start;
    text-align: left;
  }

  .senescyt-update-subscreen-backdrop.screen-access-subscreen-backdrop {
    padding: 6px;
  }

  .senescyt-update-subscreen.screen-access-subscreen {
    height: calc(100dvh - 12px);
    max-height: calc(100dvh - 12px);
    border-radius: var(--ui-radius-panel);
  }

  .screen-access-subscreen .senescyt-update-subscreen__head {
    gap: 10px;
    padding: 12px 14px;
  }

  .screen-access-subscreen .senescyt-update-subscreen__actions {
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
  }

  .screen-access-subscreen .senescyt-update-subscreen__actions button {
    min-height: 38px;
  }

  .screen-access-subscreen__body {
    scrollbar-gutter: auto;
    padding: 10px;
  }

  .screen-access-actions {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .screen-access-actions__status {
    grid-column: 1 / -1;
    min-width: 0;
  }

  .screen-access-actions button {
    width: 100%;
  }

  .screen-access-summary-table {
    min-width: 0;
  }

  .screen-access-summary-table thead {
    display: none;
  }

  .screen-access-summary-table tbody {
    display: grid;
    gap: 10px;
    padding: 10px;
  }

  .screen-access-summary-table tr {
    display: grid;
    overflow: hidden;
    border: 1px solid var(--line);
    border-radius: var(--ui-radius-panel);
    background: var(--ui-surface);
  }

  .screen-access-summary-table td,
  .screen-access-summary-table tr:last-child td {
    display: grid;
    grid-template-columns: minmax(112px, 0.42fr) minmax(0, 1fr);
    gap: 10px;
    align-items: center;
    border-bottom: 1px solid var(--line);
    padding: 9px 10px;
  }

  .screen-access-summary-table td::before {
    content: attr(data-label);
    color: var(--ui-chart-neutral);
    font-size: var(--ui-size-11);
    font-weight: var(--ui-weight-bold);
    letter-spacing: 0;
    text-transform: uppercase;
  }

  .screen-access-summary-table td:last-child {
    border-bottom: 0;
  }

  .screen-access-summary-table td:last-child button {
    width: 100%;
  }
}

@media (max-width: 560px) {
  .screen-access-group__head {
    align-items: stretch;
    flex-direction: column;
  }

  .screen-access-subscreen__body > .senescyt-update-summary,
  .screen-access-grid,
  .screen-access-toolbar {
    grid-template-columns: 1fr;
  }

  .screen-access-toolbar label,
  .screen-access-sync-copy {
    grid-column: auto;
  }

  .screen-access-actions {
    grid-template-columns: 1fr;
  }

  .screen-access-actions__status {
    grid-column: auto;
  }

  .screen-access-item {
    min-height: 68px;
  }

  .screen-access-role-card__head,
  .screen-access-role-card__footer {
    align-items: flex-start;
    flex-direction: column;
  }

  .screen-access-role-card__head small,
  .screen-access-role-card__footer small {
    text-align: left;
  }
}

.gestion-sis-homo-bulk {
  margin: 0 0 14px;
  padding: 14px;
  border: 1px solid color-mix(in srgb, var(--ui-accent-border) 42%, transparent);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface);
  box-shadow: var(--ui-shadow-sm);
}

.gestion-sis-homo-bulk__head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 12px;
}

.gestion-sis-homo-bulk__head div,
.gestion-sis-homo-bulk__head strong,
.gestion-sis-homo-bulk__head span {
  display: block;
}

.gestion-sis-homo-bulk__head strong {
  color: var(--ink);
  font-size: var(--ui-size-16);
}

.gestion-sis-homo-bulk__head span {
  margin-top: 3px;
  color: var(--ui-muted);
  font-size: var(--ui-size-12);
  line-height: 1.4;
}

.gestion-sis-homo-bulk__head em {
  flex: 0 0 auto;
  border: 1px solid color-mix(in srgb, var(--ui-danger) 24%, transparent);
  border-radius: var(--ui-radius-panel);
  padding: 7px 10px;
  background: color-mix(in srgb, var(--ui-danger) 8%, transparent);
  color: var(--ui-danger);
  font-size: var(--ui-size-12);
  font-style: normal;
  font-weight: var(--ui-weight-bold);
}

.gestion-sis-homo-bulk__form {
  grid-template-columns: repeat(12, minmax(0, 1fr));
}

.gestion-sis-homo-bulk__form label {
  grid-column: span 3;
}

.gestion-sis-homo-bulk__form .gestion-sis-field--wide {
  grid-column: 1 / -1;
}

.gestion-sis-homo-bulk__form input[readonly] {
  background: color-mix(in srgb, var(--ui-accent-border) 12%, transparent);
  color: var(--ui-text);
  font-weight: var(--ui-weight-bold);
}

.gestion-sis-homo-picker {
  display: grid;
  gap: 8px;
  border: 1px solid color-mix(in srgb, var(--ui-accent-border) 42%, transparent);
  border-radius: var(--ui-radius-panel);
  padding: 12px;
  background: color-mix(in srgb, var(--ui-surface) 70%, transparent);
}

.gestion-sis-homo-picker > span,
.gestion-sis-homo-picker strong,
.gestion-sis-homo-picker small {
  display: block;
}

.gestion-sis-homo-picker > span {
  color: var(--ui-muted);
  font-size: var(--ui-size-12);
  font-weight: var(--ui-weight-bold);
}

.gestion-sis-homo-picker div {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.gestion-sis-homo-picker strong {
  color: var(--ink);
  font-size: var(--ui-size-14);
}

.gestion-sis-homo-picker small {
  color: var(--ui-chart-neutral);
  font-size: var(--ui-size-12);
  line-height: 1.4;
}

.gestion-sis-homo-bulk__toolbar {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 8px;
  margin: 12px 0;
}

.gestion-sis-homo-bulk__finder {
  margin-top: 12px;
  border: 1px solid color-mix(in srgb, var(--ui-border-strong) 68%, transparent);
  border-radius: var(--ui-radius-panel);
  padding: 12px;
  background: color-mix(in srgb, var(--ui-surface) 72%, transparent);
}

.gestion-sis-homo-bulk__finder-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 10px;
}

.gestion-sis-homo-bulk__finder-head strong,
.gestion-sis-homo-bulk__finder-head span {
  display: block;
}

.gestion-sis-homo-bulk__finder-head strong {
  color: var(--ink);
  font-size: var(--ui-size-13);
  text-transform: uppercase;
}

.gestion-sis-homo-bulk__finder-head span {
  color: var(--ui-chart-neutral);
  font-size: var(--ui-size-12);
  font-weight: var(--ui-weight-bold);
}

.gestion-sis-homo-bulk__results,
.gestion-sis-homo-bulk__selected-list {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 8px;
  max-height: 320px;
  overflow: auto;
  padding-right: 4px;
}

.gestion-sis-homo-bulk__result,
.gestion-sis-homo-bulk__selected,
.gestion-sis-homo-bulk__materia {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  min-height: 62px;
  border: 1px solid color-mix(in srgb, var(--ui-border-strong) 78%, transparent);
  border-radius: var(--ui-radius-panel);
  padding: 10px;
  background: color-mix(in srgb, var(--ui-surface) 88%, transparent);
  cursor: pointer;
  text-align: left;
}

.gestion-sis-homo-bulk__materia input {
  width: 18px;
  height: 18px;
  accent-color: var(--rojo);
}

.gestion-sis-homo-bulk__result span,
.gestion-sis-homo-bulk__result strong,
.gestion-sis-homo-bulk__result small,
.gestion-sis-homo-bulk__result em,
.gestion-sis-homo-bulk__selected span,
.gestion-sis-homo-bulk__selected strong,
.gestion-sis-homo-bulk__selected small,
.gestion-sis-homo-bulk__selected em,
.gestion-sis-homo-bulk__materia span,
.gestion-sis-homo-bulk__materia strong,
.gestion-sis-homo-bulk__materia small {
  display: block;
}

.gestion-sis-homo-bulk__result strong,
.gestion-sis-homo-bulk__selected strong,
.gestion-sis-homo-bulk__materia strong {
  color: var(--ui-text);
  font-size: var(--ui-size-13);
  line-height: 1.32;
}

.gestion-sis-homo-bulk__result small,
.gestion-sis-homo-bulk__selected small,
.gestion-sis-homo-bulk__materia small {
  margin-top: 3px;
  color: var(--ui-chart-neutral);
  font-size: var(--ui-size-11);
  font-weight: var(--ui-weight-bold);
}

.gestion-sis-homo-bulk__result em,
.gestion-sis-homo-bulk__selected em {
  border-radius: var(--ui-radius-panel);
  padding: 6px 8px;
  background: color-mix(in srgb, var(--ui-accent-border) 20%, transparent);
  color: var(--ui-accent);
  font-size: var(--ui-size-11);
  font-style: normal;
  font-weight: var(--ui-weight-bold);
  white-space: nowrap;
}

.gestion-sis-homo-bulk__result--active,
.gestion-sis-homo-bulk__selected,
.gestion-sis-homo-bulk__materia--active {
  border-color: color-mix(in srgb, var(--ui-danger) 46%, transparent);
  background: var(--ui-surface);
}

.gestion-sis-homo-bulk__selected em,
.gestion-sis-homo-bulk__result--active em {
  background: color-mix(in srgb, var(--ui-danger) 12%, transparent);
  color: var(--ui-danger);
}

.gestion-sis-homo-bulk__materias {
  margin-top: 12px;
}

.gestion-sis-homo-selector-modal {
  max-width: 980px;
}

.gestion-sis-homo-selector-search {
  grid-template-columns: 1fr;
  margin-bottom: 12px;
}

.gestion-sis-homo-selector-search label,
.gestion-sis-homo-selector-search label:first-child,
.gestion-sis-homo-selector-search label:nth-child(2) {
  grid-column: auto;
}

.gestion-sis-homo-name-list {
  display: grid;
  gap: 8px;
  max-height: 56vh;
  overflow: auto;
  padding-right: 4px;
}

.gestion-sis-homo-name-option {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  min-height: 72px;
  border: 1px solid color-mix(in srgb, var(--ui-border-strong) 78%, transparent);
  border-radius: var(--ui-radius-panel);
  padding: 12px;
  background: color-mix(in srgb, var(--ui-surface) 90%, transparent);
  color: var(--ink);
  cursor: pointer;
  text-align: left;
}

.gestion-sis-homo-name-option span,
.gestion-sis-homo-name-option strong,
.gestion-sis-homo-name-option small,
.gestion-sis-homo-name-option em {
  display: block;
}

.gestion-sis-homo-name-option strong {
  font-size: var(--ui-size-14);
  line-height: 1.32;
}

.gestion-sis-homo-name-option small {
  margin-top: 4px;
  color: var(--ui-muted);
  font-size: var(--ui-size-12);
  line-height: 1.35;
}

.gestion-sis-homo-name-option em {
  border-radius: var(--ui-radius-panel);
  padding: 7px 9px;
  background: color-mix(in srgb, var(--ui-accent-border) 22%, transparent);
  color: var(--ui-accent);
  font-size: var(--ui-size-11);
  font-style: normal;
  font-weight: var(--ui-weight-bold);
  white-space: nowrap;
}

.gestion-sis-homo-name-option--active {
  border-color: color-mix(in srgb, var(--ui-danger) 50%, transparent);
  background: var(--ui-surface);
}

.gestion-sis-homo-name-option--active em {
  background: color-mix(in srgb, var(--ui-danger) 12%, transparent);
  color: var(--ui-danger);
}

.gestion-sis-homo-selector-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
