  display: grid;
  width: 34px;
  height: 34px;
  flex: 0 0 34px;
  place-items: center;
  border: 1px solid color-mix(in srgb, var(--ui-accent-border) 72%, transparent);
  border-radius: 50%;
  background: color-mix(in srgb, var(--ui-accent-border) 15%, transparent);
  color: var(--ui-accent);
  font-size: var(--ui-size-11);
}

.academic-lifecycle__name strong {
  color: var(--ink);
  font-size: var(--ui-size-14);
}

.academic-lifecycle__row > span {
  color: var(--ui-text-secondary);
  font-size: var(--ui-size-12);
  line-height: 1.35;
}

.academic-lifecycle__record {
  display: grid;
  gap: 5px;
}

.academic-lifecycle__record > b {
  color: var(--ink);
  font-size: var(--ui-size-11);
}

.integration-state {
  width: fit-content;
  font-size: var(--ui-size-11);
  font-weight: var(--ui-weight-bold);
}

.integration-state--ready {
  color: var(--ui-success);
}

.integration-state--partial,
.integration-state--checking {
  color: var(--ui-warning);
}

.integration-state--unavailable {
  color: var(--ui-danger);
}

.academic-lifecycle__row .ghost-button {
  width: 100%;
  justify-content: center;
}

.academic-system-controls {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface-alt);
}

.academic-system-controls > div {
  padding: 12px 15px;
}

.academic-system-controls > div + div {
  border-left: 1px solid var(--line);
}

.academic-system-controls strong {
  display: block;
  margin-top: 4px;
  color: var(--ink);
  font-size: var(--ui-size-12);
}

.academic-integration {
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: var(--ui-radius-panel);
  background: var(--surface);
  box-shadow: var(--ui-shadow-sm);
}

.academic-integration__header,
.academic-integration__row {
  display: grid;
  grid-template-columns: minmax(240px, 1.15fr) minmax(300px, 1.45fr) minmax(230px, 1fr) 140px;
  align-items: center;
  gap: 16px;
}

.academic-integration__header {
  padding: 10px 18px;
  border-bottom: 1px solid var(--line);
  background: var(--ui-accent-soft);
  color: var(--ui-muted);
  font-size: var(--ui-size-11);
  font-weight: var(--ui-weight-bold);
  text-transform: uppercase;
}

.academic-integration__row {
  min-height: 62px;
  padding: 10px 18px;
}

.academic-integration__row + .academic-integration__row {
  border-top: 1px solid var(--line);
}

.academic-integration__row > div {
  min-width: 0;
}

.academic-integration__row strong,
.academic-integration__row small {
  display: block;
  overflow-wrap: anywhere;
}

.academic-integration__row strong {
  color: var(--ink);
  font-size: var(--ui-size-13);
}

.academic-integration__row small,
.academic-integration__row > span {
  color: var(--ui-muted);
  font-size: var(--ui-size-11);
  line-height: 1.35;
}

.academic-integration__row small {
  margin-top: 3px;
}

.database-status {
  display: inline-flex;
  width: fit-content;
  min-width: 104px;
  justify-content: center;
  padding: 6px 9px;
  border: 1px solid transparent;
  border-radius: var(--ui-radius-control);
  font-size: var(--ui-size-11);
}

.database-status--online {
  border-color: var(--ui-success-border);
  background: var(--ui-success-soft);
  color: var(--ui-success);
}

.database-status--offline {
  border-color: var(--ui-danger-border);
  background: var(--ui-primary-soft);
  color: var(--ui-danger);
}

.database-status--partial {
  border-color: var(--ui-danger-border);
  background: var(--ui-warning-soft);
  color: var(--ui-warning);
}

.database-status--not_configured {
  border-color: var(--ui-danger-border);
  background: var(--ui-warning-soft);
  color: var(--ui-warning);
}

.academic-integration__empty {
  margin: 0;
  padding: 24px 18px;
  color: var(--ui-muted);
}

@media (max-width: 1180px) {
  .academic-system-summary {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .academic-system-summary > div + div {
    border-left: 0;
  }

  .academic-system-summary > div:nth-child(n + 4) {
    border-top: 1px solid var(--line);
  }

  .academic-lifecycle__header,
  .academic-lifecycle__row,
  .academic-integration__header,
  .academic-integration__row {
    grid-template-columns: minmax(220px, 1.1fr) minmax(150px, 0.75fr) minmax(240px, 1.2fr) 140px;
  }

  .academic-process-map__rail {
    grid-template-columns: 1fr 1fr;
  }

  .academic-process-map__rail button:nth-child(3) {
    border-left: 0;
  }

  .academic-process-map__rail button:nth-child(n + 3) {
    border-top: 1px solid var(--line);
  }
}

@media (max-width: 820px) {
  .academic-system-hero,
  .academic-lifecycle__heading,
  .academic-process-map__heading {
    align-items: stretch;
    flex-direction: column;
  }

  .academic-system-summary,
  .academic-system-controls {
    grid-template-columns: 1fr 1fr;
  }

  .academic-system-summary > div,
  .academic-system-controls > div {
    border: 0;
    border-bottom: 1px solid var(--line);
  }

  .academic-system-summary > div:nth-child(even),
  .academic-system-controls > div:nth-child(even) {
    border-left: 1px solid var(--line);
  }

  .academic-lifecycle__header,
  .academic-integration__header {
    display: none;
  }

  .academic-lifecycle__row {
    grid-template-columns: 1fr auto;
    gap: 7px 12px;
    padding: 14px;
  }

  .academic-lifecycle__name {
    grid-column: 1 / -1;
  }

  .academic-lifecycle__row > span {
    grid-column: 1;
  }

  .academic-lifecycle__row .ghost-button {
    grid-column: 2;
    grid-row: 2 / span 2;
    min-width: 130px;
  }

  .academic-integration__row {
    grid-template-columns: 1fr 150px;
    gap: 7px 12px;
    padding: 14px;
  }

  .academic-integration__row > div {
    grid-column: 1 / -1;
  }

  .academic-integration__row > span {
    grid-column: 1;
  }

  .academic-integration__row > b {
    grid-column: 2;
    grid-row: 2 / span 2;
  }
}

/* Selección específica de fechas Moodle por materia. */

.moodle-confirm-dialog.moodle-date-course-dialog {
  display: grid;
  grid-template-rows: auto auto minmax(0, 1fr) auto;
  width: min(1180px, calc(100vw - 48px));
  max-height: calc(100dvh - 48px);
  overflow: hidden;
}

.moodle-date-course-dialog .moodle-confirm-dialog__header > div {
  min-width: 0;
}

.moodle-date-course-summary {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  border-bottom: 1px solid var(--ui-border);
  background: var(--ui-surface-alt);
}

.moodle-date-course-summary > div {
  display: grid;
  min-width: 0;
  min-height: 72px;
  align-content: center;
  gap: 5px;
  padding: 11px 16px;
  border-right: 1px solid var(--ui-border);
}

.moodle-date-course-summary > div:last-child {
  border-right: 0;
}

.moodle-date-course-summary span,
.moodle-date-course-detail > header span {
  color: var(--ui-chart-neutral);
  font-size: var(--ui-size-11);
  font-weight: var(--ui-weight-bold);
  text-transform: uppercase;
}

.moodle-date-course-summary strong {
  color: var(--ui-text);
  font-size: var(--ui-size-20);
}

.moodle-date-course-workspace {
  display: grid;
  grid-template-columns: minmax(250px, 0.32fr) minmax(0, 1fr);
  min-height: 0;
  overflow: hidden;
}

.moodle-date-course-nav {
  min-height: 0;
  overflow-y: auto;
  border-right: 1px solid var(--ui-border);
  background: var(--ui-surface-alt);
}

.moodle-date-course-nav > button {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 30px;
  width: 100%;
  min-height: 64px;
  align-items: center;
  gap: 10px;
  padding: 10px 12px;
  border: 0;
  border-bottom: 1px solid var(--ui-border);
  background: transparent;
  color: var(--ui-text);
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.moodle-date-course-nav > button:hover {
  background: var(--ui-surface);
}

.moodle-date-course-nav > button.is-active {
  background: var(--ui-accent-soft);
  box-shadow: inset 4px 0 var(--ui-accent);
}

.moodle-date-course-nav span,
.moodle-date-course-nav strong,
.moodle-date-course-nav small {
  display: block;
  min-width: 0;
  overflow-wrap: anywhere;
}

.moodle-date-course-nav small {
  margin-top: 4px;
  color: var(--ui-chart-neutral);
  font-size: var(--ui-size-11);
}

.moodle-date-course-nav b {
  display: grid;
  width: 28px;
  height: 28px;
  place-items: center;
  border: 1px solid var(--ui-border-strong);
  border-radius: 50%;
  background: var(--ui-surface);
  color: var(--ui-accent);
  font-size: var(--ui-size-12);
}

.moodle-date-course-detail {
  min-width: 0;
  min-height: 0;
  overflow-y: auto;
  background: var(--ui-surface);
}

.moodle-date-course-detail > header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 18px;
  padding: 16px;
  border-bottom: 1px solid var(--ui-border);
}

.moodle-date-course-detail > header > div:first-child {
  min-width: 0;
}

.moodle-date-course-detail > header h3 {
  margin: 4px 0;
  overflow-wrap: anywhere;
  color: var(--ui-text);
  font-size: var(--ui-size-18);
}

.moodle-date-course-detail > header small {
  color: var(--ui-chart-neutral);
  overflow-wrap: anywhere;
}

.moodle-date-course-detail__actions {
  display: flex;
  flex: 0 0 auto;
  gap: 8px;
}

.moodle-date-scope-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.moodle-date-scope + .moodle-date-scope {
  border-left: 1px solid var(--ui-border);
}

.moodle-date-scope h4 {
  margin: 0;
  padding: 11px 14px;
  border-bottom: 1px solid var(--ui-border);
  background: var(--ui-accent-soft);
  color: var(--ui-text);
  font-size: var(--ui-size-14);
}

.moodle-date-scope__partials {
  display: grid;
}

.moodle-date-partial {
  border-bottom: 1px solid var(--ui-border);
  background: var(--ui-surface-alt);
}

.moodle-date-partial:last-child {
  border-bottom: 0;
}

.moodle-date-partial.has-selection {
  box-shadow: inset 4px 0 var(--ui-accent);
}

.moodle-date-partial__selector {
  display: grid;
  grid-template-columns: 20px minmax(110px, 0.35fr) minmax(0, 1fr);
  min-height: 68px;
  align-items: center;
  gap: 10px;
  padding: 10px 12px;
  background: var(--ui-surface);
  cursor: pointer;
}

.moodle-date-partial.has-selection .moodle-date-partial__selector {
  background: var(--ui-accent-soft);
}

.moodle-date-partial.is-disabled .moodle-date-partial__selector {
  background: var(--ui-surface-alt);
  color: var(--ui-disabled-text);
  cursor: not-allowed;
}

.moodle-date-scope input {
  width: 18px;
  height: 18px;
  margin: 0;
  accent-color: var(--ui-accent);
}

.moodle-date-scope span,
.moodle-date-scope strong,
.moodle-date-scope small {
  display: block;
  min-width: 0;
}

.moodle-date-scope small {
  margin-top: 3px;
  color: var(--ui-chart-neutral);
  font-size: var(--ui-size-11);
}

.moodle-date-partial__selector em,
.moodle-date-activity em {
  min-width: 0;
  overflow-wrap: anywhere;
  color: var(--ui-muted);
  font-size: var(--ui-size-11);
  font-style: normal;
  line-height: 1.4;
}

.moodle-date-activity-list {
  display: grid;
  gap: 6px;
  padding: 0 10px 10px 42px;
  background: var(--ui-surface-alt);
}

.moodle-date-activity {
  display: grid;
  grid-template-columns: 18px minmax(0, 1fr);
  align-items: start;
  gap: 7px 9px;
  min-width: 0;
  padding: 9px 10px;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-control);
  background: var(--ui-surface);
  cursor: pointer;
}

.moodle-date-activity:hover {
  border-color: var(--ui-accent-border);
}

.moodle-date-activity.is-selected {
  border-color: var(--ui-accent-border);
  background: var(--ui-accent-soft);
}

.moodle-date-activity.is-disabled {
  background: var(--ui-background);
  color: var(--ui-disabled-text);
  cursor: not-allowed;
}

.moodle-date-activity > input {
  margin-top: 2px;
}

.moodle-date-activity > span,
.moodle-date-activity > span > strong,
.moodle-date-activity > span > small {
  min-width: 0;
  overflow-wrap: anywhere;
}

.moodle-date-activity > span > strong {
  font-size: var(--ui-size-12);
  line-height: 1.35;
}

.moodle-date-activity > em {
  grid-column: 2;
}

.moodle-date-activity-list > p {
  margin: 0;
  padding: 9px 10px;
  border: 1px dashed var(--ui-border);
  border-radius: var(--ui-radius-control);
  color: var(--ui-chart-neutral);
  font-size: var(--ui-size-11);
  text-align: center;
}

.moodle-confirm-dialog__actions.moodle-date-course-dialog__actions {
  align-items: center;
  justify-content: space-between;
}

.moodle-confirm-dialog__actions.moodle-date-course-dialog__actions > span {
  color: var(--ui-muted);
  font-size: var(--ui-size-12);
  font-weight: var(--ui-weight-bold);
}

.moodle-table-action {
  min-height: 30px;
  margin-top: 6px;
  padding: 5px 9px;
  border: 1px solid var(--ui-border-strong);
  border-radius: var(--ui-radius-control);
  background: var(--ui-surface);
  color: var(--ui-accent-hover);
  font: inherit;
  font-size: var(--ui-size-11);
  font-weight: var(--ui-weight-bold);
  cursor: pointer;
}

.moodle-table-action:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

@media (max-width: 900px) {
  .moodle-confirm-dialog.moodle-date-course-dialog {
    width: min(760px, calc(100vw - 32px));
    max-height: calc(100dvh - 32px);
  }

  .moodle-date-course-workspace {
    grid-template-columns: minmax(210px, 0.4fr) minmax(0, 1fr);
  }

  .moodle-date-course-detail > header,
  .moodle-date-course-detail__actions {
    align-items: stretch;
    flex-direction: column;
  }

  .moodle-date-scope-grid {
    grid-template-columns: 1fr;
  }

  .moodle-date-scope + .moodle-date-scope {
    border-top: 1px solid var(--ui-border);
    border-left: 0;
  }

  .moodle-date-partial__selector {
    grid-template-columns: 20px minmax(100px, 0.4fr) minmax(0, 1fr);
  }
}

@media (max-width: 650px) {
  .moodle-confirm-overlay.moodle-date-course-overlay {
    padding: 0;
  }

  .moodle-confirm-dialog.moodle-date-course-dialog {
    width: 100vw;
    max-height: 100dvh;
    height: 100dvh;
    border: 0;
    border-radius: 0;
  }

  .moodle-date-course-dialog .moodle-confirm-dialog__header {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    align-items: start;
    gap: 8px;
    padding: 14px 12px;
  }

  .moodle-date-course-dialog .moodle-confirm-dialog__header h2 {
    overflow-wrap: anywhere;
    font-size: var(--ui-size-18);
    line-height: 1.25;
  }

  .moodle-date-course-dialog .moodle-confirm-dialog__header .moodle-button {
    min-height: 38px;
    padding: 8px 10px;
  }

  .moodle-date-course-summary {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .moodle-date-course-summary > div {
    min-height: 62px;
    padding: 8px;
  }

  .moodle-date-course-summary span {
    overflow-wrap: anywhere;
    font-size: var(--ui-size-11);
  }

  .moodle-date-course-summary strong {
    font-size: var(--ui-size-16);
  }

  .moodle-date-course-workspace {
    grid-template-columns: 1fr;
    grid-template-rows: auto minmax(0, 1fr);
  }

  .moodle-date-course-nav {
    display: flex;
    max-height: 104px;
    overflow-x: auto;
    overflow-y: hidden;
    border-right: 0;
    border-bottom: 1px solid var(--ui-border);
  }

  .moodle-date-course-nav > button {
    flex: 0 0 220px;
    border-right: 1px solid var(--ui-border);
    border-bottom: 0;
  }

  .moodle-date-partial__selector {
    grid-template-columns: 20px minmax(0, 1fr);
  }

  .moodle-date-partial__selector em {
    grid-column: 2;
  }

  .moodle-date-activity-list {
    padding: 0 8px 9px 30px;
  }

  .moodle-confirm-dialog__actions.moodle-date-course-dialog__actions {
    align-items: stretch;
    flex-direction: column;
  }

  .moodle-confirm-dialog__actions.moodle-date-course-dialog__actions .moodle-button {
    width: 100%;
  }
}

@media (max-width: 560px) {
  .academic-system-summary,
  .academic-system-controls {
    grid-template-columns: 1fr;
  }

  .academic-process-map__rail {
    grid-template-columns: 1fr;
  }

  .academic-process-map__rail button + button,
  .academic-process-map__rail button:nth-child(3) {
    border-left: 0;
    border-top: 1px solid var(--line);
  }

  .academic-system-summary > div:nth-child(even),
  .academic-system-controls > div:nth-child(even) {
    border-left: 0;
  }

  .academic-lifecycle__row {
    grid-template-columns: 1fr;
  }

  .academic-lifecycle__row .ghost-button {
    grid-column: 1;
    grid-row: auto;
  }

  .academic-integration__row {
    grid-template-columns: 1fr;
  }

  .academic-integration__row > b {
    grid-column: 1;
    grid-row: auto;
  }
}

.preinscripcion-journey {
  margin-bottom: 14px;
  overflow: hidden;
  border: 1px solid color-mix(in srgb, var(--ui-accent-border) 62%, transparent);
  border-radius: var(--ui-radius-panel);
  background: var(--surface);
  box-shadow: var(--ui-shadow-sm);
}

.preinscripcion-journey__heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding: 15px 18px;
  border-bottom: 1px solid var(--line);
  background: var(--ui-surface);
}

.preinscripcion-journey__heading > div:first-child {
  min-width: 0;
}

.preinscripcion-journey__heading span,
.preinscripcion-journey__heading small {
  color: var(--ui-chart-neutral);
  font-size: var(--ui-size-11);
  font-weight: var(--ui-weight-bold);
  text-transform: uppercase;
}

.preinscripcion-journey__heading h2 {
  margin: 3px 0;
  color: var(--ink);
  font-size: var(--ui-size-20);
  overflow-wrap: anywhere;
}

.preinscripcion-journey__progress {
  display: grid;
  width: min(280px, 34vw);
  flex: 0 0 auto;
  grid-template-columns: auto 1fr;
  align-items: baseline;
  gap: 2px 10px;
}

.preinscripcion-journey__progress strong {
  color: var(--ui-primary);
  font-size: var(--ui-size-20);
}

.preinscripcion-journey__progress > span {
  text-align: right;
}

.preinscripcion-journey__progress > div {
  height: 7px;
  grid-column: 1 / -1;
  overflow: hidden;
  border-radius: var(--ui-radius-panel);
  background: var(--ui-neutral-soft);
}

.preinscripcion-journey__progress i {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: var(--ui-accent);
  transition: width 180ms ease;
}

.preinscripcion-journey__steps {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  padding: 0 10px;
  background: var(--ui-surface);
}

.preinscripcion-journey__step {
  display: flex;
  min-width: 0;
  min-height: 72px;
  align-items: center;
  gap: 10px;
  padding: 12px 10px;
  border: 0;
  border-bottom: 3px solid transparent;
  border-radius: 0;
  background: transparent;
  color: var(--ink);
  text-align: left;
  cursor: pointer;
}

.preinscripcion-journey__step + .preinscripcion-journey__step {
  border-left: 1px solid var(--line);
}

.preinscripcion-journey__step:hover:not(:disabled),
.preinscripcion-journey__step.is-active {
  background: color-mix(in srgb, var(--ui-accent-border) 12%, transparent);
  border-bottom-color: var(--ui-primary);
}

.preinscripcion-journey__step:disabled {
  color: var(--ui-border-strong);
  cursor: not-allowed;
