.cruce-source-stack {
  display: grid;
  gap: 3px;
}

.cruce-source-stack strong,
.cruce-source-stack span {
  color: var(--ui-text);
  overflow-wrap: anywhere;
}

.cruce-source-stack small {
  color: var(--ui-chart-neutral);
  overflow-wrap: anywhere;
}

.cruce-source-stack--compact {
  max-width: 180px;
}

.cruce-status {
  display: inline-flex;
  align-items: center;
  border-radius: var(--ui-radius-panel);
  padding: 5px 9px;
  font-size: var(--ui-size-12);
  font-weight: var(--ui-weight-bold);
  color: var(--ui-text);
  background: color-mix(in srgb, var(--ui-border-strong) 35%, transparent);
  white-space: nowrap;
}

.cruce-status--en-todos {
  color: var(--ui-success);
  background: color-mix(in srgb, var(--ui-success) 15%, transparent);
}

.cruce-status--balance-moodle,
.cruce-status--balance-tablas,
.cruce-status--moodle-tablas {
  color: var(--ui-warning);
  background: color-mix(in srgb, var(--ui-chart-gold) 22%, transparent);
}

.cruce-status--solo-balance,
.cruce-status--solo-moodle,
.cruce-status--solo-tablas {
  color: var(--ui-primary);
  background: color-mix(in srgb, var(--ui-danger) 14%, transparent);
}

.cruce-status--matriculado,
.cruce-status--a,
.cruce-status--encontrado {
  color: var(--ui-success);
  background: color-mix(in srgb, var(--ui-success) 15%, transparent);
}

.cruce-status--p,
.cruce-status--r,
.cruce-status--no-encontrado {
  color: var(--ui-primary);
  background: color-mix(in srgb, var(--ui-danger) 14%, transparent);
}

.cruce-status--g,
.cruce-status--d,
.cruce-status--parcial {
  color: var(--ui-warning);
  background: color-mix(in srgb, var(--ui-chart-gold) 22%, transparent);
}

.cruce-status--sin-matricula,
.cruce-status--sin-identificador {
  color: var(--ui-muted);
  background: color-mix(in srgb, var(--ui-border-strong) 35%, transparent);
}

.periodo-inline-summary {
  margin-top: 12px;
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.periodo-filter-pill {
  border: 1px solid color-mix(in srgb, var(--ui-border-strong) 80%, transparent);
  border-radius: var(--ui-radius-panel);
  padding: 7px 10px;
  color: var(--ui-text);
  background: color-mix(in srgb, var(--ui-accent-border) 14%, transparent);
  font-size: var(--ui-size-12);
  font-weight: var(--ui-weight-bold);
  cursor: pointer;
}

.periodo-filter-pill--active {
  border-color: var(--rojo);
  color: var(--rojo);
  box-shadow: var(--ui-shadow-sm);
}

.logout-button {
  border: none;
  border-radius: var(--ui-radius-panel);
  background: var(--rojo);
  color: var(--blanco);
  padding: 10px 14px;
  font-weight: var(--ui-weight-medium);
  cursor: pointer;
}

@keyframes drift {
  0% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-8px);
  }
  100% {
    transform: translateY(0);
  }
}

@keyframes shoot {
  0% {
    opacity: 0;
    transform: translateX(0) rotate(-35deg);
  }
  18% {
    opacity: 1;
  }
  50% {
    opacity: 0;
    transform: translateX(220px) rotate(-35deg);
  }
  100% {
    opacity: 0;
  }
}

