.carnet-page {
  gap: 16px;
}

.carnet-hero {
  align-items: center;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 16px;
}

.carnet-hero p {
  margin: 8px 0 0;
  color: var(--ui-text-secondary);
  max-width: 780px;
}

.carnet-hero__user {
  border: 1px solid color-mix(in srgb, var(--ui-accent-border) 58%, transparent);
  border-radius: var(--ui-radius-panel);
  padding: 12px 16px;
  min-width: 190px;
  background: var(--ui-surface);
}

.carnet-hero__user span,
.carnet-hero__user strong {
  display: block;
}

.carnet-hero__user span {
  color: var(--ui-muted);
  font-size: var(--ui-size-13);
}

.carnet-hero__user strong {
  color: var(--ui-text);
  margin-top: 4px;
}

.success-message,
.error-message {
  border-radius: var(--ui-radius-panel);
  padding: 12px 14px;
  font-weight: var(--ui-weight-bold);
}

.success-message {
  background: var(--ui-success-soft);
  border: 1px solid var(--ui-border);
  color: var(--ui-success);
}

.error-message {
  background: var(--ui-primary-soft);
  border: 1px solid var(--ui-danger-border);
  color: var(--ui-primary);
}

.carnet-grid {
  display: grid;
  grid-template-columns: minmax(360px, 0.8fr) minmax(0, 1.4fr);
  gap: 16px;
  align-items: start;
}

.carnet-grid:has(.carnet-panel:only-child) {
  grid-template-columns: minmax(0, 760px);
}

.section-title--inline {
  align-items: center;
  display: flex;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 14px;
}

.section-title--inline h2,
.section-title--inline h3 {
  margin: 4px 0 0;
}

.carnet-panel {
  overflow: hidden;
}

.carnet-card-preview {
  position: relative;
  isolation: isolate;
  width: min(100%, 540px);
  aspect-ratio: 1.72 / 1;
  margin: 0 auto 16px;
  display: grid;
  grid-template-columns: 30% minmax(0, 1fr) 28%;
  grid-template-rows: 30% minmax(0, 1fr);
  gap: 0;
  align-items: center;
  overflow: hidden;
  border: 1px solid color-mix(in srgb, var(--ui-accent-border) 90%, transparent);
  border-radius: var(--ui-radius-control);
  background: var(--ui-accent-soft);
  box-shadow: var(--ui-shadow-sm);
}

.carnet-card-preview::before,
.carnet-card-preview::after {
  content: '';
  position: absolute;
  inset-inline: -8%;
  z-index: -1;
  height: 36%;
  background:
    var(--ui-surface);
  border-radius: 50%;
}

.carnet-card-preview::before {
  top: -12%;
  transform: rotate(-4deg);
}

.carnet-card-preview::after {
  bottom: -12%;
  transform: rotate(5deg);
}

.carnet-card-preview__brand {
  grid-column: 1 / 3;
  grid-row: 1;
  align-self: start;
  padding: 14px 18px 0;
}

.carnet-card-preview__brand img {
  display: block;
  width: min(210px, 58%);
  height: auto;
  margin: 0 auto;
}

.carnet-card-preview__qr {
  grid-column: 1;
  grid-row: 2;
  width: min(128px, 78%);
  aspect-ratio: 1;
  margin-left: 12px;
  align-self: end;
  display: grid;
  grid-template-columns: repeat(9, 1fr);
  gap: 1px;
  padding: 5px;
  background: var(--ui-surface);
}

.carnet-card-preview__qr span {
  background: transparent;
}

.carnet-card-preview__qr span.is-dark {
  background: var(--ui-text);
}

.carnet-card-preview__info {
  grid-column: 2;
  grid-row: 2;
  align-self: center;
  display: grid;
  gap: 5px;
  justify-items: center;
  text-align: center;
  color: var(--ui-text-secondary);
  font-size: var(--ui-size-16);
  line-height: 1.1;
}

.carnet-card-preview__info strong {
  max-width: 100%;
  color: var(--ui-text);
  font-size: var(--ui-size-16);
  line-height: 1.12;
  overflow-wrap: anywhere;
}

.carnet-card-preview__photo {
  grid-column: 3;
  grid-row: 1 / 3;
  width: min(150px, 78%);
  aspect-ratio: 0.78;
  justify-self: center;
  align-self: center;
  display: grid;
  place-items: center;
  overflow: hidden;
  border: 4px solid var(--ui-accent-border);
  background: var(--ui-surface-alt);
  color: var(--ui-chart-neutral);
  font-weight: var(--ui-weight-bold);
}

.carnet-card-preview__photo img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
}

.carnet-photo-block {
  display: grid;
  grid-template-columns: 148px minmax(0, 1fr);
  gap: 14px;
  align-items: stretch;
  margin-bottom: 14px;
}

.carnet-photo-preview {
  align-items: center;
  background: var(--ui-surface);
  border: 1px solid color-mix(in srgb, var(--ui-accent-border) 58%, transparent);
  border-radius: var(--ui-radius-panel);
  display: flex;
  justify-content: center;
  min-height: 170px;
  overflow: hidden;
}

.carnet-photo-preview img {
  display: block;
  height: 100%;
  max-height: 220px;
  object-fit: cover;
  width: 100%;
}

.carnet-photo-preview span {
  color: var(--ui-muted);
  font-weight: var(--ui-weight-bold);
}

.carnet-photo-copy {
  border: 1px solid color-mix(in srgb, var(--ui-border-strong) 72%, transparent);
  border-radius: var(--ui-radius-panel);
  padding: 14px;
  min-width: 0;
}

.carnet-photo-copy strong,
.carnet-photo-copy p,
.carnet-photo-copy small {
  display: block;
}

.carnet-photo-copy strong {
  margin-top: 10px;
  color: var(--ui-text);
  overflow-wrap: anywhere;
}

.carnet-photo-copy p {
  margin: 8px 0;
  color: var(--ui-text-secondary);
}

.carnet-photo-copy small {
  color: var(--ui-chart-neutral);
}

.carnet-meta-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
  margin-bottom: 14px;
}

.carnet-meta-grid--compact {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.carnet-info-tile {
  border: 1px solid color-mix(in srgb, var(--ui-border-strong) 72%, transparent);
  border-radius: var(--ui-radius-panel);
  padding: 10px 12px;
  background: var(--ui-surface);
  min-width: 0;
}

.carnet-info-tile span,
.carnet-info-tile strong {
  display: block;
}

.carnet-info-tile span {
  color: var(--ui-chart-neutral);
  font-size: var(--ui-size-12);
  font-weight: var(--ui-weight-bold);
  text-transform: uppercase;
}

.carnet-info-tile strong {
  color: var(--ui-text);
  margin-top: 6px;
  overflow-wrap: anywhere;
}

.file-input-card {
  background: var(--ui-surface);
  border: 1px dashed var(--ui-accent-border);
  border-radius: var(--ui-radius-panel);
  cursor: pointer;
  display: grid;
  gap: 4px;
  padding: 14px;
}

.file-input-card span {
  color: var(--ui-text);
  font-weight: var(--ui-weight-bold);
}

.file-input-card small {
  color: var(--ui-muted);
}

.file-input-card input,
.file-trigger input {
  display: none;
}

.file-input-card--disabled,
.file-trigger.is-disabled {
  cursor: not-allowed;
  opacity: 0.58;
}

.carnet-search {
  display: grid;
  grid-template-columns: minmax(280px, 1fr) 180px auto;
  gap: 10px;
  margin-bottom: 14px;
}

.carnet-search label {
  color: var(--ui-text-secondary);
  font-size: var(--ui-size-13);
  font-weight: var(--ui-weight-bold);
}

.carnet-search input,
.carnet-search select {
  border: 1px solid color-mix(in srgb, var(--ui-border-strong) 92%, transparent);
  border-radius: var(--ui-radius-panel);
  display: block;
  font: inherit;
  margin-top: 6px;
  min-height: 48px;
  padding: 0 12px;
  width: 100%;
}

.carnet-search button {
  align-self: end;
  min-height: 48px;
}

.carnet-manager-summary {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
  margin: 0 0 14px;
}

.carnet-manager-summary .carnet-info-tile {
  background: var(--ui-surface);
}

.carnet-workspace {
  display: grid;
  grid-template-columns: 320px minmax(0, 1fr);
  gap: 14px;
  min-height: 420px;
}

.carnet-results {
  border: 1px solid color-mix(in srgb, var(--ui-accent-border) 48%, transparent);
  border-radius: var(--ui-radius-panel);
  display: grid;
  gap: 8px;
  max-height: 560px;
  overflow: auto;
  padding: 10px;
}

.carnet-person-card {
  background: var(--ui-surface);
  border: 1px solid color-mix(in srgb, var(--ui-border-strong) 80%, transparent);
  border-radius: var(--ui-radius-panel);
  color: var(--ui-text);
  cursor: pointer;
  display: grid;
  gap: 5px;
  padding: 12px;
  text-align: left;
}

.carnet-person-card:hover,
.carnet-person-card:focus-visible {
  background: var(--ui-info-soft);
  border-color: var(--ui-accent-border);
  color: var(--ui-text);
}

.carnet-person-card--active {
  border-color: var(--ui-primary);
  box-shadow: inset 4px 0 0 var(--ui-primary);
}

.carnet-person-card strong,
.carnet-person-card small,
.carnet-person-card em {
  overflow-wrap: anywhere;
}

.carnet-person-card em {
  color: var(--ui-muted);
  font-style: normal;
}

.carnet-selected {
  border: 1px solid color-mix(in srgb, var(--ui-border-strong) 80%, transparent);
  border-radius: var(--ui-radius-panel);
  padding: 14px;
  min-width: 0;
}

.carnet-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.carnet-actions--stacked {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: stretch;
}

.carnet-actions .ghost-button,
.carnet-actions .primary-action,
.carnet-actions .danger-action {
  min-height: 46px;
}

.carnet-actions .ghost-button:disabled,
.carnet-actions .primary-action:disabled,
.carnet-actions .danger-action:disabled {
  cursor: not-allowed;
  opacity: 0.58;
}

.carnet-validity-note {
  background: var(--ui-surface);
  border: 1px solid color-mix(in srgb, var(--ui-accent-border) 58%, transparent);
  border-radius: var(--ui-radius-panel);
  color: var(--ui-text);
  font-weight: var(--ui-weight-bold);
  margin: 0 0 14px;
  padding: 12px 14px;
}

.empty-state {
  align-self: center;
