/* Evaluacion docente unified public flow */

.teacher-evaluation {
  min-height: 100vh;
  padding: clamp(16px, 3vw, 36px);
  color: var(--ui-text);
  background: var(--ui-surface);
}

.teacher-evaluation__hero,
.teacher-evaluation__panel,
.teacher-evaluation__profile-card,
.teacher-evaluation__mode-card,
.teacher-evaluation__course-card,
.teacher-evaluation__modal {
  background: var(--ui-surface);
  border: 1px solid color-mix(in srgb, var(--ui-accent-border) 58%, transparent);
  border-radius: var(--ui-radius-panel);
  box-shadow: var(--ui-shadow-dialog);
}

.teacher-evaluation__hero {
  display: flex;
  justify-content: space-between;
  gap: 20px;
  align-items: flex-start;
  padding: clamp(20px, 3vw, 32px);
  max-width: 1480px;
  margin: 0 auto 18px;
}

.teacher-evaluation__hero h1 {
  margin: 10px 0 12px;
  font-size: var(--ui-size-40);
  line-height: 1;
}

.teacher-evaluation__hero p {
  margin: 0;
  color: var(--ui-accent-hover);
}

.teacher-evaluation__hero-actions {
  min-width: 170px;
}

.teacher-evaluation__eyebrow {
  margin: 0 0 8px;
  letter-spacing: 0;
  text-transform: uppercase;
  color: var(--ui-chart-neutral);
  font-size: var(--ui-size-12);
  font-weight: var(--ui-weight-bold);
}

.teacher-evaluation__panel {
  max-width: 1480px;
  margin: 18px auto 0;
  padding: clamp(16px, 2vw, 22px);
  box-shadow: var(--ui-shadow-sm);
}

.teacher-evaluation__label {
  display: block;
  margin-bottom: 8px;
  font-weight: var(--ui-weight-bold);
}

.teacher-evaluation__lookup-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 12px;
  align-items: end;
}

.teacher-evaluation input,
.teacher-evaluation select,
.teacher-evaluation textarea {
  width: 100%;
  border: 1px solid var(--ui-border-strong);
  border-radius: var(--ui-radius-panel);
  padding: 12px 14px;
  color: var(--ui-text);
  background: var(--ui-surface);
  font: inherit;
}

.teacher-evaluation__primary,
.teacher-evaluation__secondary,
.teacher-evaluation__ghost {
  border-radius: var(--ui-radius-panel);
  padding: 12px 18px;
  font-weight: var(--ui-weight-bold);
  cursor: pointer;
}

.teacher-evaluation__primary {
  border: 0;
  color: var(--ui-on-primary);
  background: var(--ui-primary);
}

.teacher-evaluation__secondary,
.teacher-evaluation__ghost {
  color: var(--ui-text);
  background: var(--ui-info-soft);
  border: 1px solid var(--ui-accent-border);
}

.teacher-evaluation__ghost {
  background: var(--ui-surface);
  border-color: var(--ui-border-strong);
}

.teacher-evaluation__primary:disabled,
.teacher-evaluation__secondary:disabled,
.teacher-evaluation__ghost:disabled,
.teacher-evaluation__mode-card:disabled,
.teacher-evaluation__course-card:disabled {
  opacity: 0.62;
  cursor: not-allowed;
}

.teacher-evaluation__message {
  margin-top: 12px;
  padding: 11px 13px;
  border-radius: var(--ui-radius-panel);
  font-weight: var(--ui-weight-bold);
}

.teacher-evaluation__message--error {
  color: var(--ui-primary);
  background: var(--ui-primary-soft);
}

.teacher-evaluation__message--success {
  color: var(--ui-success);
  background: var(--ui-success-soft);
}

.teacher-evaluation__profile-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 12px;
}

.teacher-evaluation__profile-card {
  padding: 14px;
  box-shadow: none;
}

.teacher-evaluation__profile-card span {
  display: block;
  margin-bottom: 6px;
  color: var(--ui-muted);
}

.teacher-evaluation__profile-card strong {
  display: block;
  overflow-wrap: anywhere;
}

.teacher-evaluation__role-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 14px;
  margin-top: 18px;
}

.teacher-evaluation__mode-card,
.teacher-evaluation__course-card {
  text-align: left;
}

.teacher-evaluation__mode-card {
  padding: 18px;
  cursor: pointer;
}

.teacher-evaluation__mode-card.is-active {
  border-color: var(--ui-primary);
  box-shadow: var(--ui-shadow-sm);
}

.teacher-evaluation__mode-card span {
  color: var(--ui-muted);
  font-weight: var(--ui-weight-bold);
}

.teacher-evaluation__mode-card h3,
.teacher-evaluation__course-card h3 {
  margin: 0 0 8px;
}

.teacher-evaluation__course-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 14px;
}

.teacher-evaluation__course-header h2 {
  margin: 0 0 6px;
}

.teacher-evaluation__course-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 14px;
}

.teacher-evaluation__course-card {
  min-height: 100%;
  display: grid;
  grid-template-rows: auto auto auto 1fr auto;
  align-content: start;
  padding: 18px;
  cursor: pointer;
}

.teacher-evaluation__course-card strong {
  display: block;
  margin-top: 8px;
}

.teacher-evaluation__course-card.is-done {
  opacity: 0.72;
}

.teacher-evaluation__badge {
  display: inline-flex;
  padding: 6px 10px;
  border-radius: var(--ui-radius-panel);
  color: var(--ui-primary);
  background: var(--ui-primary-soft);
  font-size: var(--ui-size-12);
  font-weight: var(--ui-weight-bold);
}

.teacher-evaluation__badge.is-done {
  color: var(--ui-success);
  background: var(--ui-neutral-soft);
}

.teacher-evaluation__course-card-actions {
  display: grid;
  justify-items: start;
  gap: 12px;
  align-self: end;
  margin-top: auto;
  padding-top: 18px;
}

.teacher-evaluation__empty {
  padding: 18px;
  border: 1px dashed var(--ui-accent-border);
  border-radius: var(--ui-radius-panel);
  color: var(--ui-muted);
  font-weight: var(--ui-weight-bold);
  text-align: center;
}

.teacher-evaluation__modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 1000;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 18px;
  background: color-mix(in srgb, var(--ui-text) 50%, transparent);
}

.teacher-evaluation__modal {
  width: min(980px, 100%);
  max-height: 92vh;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.teacher-evaluation__modal-header {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  padding: 18px 22px;
  border-bottom: 1px solid var(--ui-background);
}

.teacher-evaluation__modal-header h2 {
  margin: 0 0 6px;
}

.teacher-evaluation__modal-body {
  padding: 18px 22px;
  overflow: auto;
}

.teacher-evaluation__scale {
  display: grid;
  grid-template-columns: minmax(180px, 0.7fr) minmax(0, 1.3fr);
  gap: 14px;
  align-items: center;
  margin-bottom: 14px;
  padding: 14px;
  border: 1px solid color-mix(in srgb, var(--ui-accent-border) 55%, transparent);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface-alt);
}

.teacher-evaluation__scale-label {
  margin: 0 0 4px;
  color: var(--ui-chart-neutral);
  font-size: var(--ui-size-12);
  font-weight: var(--ui-weight-bold);
  letter-spacing: 0;
  text-transform: uppercase;
}

.teacher-evaluation__scale strong {
  display: block;
  color: var(--ui-text);
  font-size: var(--ui-size-14);
}

.teacher-evaluation__scale-options {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(116px, 1fr));
  gap: 8px;
}

.teacher-evaluation__scale-options span {
  display: block;
  padding: 8px 10px;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface);
  color: var(--ui-text);
  font-size: var(--ui-size-13);
  font-weight: var(--ui-weight-bold);
  text-align: center;
}

.teacher-evaluation__question-section {
  margin-bottom: 14px;
  padding: 14px;
  border: 1px solid color-mix(in srgb, var(--ui-accent-border) 45%, transparent);
  border-radius: var(--ui-radius-panel);
}

.teacher-evaluation__question-section h3 {
  margin: 0 0 10px;
}

.teacher-evaluation__question-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(210px, 240px);
  gap: 14px;
  align-items: center;
  padding: 12px 0;
  border-top: 1px solid var(--ui-background);
}

.teacher-evaluation__question-row:first-of-type {
  border-top: 0;
}

.teacher-evaluation__question-row p {
  margin: 0;
}

.teacher-evaluation__question-row select {
  width: 100%;
}

.teacher-evaluation__modal-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  padding: 16px 22px;
  border-top: 1px solid var(--ui-background);
}

@media (max-width: 760px) {
  .teacher-evaluation__hero,
  .teacher-evaluation__modal-header,
  .teacher-evaluation__course-header {
    display: block;
  }

  .teacher-evaluation__lookup-row,
  .teacher-evaluation__scale,
  .teacher-evaluation__question-row {
    grid-template-columns: 1fr;
  }

  .teacher-evaluation__modal-actions {
    display: grid;
    grid-template-columns: 1fr;
  }

  .teacher-evaluation__primary,
  .teacher-evaluation__secondary,
  .teacher-evaluation__ghost {
    width: 100%;
  }
}

