}

.fecha-grado-verification-col-date {
  width: 12%;
}

.fecha-grado-verification-col-code {
  width: 12%;
}

.fecha-grado-verification-col-roster {
  width: 10%;
}

.fecha-grado-col-name {
  width: 34%;
}

.fecha-grado-col-id {
  width: 15%;
}

.fecha-grado-col-career {
  width: 32%;
}

.fecha-grado-col-date {
  width: 19%;
}

.fecha-grado-table th,
.fecha-grado-table td {
