@media (max-width: 720px) {
  .fecha-grado-stats {
    grid-template-columns: 1fr 1fr;
  }

  .fecha-grado-form {
    grid-template-columns: 1fr;
  }

  .fecha-grado-actions {
    align-items: stretch;
    flex-direction: column;
    white-space: normal;
  }

  .fecha-grado-actions button {
    width: 100%;
  }

  .fecha-grado-student-cell--action {
    grid-template-columns: 1fr;
  }

  .fecha-grado-row-action {
    width: 100%;
  }

  .fecha-grado-modal-backdrop {
    padding: 10px;
  }

  .fecha-grado-modal__header,
  .fecha-grado-modal__actions {
    display: grid;
    grid-template-columns: 1fr;
  }

  .fecha-grado-modal__actions .ghost-button,
  .fecha-grado-modal__actions .primary-action {
    width: 100%;
  }

  .fecha-grado-import-row,
  .fecha-grado-import-only,
  .fecha-grado-verification-bar {
    grid-template-columns: 1fr;
  }

  .fecha-grado-source-tabs {
    display: grid;
    grid-template-columns: 1fr 1fr;
    width: 100%;
    box-sizing: border-box;
  }

  .fecha-grado-source-tabs button {
    min-width: 0;
    padding-inline: 8px;
  }

  .fecha-grado-analysis__head {
    align-items: stretch;
    flex-direction: column;
  }

  .fecha-grado-modal__body {
    grid-template-columns: 1fr;
  }

  .fecha-grado-modal__field--wide {
    grid-column: auto;
  }

  .senescyt-preview-launcher .card-head,
  .senescyt-modal__header {
    align-items: stretch;
    flex-direction: column;
  }

  .senescyt-preview-launcher__actions {
