  }

  .senescyt-modal__body {
    padding: 12px;
  }

  .senescyt-detail-grid {
    grid-template-columns: 1fr;
  }
}

/* Final button and titulacion modal overrides. Keep this block last. */

.app button,
.app .primary-action,
.app .secondary-action,
.app .ghost-button,
.app .danger-action {
  border-radius: var(--ui-radius-panel);
  letter-spacing: 0;
  transition:
    background-color 160ms ease,
    border-color 160ms ease,
    box-shadow 160ms ease,
    color 160ms ease,
    transform 160ms ease;
}

.app .primary-action,
.app .secondary-action,
.app .ghost-button,
.app .danger-action,
.app button:not(.student-nav__group-button):not(.student-mobile-menu-button):not(.titulacion-sort-button):not(.titulacion-progress-meter--button) {
  min-height: 38px;
  border: 1px solid color-mix(in srgb, var(--ui-text) 18%, transparent);
  padding: 8px 14px;
  font-weight: var(--ui-weight-bold);
  line-height: 1.15;
}

.app .primary-action {
  border-color: color-mix(in srgb, var(--ui-primary) 72%, transparent);
  background: var(--ui-primary);
  color: var(--ui-on-primary);
  box-shadow: var(--ui-shadow-sm);
}

.app .secondary-action,
.app .ghost-button {
  border-color: color-mix(in srgb, var(--ui-accent) 42%, transparent);
  background: var(--ui-surface-alt);
  color: var(--ink);
  box-shadow: var(--ui-shadow-sm);
}

.app .primary-action:hover,
.app .primary-action:focus-visible {
  border-color: color-mix(in srgb, var(--ui-primary) 90%, transparent);
  background: var(--ui-primary);
  color: var(--ui-on-primary);
  box-shadow: var(--ui-shadow-sm);
  transform: translateY(-1px);
}

.app .secondary-action:hover,
.app .secondary-action:focus-visible,
.app .ghost-button:hover,
.app .ghost-button:focus-visible {
  border-color: color-mix(in srgb, var(--ui-accent) 68%, transparent);
  background: var(--ui-accent-soft);
  color: var(--ink);
  box-shadow: var(--ui-shadow-sm);
  transform: translateY(-1px);
}

.app button:focus-visible,
.app .primary-action:focus-visible,
.app .secondary-action:focus-visible,
.app .ghost-button:focus-visible,
.app .danger-action:focus-visible {
  outline: 3px solid color-mix(in srgb, var(--ui-accent-border) 28%, transparent);
  outline-offset: 2px;
}

.app button:disabled,
.app .primary-action:disabled,
.app .secondary-action:disabled,
.app .ghost-button:disabled,
.app .danger-action:disabled {
  border-color: color-mix(in srgb, var(--ui-border-strong) 38%, transparent);
  background: var(--ui-neutral-soft);
  color: var(--ui-border-strong);
  box-shadow: none;
  cursor: not-allowed;
  transform: none;
}

