.scholarship-contract-template-modal {
  width: min(1120px, calc(100vw - 32px));
  max-height: min(900px, calc(100vh - 32px));
  overflow-y: auto;
  overscroll-behavior: contain;
}

.scholarship-contract-template-modal__intro {
  margin: 0;
  padding: 11px 14px;
  border-left: 3px solid var(--ui-accent);
  background: var(--ui-accent-soft);
  color: var(--ui-text-secondary);
  line-height: 1.45;
}

.scholarship-contract-template-modal__tabs {
  margin-top: 12px;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  overflow: hidden;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface);
}

.scholarship-contract-template-modal__tabs button {
  min-width: 0;
  min-height: 44px;
  padding: 9px 14px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  border: 0;
  border-right: 1px solid var(--ui-border);
  border-bottom: 3px solid transparent;
  background: var(--ui-surface);
  color: var(--ui-accent-hover);
  font: inherit;
  font-weight: var(--ui-weight-bold);
  cursor: pointer;
}

.scholarship-contract-template-modal__tabs button:last-child {
  border-right: 0;
}

.scholarship-contract-template-modal__tabs button:hover,
.scholarship-contract-template-modal__tabs button:focus-visible {
  background: var(--ui-surface-alt);
  outline: none;
}

.scholarship-contract-template-modal__tabs button.is-active {
  border-bottom-color: var(--ui-accent);
  background: var(--ui-accent-soft);
  color: var(--ui-accent);
}

.scholarship-contract-template-modal__tabs button span {
  min-width: 24px;
  height: 24px;
  padding: 0 6px;
  display: inline-grid;
  place-items: center;
  border-radius: var(--ui-radius-panel);
  background: var(--ui-neutral-soft);
  color: var(--ui-accent-hover);
  font-size: var(--ui-size-11);
  line-height: 1;
}

.scholarship-contract-template-modal__tabs button.is-active span {
  background: var(--ui-accent);
  color: var(--ui-on-primary);
}

.scholarship-contract-template-modal [role='tabpanel'][hidden] {
  display: none;
}

.scholarship-contract-template-modal__status {
  margin: 12px 0 0;
  padding: 10px 14px;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface-alt);
  color: var(--ui-accent);
  font-weight: var(--ui-weight-bold);
}

.scholarship-contract-template-modal__section {
  margin-top: 16px;
  padding-top: 16px;
  border-top: 1px solid var(--ui-border);
}

.scholarship-contract-template-modal__section h4 {
  margin: 0 0 12px;
  color: var(--ui-text);
  font-size: var(--ui-size-16);
}

.scholarship-contract-template-modal__fixed-title {
  margin-bottom: 12px;
  padding: 11px 14px;
  display: grid;
  gap: 4px;
  border: 1px solid var(--ui-border);
  border-left: 3px solid var(--ui-danger);
  border-radius: var(--ui-radius-control);
  background: var(--ui-surface-alt);
}

.scholarship-contract-template-modal__fixed-title span {
  color: var(--ui-muted);
  font-size: var(--ui-size-11);
  font-weight: var(--ui-weight-bold);
  text-transform: uppercase;
}

.scholarship-contract-template-modal__fixed-title strong {
  color: var(--ui-text);
  font-size: var(--ui-size-16);
}

.scholarship-contract-template-modal__opening {
  padding: 16px;
  border: 1px solid var(--ui-border);
  border-top: 3px solid var(--ui-accent);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface-alt);
}

.scholarship-contract-template-modal__grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
}

.scholarship-contract-template-modal__grid label,
.scholarship-contract-template-modal__projection label {
  min-width: 0;
  display: grid;
  gap: 6px;
  align-content: start;
}

.scholarship-contract-template-modal__grid label.is-wide {
  grid-column: span 2;
}

.scholarship-contract-template-modal__grid label > span,
.scholarship-contract-template-modal__projection label > span {
  color: var(--ui-muted);
  font-size: var(--ui-size-11);
  font-weight: var(--ui-weight-bold);
  text-transform: uppercase;
}

.scholarship-contract-template-modal__grid input,
.scholarship-contract-template-modal__grid textarea,
.scholarship-contract-template-modal__projection input {
  width: 100%;
  min-height: 44px;
  padding: 10px 12px;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface);
  color: var(--ui-text);
  font: inherit;
}

.scholarship-contract-template-modal__grid textarea {
  min-height: 76px;
  resize: vertical;
}

.scholarship-contract-template-modal__grid input:focus,
.scholarship-contract-template-modal__grid textarea:focus,
.scholarship-contract-template-modal__projection input:focus {
  border-color: var(--ui-accent);
  outline: 2px solid color-mix(in srgb, var(--ui-accent) 16%, transparent);
  outline-offset: 1px;
}

.scholarship-contract-template-modal__grid small {
  color: var(--ui-chart-neutral);
  line-height: 1.35;
}

.scholarship-contract-template-modal__color-control {
  display: grid;
  grid-template-columns: 52px minmax(0, 1fr);
  gap: 8px;
  align-items: center;
}

.scholarship-contract-template-modal__color-control input[type="color"] {
  width: 52px;
  min-width: 52px;
  height: 44px;
  min-height: 44px;
  padding: 4px;
  cursor: pointer;
}

.scholarship-contract-template-modal__signature-preview {
  margin-top: 12px;
  min-height: 112px;
  padding: 14px 18px;
  display: grid;
  justify-items: center;
  align-content: end;
  gap: 5px;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-control);
  background: var(--ui-surface);
  color: var(--ui-text);
  text-align: center;
}

.scholarship-contract-template-modal__signature-preview > span {
  align-self: start;
  justify-self: start;
  color: var(--ui-muted);
  font-size: var(--ui-size-11);
  font-weight: var(--ui-weight-bold);
  text-transform: uppercase;
}

.scholarship-contract-template-modal__signature-line {
  width: min(420px, 100%);
  margin-top: 12px;
  border-top: 1px solid var(--ui-text);
}

.scholarship-contract-template-modal__signature-preview strong {
  overflow-wrap: anywhere;
}

.scholarship-contract-template-modal__signature-preview small {
  color: var(--ui-muted);
  font-weight: var(--ui-weight-bold);
}

.scholarship-contract-template-modal__table-preview {
  margin-top: 12px;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  overflow: hidden;
  border: 1px solid var(--ui-disabled-text);
  border-radius: var(--ui-radius-control);
}

.scholarship-contract-template-modal__table-preview > * {
  min-height: 42px;
  padding: 9px 12px;
  display: flex;
  align-items: center;
  border-right: 1px solid;
  border-color: inherit;
  color: var(--ui-text);
}

.scholarship-contract-template-modal__table-preview > :first-child {
  grid-column: 1 / -1;
  justify-content: center;
  border-right: 0;
  border-bottom: 1px solid;
  border-color: inherit;
  color: var(--ui-on-primary);
}

.scholarship-contract-template-modal__table-preview > :last-child {
  border-right: 0;
  background: var(--ui-surface);
}

.scholarship-contract-template-modal__section-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
}

.scholarship-contract-template-modal__section-head h4 {
  margin-bottom: 3px;
}

.scholarship-contract-template-modal__section-head p {
  margin: 0;
  color: var(--ui-chart-neutral);
}

.scholarship-contract-template-modal__section-head .ghost-button {
  width: auto;
  flex: 0 0 auto;
}

.scholarship-contract-template-modal__clause-toolbar {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  align-items: center;
  gap: 8px;
}

.scholarship-contract-template-modal__clause-toolbar > span {
  color: var(--ui-chart-neutral);
  font-size: var(--ui-size-12);
  font-weight: var(--ui-weight-bold);
  white-space: nowrap;
}

.scholarship-contract-template-modal__tokens {
  margin-top: 12px;
  padding: 10px 12px;
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
  align-items: center;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface-alt);
  color: var(--ui-text-secondary);
}

.scholarship-contract-template-modal__tokens strong {
  margin-right: 2px;
  color: var(--ui-text);
}

.scholarship-contract-template-modal__tokens code {
  padding: 3px 6px;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-sm);
  background: var(--ui-surface);
  color: var(--ui-accent);
  font-size: var(--ui-size-11);
  overflow-wrap: anywhere;
}

.scholarship-contract-template-modal__introduction,
.scholarship-contract-template-modal__clause label {
  min-width: 0;
  display: grid;
  gap: 6px;
}

.scholarship-contract-template-modal__introduction {
  margin-top: 12px;
}

.scholarship-contract-template-modal__introduction textarea {
  min-height: 180px;
}

.scholarship-contract-template-modal__introduction small {
  justify-self: end;
  color: var(--ui-chart-neutral);
}

.scholarship-contract-template-modal__introduction > span,
.scholarship-contract-template-modal__clause label > span {
  color: var(--ui-muted);
  font-size: var(--ui-size-11);
  font-weight: var(--ui-weight-bold);
  text-transform: uppercase;
}

.scholarship-contract-template-modal__introduction textarea,
.scholarship-contract-template-modal__clause input,
.scholarship-contract-template-modal__clause textarea {
  width: 100%;
  min-height: 44px;
  padding: 10px 12px;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface);
  color: var(--ui-text);
  font: inherit;
}

.scholarship-contract-template-modal__introduction textarea,
.scholarship-contract-template-modal__clause textarea {
  resize: vertical;
  line-height: 1.45;
}

.scholarship-contract-template-modal__introduction textarea:focus,
.scholarship-contract-template-modal__clause input:focus,
.scholarship-contract-template-modal__clause textarea:focus {
  border-color: var(--ui-accent);
  outline: 2px solid color-mix(in srgb, var(--ui-accent) 16%, transparent);
  outline-offset: 1px;
}

.scholarship-contract-template-modal__clauses {
  margin-top: 12px;
  display: grid;
  gap: 10px;
}

.scholarship-contract-template-modal__clause {
  padding: 12px;
  display: grid;
  grid-template-columns: minmax(180px, 0.55fr) minmax(0, 1.45fr);
  gap: 12px;
  border: 1px solid var(--ui-border);
  border-left: 3px solid var(--ui-accent);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface-alt);
}

.scholarship-contract-template-modal__clause-head {
  grid-column: 1 / -1;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.scholarship-contract-template-modal__clause-head > strong {
  color: var(--ui-text);
}

.scholarship-contract-template-modal__clause-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: end;
  justify-content: flex-end;
  gap: 6px;
}

.scholarship-contract-template-modal__clause-position {
  display: grid;
  gap: 3px;
}

.scholarship-contract-template-modal__clause-position > span {
  color: var(--ui-chart-neutral);
  font-size: var(--ui-size-11);
  font-weight: var(--ui-weight-bold);
  text-transform: uppercase;
}

.scholarship-contract-template-modal__clause-position select {
  width: 78px;
  min-height: 36px;
  padding: 5px 28px 5px 9px;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-control);
  background: var(--ui-surface);
  color: var(--ui-text);
  font: inherit;
  font-weight: var(--ui-weight-bold);
}

.scholarship-contract-template-modal__clause-icon-button {
  width: 36px;
  height: 36px;
  padding: 0;
  display: inline-grid;
  place-items: center;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-control);
  background: var(--ui-surface-alt);
  color: var(--ui-text);
  font-size: var(--ui-size-20);
  font-weight: var(--ui-weight-bold);
  line-height: 1;
  cursor: pointer;
}

.scholarship-contract-template-modal__clause-icon-button:hover:not(:disabled),
.scholarship-contract-template-modal__clause-icon-button:focus-visible {
  border-color: var(--ui-accent);
  background: var(--ui-accent-soft);
  outline: none;
}

.scholarship-contract-template-modal__clause-icon-button.is-danger {
  color: var(--ui-danger);
}

.scholarship-contract-template-modal__clause-icon-button.is-danger:hover:not(:disabled),
.scholarship-contract-template-modal__clause-icon-button.is-danger:focus-visible {
  border-color: var(--ui-chart-gold);
  background: var(--ui-danger-soft);
}

.scholarship-contract-template-modal__clause-icon-button:disabled {
  opacity: 0.42;
  cursor: not-allowed;
}

.scholarship-contract-template-modal__projection {
  margin-top: 12px;
  display: grid;
  gap: 8px;
}

.scholarship-contract-template-modal__projection > div {
  padding: 10px;
  display: grid;
  grid-template-columns: 32px minmax(180px, 0.8fr) minmax(280px, 1.4fr) auto;
  gap: 10px;
  align-items: end;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface-alt);
}

.scholarship-contract-template-modal__projection > div > span {
  width: 28px;
  height: 28px;
  margin-bottom: 8px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: var(--ui-accent);
  color: var(--ui-on-primary);
  font-size: var(--ui-size-12);
  font-weight: var(--ui-weight-bold);
}

.scholarship-contract-template-modal__projection .ghost-button {
  width: auto;
  min-height: 44px;
}

.scholarship-contract-template-modal__automatic {
  margin: 12px 0 0;
  padding: 12px 14px;
  border-left: 3px solid var(--ui-success);
  background: var(--ui-success-soft);
  color: var(--ui-success);
}

.scholarship-contract-template-modal__clause textarea {
  min-height: 156px;
}

.scholarship-contract-template-modal__clause input:disabled,
.scholarship-contract-template-modal__clause textarea:disabled {
  background: var(--ui-background);
  color: var(--ui-chart-neutral);
}

.scholarship-contract-template-modal__empty-clauses {
  margin-top: 12px;
  min-height: 150px;
  padding: 24px;
  display: grid;
  place-items: center;
  align-content: center;
  gap: 12px;
  border: 1px dashed var(--ui-border-strong);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface-alt);
  color: var(--ui-text-secondary);
  text-align: center;
}

.scholarship-contract-template-modal__empty-clauses .ghost-button {
  width: auto;
}

.scholarship-contract-template-modal__preview-context {
  margin-top: 12px;
  display: grid;
  grid-template-columns: 0.75fr 1.35fr 1fr;
  overflow: hidden;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface-alt);
}

.scholarship-contract-template-modal__preview-context > div {
  min-width: 0;
  padding: 11px 13px;
  display: grid;
  gap: 4px;
  border-right: 1px solid var(--ui-border);
}

.scholarship-contract-template-modal__preview-context > div:last-child {
  border-right: 0;
}

.scholarship-contract-template-modal__preview-context span {
  color: var(--ui-muted);
  font-size: var(--ui-size-11);
  font-weight: var(--ui-weight-bold);
  text-transform: uppercase;
}

.scholarship-contract-template-modal__preview-context strong {
  color: var(--ui-text);
  overflow-wrap: anywhere;
}

.scholarship-contract-template-modal__pdf-preview {
  margin-top: 12px;
  min-height: 520px;
  overflow: hidden;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-neutral-soft);
}

.scholarship-contract-template-modal__pdf-preview iframe {
  width: 100%;
  height: min(64vh, 700px);
  min-height: 520px;
  display: block;
  border: 0;
  background: var(--ui-surface);
}

.scholarship-contract-template-modal__preview-state {
  min-height: 520px;
  padding: 24px;
  display: grid;
  place-items: center;
  gap: 10px;
  color: var(--ui-muted);
  font-weight: var(--ui-weight-bold);
  text-align: center;
}

.scholarship-contract-template-modal__preview-state.is-error {
  align-content: center;
}

.scholarship-contract-template-modal__preview-state .form-error {
  margin: 0;
}

.scholarship-contract-template-modal__preview-state .ghost-button {
  width: auto;
}

.scholarship-contract-template-modal__actions {
  position: sticky;
  bottom: 0;
  margin: 18px -20px -20px;
  padding: 14px 20px;
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  border-top: 1px solid var(--ui-border);
  background: color-mix(in srgb, var(--ui-surface) 97%, transparent);
  backdrop-filter: blur(6px);
}

.scholarship-contract-template-modal__actions .ghost-button,
.scholarship-contract-template-modal__actions .primary-action {
  width: auto;
}

.scholarship-contracts__history td small {
  margin-top: 3px;
  color: var(--ui-chart-neutral);
}

@media (max-width: 1050px) {
  .scholarship-management__form {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .scholarship-contracts__filters {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .scholarship-contracts__filters .primary-action {
    grid-column: 1 / -1;
  }

  .scholarship-contracts__selection-bar {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .scholarship-contract-template-modal__grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .scholarship-contract-review-modal__summary {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .scholarship-contract-review-modal__summary > div:nth-child(2) {
    border-right: 0;
  }

  .scholarship-contract-review-modal__summary > div:nth-child(-n + 2) {
    border-bottom: 1px solid var(--ui-border);
  }

  .scholarship-contract-template-modal__projection > div {
    grid-template-columns: 32px minmax(160px, 0.8fr) minmax(220px, 1.2fr);
  }

  .scholarship-contract-template-modal__clause {
    grid-template-columns: 1fr;
  }

  .scholarship-contract-template-modal__projection .ghost-button {
    grid-column: 2 / -1;
    justify-self: end;
  }
}

@media (max-width: 880px) {
  .scholarship-contracts__steps {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .scholarship-contracts__steps > div:nth-child(2) {
    border-right: 0;
  }

  .scholarship-contracts__steps > div:nth-child(-n + 2) {
    border-bottom: 1px solid var(--ui-border);
  }

  .scholarship-contract-upload-modal__summary {
    grid-template-columns: 1fr;
  }

  .scholarship-contract-upload-modal__summary > div {
    border-right: 0;
    border-bottom: 1px solid var(--ui-border);
  }

  .scholarship-contract-upload-modal__summary > div:last-child {
    border-bottom: 0;
  }
}

@media (max-width: 760px) {
  .preinscripcion-scholarship-approval__toolbar {
    grid-template-columns: 1fr;
  }

  .scholarship-management__form {
    grid-template-columns: 1fr;
  }

  .scholarship-beneficiaries__summary {
    grid-template-columns: 1fr;
  }

  .scholarship-contracts__steps,
  .scholarship-contracts__filters,
  .scholarship-contracts__selection-bar,
  .scholarship-contracts__history-search,
  .scholarship-contracts__format-options,
  .scholarship-contract-template-modal__grid {
    grid-template-columns: 1fr;
  }

  .scholarship-contract-template-modal__tabs {
    grid-template-columns: 1fr;
  }

  .scholarship-contract-template-modal__tabs button {
    border-right: 0;
    border-bottom: 1px solid var(--ui-border);
  }

  .scholarship-contract-template-modal__tabs button.is-active {
    border-bottom-color: var(--ui-accent);
    box-shadow: inset 3px 0 0 var(--ui-accent);
  }

  .scholarship-contracts__template-heading,
  .scholarship-contract-template-modal__section-head {
    align-items: stretch;
    flex-direction: column;
  }

  .scholarship-contracts__template-heading .ghost-button,
  .scholarship-contract-template-modal__section-head .ghost-button {
    width: 100%;
  }

  .scholarship-contract-template-modal__table-preview {
    grid-template-columns: 1fr;
  }

  .scholarship-contract-template-modal__table-preview > * {
    border-right: 0;
    border-bottom: 1px solid var(--ui-disabled-text);
  }

  .scholarship-contract-template-modal__table-preview > :last-child {
    border-bottom: 0;
  }

  .scholarship-contract-template-modal__clause-head {
    align-items: stretch;
    flex-direction: column;
  }

  .scholarship-contract-template-modal__clause-actions,
  .scholarship-contract-template-modal__clause-toolbar {
    width: 100%;
  }

  .scholarship-contract-template-modal__clause-actions {
    justify-content: flex-start;
  }

  .scholarship-contract-template-modal__clause-position {
    flex: 1 1 110px;
  }

  .scholarship-contract-template-modal__clause-position select {
    width: 100%;
  }

  .scholarship-contract-template-modal__clause-toolbar {
