}

.preinscripcion-beca-panel .preinscripcion-beca-approval,
.preinscripcion-beca-approval {
  grid-column: 1 / -1;
  padding: 12px 14px;
  display: grid;
  grid-template-columns: auto minmax(240px, 1fr) auto;
  gap: 12px;
  align-items: center;
  border: 1px solid var(--ui-danger-border);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-danger-soft);
  color: var(--ui-primary);
}

.preinscripcion-beca-panel .preinscripcion-beca-approval strong,
.preinscripcion-beca-approval strong {
