  font-size: var(--ui-size-14);
}

.preinscripcion-beca-approval--approved {
  border-color: var(--ui-success-border);
  background: var(--ui-success-soft);
  color: var(--ui-success);
}

.planning-form {
  display: grid;
  gap: 16px;
  padding: 0 6px 24px;
}

.planning-section {
  width: 100%;
  padding: 18px;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-control);
  background: var(--ui-surface);
  box-shadow: var(--ui-shadow-sm);
}

.planning-section[hidden] {
  display: none;
}

.planning-course-summary {
  display: grid;
  gap: 2px;
  justify-items: end;
  color: var(--ui-text);
}

.planning-course-summary span {
  color: var(--ui-chart-neutral);
  font-size: var(--ui-size-12);
  font-weight: var(--ui-weight-bold);
}

.planning-document-picker {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.planning-document-option {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 4px 12px;
  align-items: center;
  min-height: 66px;
  padding: 11px 13px;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-control);
  background: var(--ui-surface-alt);
  color: var(--ui-text);
  text-align: left;
  cursor: pointer;
}

.planning-document-option > span {
  grid-row: 1 / span 2;
  display: grid;
  place-items: center;
  width: 44px;
  height: 44px;
  border-radius: var(--ui-radius-control);
  background: var(--ui-neutral-soft);
  color: var(--ui-text);
  font-weight: var(--ui-weight-bold);
}

.planning-document-option strong {
  align-self: end;
  font-size: var(--ui-size-13);
}

.planning-document-option small {
  grid-column: 3;
  grid-row: 1 / span 2;
  color: var(--ui-chart-neutral);
  font-size: var(--ui-size-11);
  font-weight: var(--ui-weight-bold);
}

.planning-document-option--active {
  border-color: var(--ui-danger);
  background: var(--ui-danger-soft);
  box-shadow: inset 3px 0 0 var(--ui-danger);
}

.planning-document-option--active > span {
  background: var(--ui-danger);
  color: var(--ui-on-primary);
}

.planning-module-nav {
  display: grid;
  grid-template-columns: repeat(8, minmax(120px, 1fr));
  gap: 7px;
  width: 100%;
  overflow-x: auto;
  padding: 8px;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-control);
  background: var(--ui-surface);
}

.planning-module-button {
  min-height: 54px;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 10px;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-control);
  background: var(--ui-surface-alt);
  color: var(--ui-text-secondary);
  font-size: var(--ui-size-12);
  font-weight: var(--ui-weight-bold);
  text-align: left;
  cursor: pointer;
}

.planning-module-index {
  width: 25px;
  height: 25px;
  flex: 0 0 25px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: var(--ui-neutral-soft);
  color: var(--ui-text);
}

.planning-module-button--active {
  border-color: var(--ui-danger);
  background: var(--ui-danger);
  color: var(--ui-on-primary);
}

.planning-module-button--active .planning-module-index {
  background: var(--ui-surface);
  color: var(--ui-danger);
}

.planning-module-copy {
  display: grid;
  gap: 2px;
  min-width: 0;
}

.planning-module-copy strong,
.planning-module-copy small {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.planning-module-copy small {
  color: var(--ui-disabled-text);
  font-size: var(--ui-size-11);
}

.planning-module-button--active .planning-module-copy small {
  color: var(--ui-on-primary);
}

.planning-module-button--complete:not(.planning-module-button--active) {
  border-color: var(--ui-success-border);
  background: var(--ui-success-soft);
}

.planning-progress {
  display: grid;
  gap: 7px;
  padding: 10px 12px;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-control);
  background: var(--ui-surface);
}

.planning-progress div {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  color: var(--ui-muted);
  font-size: var(--ui-size-12);
  font-weight: var(--ui-weight-bold);
}

.planning-progress progress {
  width: 100%;
  height: 8px;
  overflow: hidden;
  border: 0;
  border-radius: var(--ui-radius-sm);
  background: var(--ui-neutral-soft);
}

.planning-progress progress::-webkit-progress-bar { background: var(--ui-neutral-soft); }

.planning-progress progress::-webkit-progress-value { background: var(--ui-accent); }

.planning-progress progress::-moz-progress-bar { background: var(--ui-accent); }

.planning-section--course {
  border-top: 3px solid var(--ui-danger);
}

.planning-course-select {
  display: grid;
  gap: 7px;
  width: 100%;
}

.planning-course-select select {
  width: 100%;
}

.planning-fields {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
}

.planning-fields--three {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.planning-fields--four {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.planning-fields label,
.planning-section label {
  display: grid;
  align-content: start;
  gap: 6px;
  min-width: 0;
}

.planning-fields label > span,
.planning-course-select > span {
  color: var(--ui-muted);
  font-size: var(--ui-size-12);
  font-weight: var(--ui-weight-bold);
}

.planning-fields input,
.planning-fields select,
.planning-fields textarea,
.planning-course-select select,
.planning-topic-table input,
.planning-topic-table textarea {
  width: 100%;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-control);
  background: var(--ui-surface);
  color: var(--ui-text);
}

.planning-fields input,
.planning-fields select,
.planning-course-select select {
  min-height: 42px;
  padding: 9px 11px;
}

.planning-fields input[readonly] {
  border-color: var(--ui-border);
  background: var(--ui-accent-soft);
  color: var(--ui-text);
  cursor: default;
  font-weight: var(--ui-weight-bold);
}

.planning-fields textarea {
  min-height: 108px;
  padding: 10px 11px;
  resize: vertical;
}

.planning-span-two {
  grid-column: span 2;
}

.planning-span-three {
  grid-column: span 3;
}

.planning-actions,
.planning-footer-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 10px;
  margin-top: 14px;
}

.planning-message {
  margin: 12px 0 0;
  padding: 10px 12px;
  border-radius: var(--ui-radius-control);
  font-weight: var(--ui-weight-bold);
}

.planning-message--ok {
  background: var(--ui-neutral-soft);
  color: var(--ui-success);
}

.planning-message--error {
  background: var(--ui-primary-soft);
  color: var(--ui-primary);
}

.planning-unit {
  margin-top: 14px;
  padding: 14px;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-control);
  background: var(--ui-surface-alt);
}

.planning-unit-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 12px;
  color: var(--ui-text);
}

.planning-topic-table-wrap {
  width: 100%;
  margin: 14px 0 10px;
  overflow-x: auto;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-control);
  background: var(--ui-surface);
}

.planning-topic-table {
  width: 100%;
  min-width: 1420px;
  border-collapse: collapse;
  table-layout: fixed;
}

.planning-topic-table th {
  padding: 9px 7px;
  background: var(--ui-accent-soft);
  color: var(--ui-text);
  font-size: var(--ui-size-11);
  text-align: left;
}

.planning-topic-table th:nth-child(1) { width: 190px; }

.planning-topic-table th:nth-child(2),
.planning-topic-table th:nth-child(3),
.planning-topic-table th:nth-child(4),
.planning-topic-table th:nth-child(5) { width: 66px; text-align: center; }

.planning-topic-table th:nth-child(6),
.planning-topic-table th:nth-child(7),
.planning-topic-table th:nth-child(8) { width: 180px; }

.planning-topic-table th:nth-child(9) { width: 150px; }

.planning-topic-table th:nth-child(10) { width: 78px; text-align: center; }

.planning-topic-table td {
  padding: 6px;
  border-top: 1px solid var(--ui-border);
  vertical-align: top;
}

.planning-topic-table input {
  min-height: 38px;
  padding: 7px;
  text-align: center;
}

.planning-topic-table textarea {
  min-height: 72px;
  padding: 7px;
  resize: vertical;
}

.planning-topic-table td:last-child {
  text-align: center;
}

.planning-total-ok { color: var(--ui-success); }

.planning-total-error { color: var(--ui-danger); }

.planning-signature-section {
  border-left: 4px solid var(--ui-danger);
}

.planning-signer-card {
  display: grid;
  gap: 4px;
  margin-bottom: 14px;
  padding: 13px 15px;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-control);
  background: var(--ui-accent-soft);
  color: var(--ui-text);
}

.planning-signer-card span,
.planning-signer-card small {
  color: var(--ui-muted);
  font-size: var(--ui-size-12);
}

.planning-signer-card strong {
  font-size: var(--ui-size-16);
}

.planning-preview-modal {
  width: min(1280px, 100%);
  height: min(94vh, 920px);
}

.planning-signature-status {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 8px 18px;
  margin-top: 12px;
  padding: 10px 12px;
  border-radius: var(--ui-radius-control);
  background: var(--ui-accent-soft);
  color: var(--ui-text-secondary);
  font-size: var(--ui-size-12);
  font-weight: var(--ui-weight-bold);
}

.planning-footer-actions {
  position: sticky;
  bottom: 8px;
  z-index: 4;
  padding: 12px;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-control);
  background: color-mix(in srgb, var(--ui-surface) 96%, transparent);
  box-shadow: var(--ui-shadow-sm);
}

@media (max-width: 1100px) {
  .planning-fields--four,
  .planning-fields--three {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .planning-span-three { grid-column: span 2; }
  .portal-compliance-steps { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}

@media (max-width: 700px) {
  .planning-section { padding: 14px; }
  .planning-fields,
  .planning-fields--four,
  .planning-fields--three { grid-template-columns: 1fr; }
  .planning-span-two,
  .planning-span-three { grid-column: auto; }
  .planning-actions,
  .planning-footer-actions { display: grid; grid-template-columns: 1fr; }
  .planning-actions button,
  .planning-footer-actions button { width: 100%; }
  .planning-module-nav { grid-template-columns: repeat(8, minmax(150px, 1fr)); }
  .planning-document-picker,
  .portal-compliance-steps { grid-template-columns: 1fr; }
  .planning-document-option { grid-template-columns: auto minmax(0, 1fr); }
  .planning-document-option small { grid-column: 2; grid-row: auto; }
  .planning-course-summary { justify-items: start; }
}

