  color: var(--ui-chart-neutral);
  font-size: var(--ui-size-11);
  font-weight: var(--ui-weight-bold);
}

.contract-data-grid dd {
  margin: 0;
  overflow-wrap: anywhere;
  color: var(--ui-text);
  font-weight: var(--ui-weight-bold);
}

.contract-table-wrap {
  margin-top: 14px;
  overflow-x: auto;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-control);
}

.contract-table {
  width: 100%;
  min-width: 1120px;
  border-collapse: collapse;
}

.contract-table th {
  padding: 10px;
  background: var(--ui-accent-soft);
  color: var(--ui-text);
  font-size: var(--ui-size-11);
  text-align: left;
}

.contract-table td {
  padding: 11px 10px;
  border-top: 1px solid var(--ui-border);
  color: var(--ui-text);
  vertical-align: middle;
}

.contract-table td strong,
.contract-table td small { display: block; }

.contract-table td small { margin-top: 3px; color: var(--ui-chart-neutral); }

.contract-class-status {
  display: inline-block;
  padding: 5px 8px;
  border-radius: var(--ui-radius-sm);
  background: var(--ui-neutral-soft);
  color: var(--ui-success);
  font-size: var(--ui-size-11);
  font-weight: var(--ui-weight-bold);
}

.contract-table-empty { padding: 24px !important; text-align: center; }

.contract-empty,
.contract-notice {
  padding: 20px;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-control);
  background: var(--ui-surface);
}

.contract-empty span { color: var(--ui-danger); font-size: var(--ui-size-11); font-weight: var(--ui-weight-bold); text-transform: uppercase; }

.contract-empty h2 { margin: 5px 0; color: var(--ui-text); }

.contract-empty p { margin: 0; color: var(--ui-muted); }

.contract-empty .primary-action { margin-top: 16px; }

.contract-notice--error { border-color: var(--ui-primary-border); background: var(--ui-danger-soft); color: var(--ui-primary); font-weight: var(--ui-weight-bold); }

.contract-notice--success { border-color: var(--ui-success-border); background: var(--ui-success-soft); color: var(--ui-success); font-weight: var(--ui-weight-bold); }

.contract-notice--warning { border-color: var(--ui-warning-border); background: var(--ui-warning-soft); color: var(--ui-warning); font-weight: var(--ui-weight-bold); }

.contract-document-actions {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 16px;
  align-items: center;
  padding: 14px 18px;
  border: 1px solid var(--ui-border);
  border-left: 4px solid var(--ui-accent);
  border-radius: var(--ui-radius-control);
  background: var(--ui-surface-alt);
}

.contract-document-actions > div:first-child {
  display: grid;
  min-width: 0;
  gap: 3px;
}

.contract-document-actions span,
.contract-local-preview > span {
  color: var(--ui-accent);
  font-size: var(--ui-size-11);
  font-weight: var(--ui-weight-bold);
  text-transform: uppercase;
}

.contract-document-actions strong {
  overflow: hidden;
  color: var(--ui-text);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.contract-document-actions small { color: var(--ui-chart-neutral); }

.contract-document-modal {
  width: min(1460px, calc(100vw - 28px));
  height: min(920px, calc(100vh - 28px));
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  overflow: hidden;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface);
  box-shadow: var(--ui-shadow-dialog);
}

.contract-document-modal > header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 15px 18px;
  border-bottom: 1px solid var(--ui-border);
  background: var(--ui-surface-alt);
}

.contract-document-modal > header span {
  color: var(--ui-danger);
  font-size: var(--ui-size-11);
  font-weight: var(--ui-weight-bold);
  text-transform: uppercase;
}

.contract-document-modal > header h2 {
  margin: 3px 0;
  color: var(--ui-text);
  font-size: var(--ui-size-20);
}

.contract-document-modal > header p {
  margin: 0;
  color: var(--ui-chart-neutral);
  font-size: var(--ui-size-12);
}

.contract-document-modal-body,
.contract-sign-layout {
  display: grid;
  grid-template-columns: minmax(460px, 0.9fr) minmax(520px, 1.1fr);
  min-height: 0;
}

.contract-upload-form,
.contract-sign-form {
  min-height: 0;
  overflow-y: auto;
  padding: 18px;
}

.contract-upload-form {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  align-content: start;
  gap: 13px;
  border-right: 1px solid var(--ui-border);
}

.contract-upload-form label,
.contract-sign-form label {
  display: grid;
  min-width: 0;
  gap: 6px;
}

.contract-upload-form label > span,
.contract-sign-form label > span {
  color: var(--ui-muted);
  font-size: var(--ui-size-11);
  font-weight: var(--ui-weight-bold);
}

.contract-upload-form input,
.contract-upload-form select,
.contract-upload-form textarea,
.contract-sign-form input {
  width: 100%;
  min-width: 0;
  padding: 10px 11px;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-control);
  background: var(--ui-surface);
  color: var(--ui-text);
  font: inherit;
}

.contract-upload-form input[readonly] { background: var(--ui-background); font-weight: var(--ui-weight-bold); }

.contract-upload-form textarea { resize: vertical; }

.contract-upload-form small,
.contract-sign-form small { color: var(--ui-chart-neutral); font-size: var(--ui-size-11); }

.contract-form-wide { grid-column: 1 / -1; }

.contract-file-picker { padding: 12px; border: 1px solid var(--ui-border); border-radius: var(--ui-radius-control); background: var(--ui-surface-alt); }

.contract-analysis-card {
  display: grid;
  gap: 10px;
  padding: 13px;
  border: 1px solid var(--ui-success-border);
  border-left: 4px solid var(--ui-success);
  border-radius: var(--ui-radius-control);
  background: var(--ui-surface-alt);
}

.contract-analysis-card[data-valid='false'] {
  border-color: var(--ui-warning-border);
  border-left-color: var(--ui-chart-gold);
  background: var(--ui-warning-soft);
}

.contract-analysis-card > header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.contract-analysis-card > header > div {
  display: grid;
  gap: 2px;
}

.contract-analysis-card > header span,
.contract-analysis-card dt {
  color: var(--ui-muted);
  font-size: var(--ui-size-11);
  font-weight: var(--ui-weight-bold);
  text-transform: uppercase;
}

.contract-analysis-card > header strong { color: var(--ui-success); }

.contract-analysis-card[data-valid='false'] > header strong { color: var(--ui-warning); }

.contract-analysis-card dl {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  margin: 0;
  border-top: 1px solid color-mix(in srgb, var(--ui-accent) 18%, transparent);
}

.contract-analysis-card dl > div {
  min-width: 0;
  padding: 9px 10px 3px 0;
}

.contract-analysis-card dd {
  overflow-wrap: anywhere;
  margin: 3px 0 0;
  color: var(--ui-text);
  font-size: var(--ui-size-12);
  font-weight: var(--ui-weight-bold);
}

.contract-analysis-card > p {
  margin: 0;
  color: var(--ui-warning);
  font-size: var(--ui-size-11);
  line-height: 1.45;
}

.contract-local-preview,
.contract-sign-preview {
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  min-width: 0;
  min-height: 0;
  gap: 10px;
  padding: 18px;
  background: var(--ui-neutral-soft);
}

.contract-local-preview iframe,
.contract-sign-preview iframe {
  width: 100%;
  height: 100%;
  min-height: 460px;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-sm);
  background: var(--ui-surface);
}

.contract-local-preview > p,
.contract-sign-preview > p {
  display: grid;
  place-items: center;
  margin: 0;
  color: var(--ui-chart-neutral);
  text-align: center;
}

.contract-document-preview-modal {
  width: min(1380px, calc(100vw - 28px));
  height: min(940px, calc(100vh - 28px));
}

.contract-sign-layout { grid-template-columns: minmax(520px, 1.15fr) minmax(380px, 0.85fr); }

.contract-sign-preview { padding: 12px; border-right: 1px solid var(--ui-border); }

.contract-sign-form {
  display: grid;
  align-content: start;
  gap: 13px;
}

.contract-sign-warning {
  padding: 11px 12px;
  border-left: 4px solid var(--ui-accent);
  border-radius: var(--ui-radius-sm);
  background: var(--ui-accent-soft);
  color: var(--ui-text);
  font-size: var(--ui-size-12);
  font-weight: var(--ui-weight-bold);
  line-height: 1.45;
}

.contract-password-field {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 7px;
}

.contract-sign-consent {
  grid-template-columns: auto minmax(0, 1fr) !important;
  align-items: start;
  padding: 10px;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-control);
}

.contract-sign-consent input { width: 18px; height: 18px; }

.contract-sign-consent span { text-transform: none; line-height: 1.4; }

.contract-ephemeral-note { display: block; padding-top: 4px; border-top: 1px solid var(--ui-border); }

@media (max-width: 900px) {
  .contract-summary { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .contract-summary > div:nth-child(2) { border-right: 0; }
  .contract-summary > div:nth-child(-n + 2) { border-bottom: 1px solid var(--ui-border); }
  .contract-data-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .contract-document-modal-body,
  .contract-sign-layout { grid-template-columns: 1fr; overflow-y: auto; }
  .contract-upload-form,
  .contract-sign-preview { border-right: 0; border-bottom: 1px solid var(--ui-border); overflow: visible; }
  .contract-local-preview iframe,
  .contract-sign-preview iframe { min-height: 520px; }
}

@media (max-width: 650px) {
  .contract-toolbar,
  .contract-summary,
  .contract-data-grid { grid-template-columns: 1fr; }
  .contract-summary > div { border-right: 0; border-bottom: 1px solid var(--ui-border); }
  .contract-summary > div:last-child { border-bottom: 0; }
  .contract-point { padding-inline: 14px; }
  .contract-hero-actions,
  .contract-document-actions > div:last-child { width: 100%; }
  .contract-hero-actions > button,
  .contract-document-actions button { flex: 1 1 auto; }
  .contract-document-actions { grid-template-columns: 1fr; }
  .contract-upload-form { grid-template-columns: 1fr; }
  .contract-form-wide { grid-column: auto; }
  .contract-analysis-card dl { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}

/* Calificaciones administrativas por docente, asignatura y periodo. */

