.matricula-acad-shell {
  display: grid;
  gap: 14px;
  min-width: 0;
}

.matricula-mode-nav {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1px;
  overflow: hidden;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-control);
  background: var(--ui-border);
}

.prerequisite-management-page {
  display: grid;
  gap: 14px;
  min-width: 0;
}

.prerequisite-management-page .report-header,
.prerequisite-rule-form,
.prerequisite-rule-list {
  width: 100%;
  max-width: none;
  margin: 0;
}

.prerequisite-form-grid {
  display: grid;
  grid-template-columns: minmax(220px, 0.8fr) minmax(280px, 1.25fr) minmax(280px, 1.25fr) auto;
  align-items: end;
  gap: 12px;
}

.prerequisite-form-grid label,
