  width: 100%;
  min-height: 42px;
  padding: 9px 12px;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-control);
  background: var(--ui-surface);
  color: var(--ui-text);
}

.prerequisite-form-grid .primary-action {
  min-height: 42px;
  white-space: nowrap;
}

.prerequisite-search {
  margin-bottom: 12px;
}

.prerequisite-rules-table th:nth-child(1),
.prerequisite-rules-table th:nth-child(2) {
  width: 36%;
}

.prerequisite-rules-table th:nth-child(3) {
  width: 12%;
}

.prerequisite-rules-table th:nth-child(4) {
  width: 16%;
}

.prerequisite-rules-table td strong,
.prerequisite-rules-table td small {
  display: block;
}

.prerequisite-rules-table td small {
  margin-top: 4px;
  color: var(--ui-chart-neutral);
}

.prerequisite-rule--invalid {
