}

.prerequisite-row-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.matricula-mode-nav__button {
  min-height: 70px;
  padding: 12px 16px;
  border: 0;
  border-radius: 0;
  background: var(--ui-surface);
  color: var(--ui-text);
  text-align: left;
  cursor: pointer;
}

.matricula-mode-nav__button strong,
.matricula-mode-nav__button span {
  display: block;
}

.matricula-mode-nav__button strong {
  font-size: var(--ui-size-14);
}

.matricula-mode-nav__button span {
  margin-top: 4px;
  color: var(--ui-chart-neutral);
