}

.matricula-student-results b {
  color: var(--ui-accent);
}

.matricula-student-summary,
.matricula-preview-summary {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  margin-bottom: 14px;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-control);
