.matricula-preview-summary strong {
  display: block;
}

.matricula-student-summary span,
.matricula-preview-summary span {
  color: var(--ui-chart-neutral);
  font-size: var(--ui-size-11);
  font-weight: var(--ui-weight-bold);
  text-transform: uppercase;
}

.matricula-student-summary strong,
.matricula-preview-summary strong {
  margin-top: 4px;
  overflow-wrap: anywhere;
}

.matricula-individual-form-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
}

.matricula-individual-form-grid label:nth-child(1),
.matricula-individual-form-grid label:nth-child(2) {
  grid-column: span 2;
}

.matricula-subject-toolbar {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 12px;
}

.matricula-subject-toolbar label {
  width: min(320px, 100%);
}

.matricula-subject-toolbar > div,
.matricula-individual-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.matricula-prerequisite-table th:first-child,
.matricula-prerequisite-table td:first-child {
