}

.matricula-prerequisite-table th:nth-child(3),
.matricula-prerequisite-table td:nth-child(3) {
  width: 125px;
}

.matricula-prerequisite-table th:nth-child(5),
.matricula-prerequisite-table td:nth-child(5) {
