  opacity: 0.55;
}

.moodle-status-grid,
.moodle-detail-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-panel);
  overflow: hidden;
}

.moodle-status-grid {
  background: var(--ui-accent-soft);
}

.moodle-detail-grid {
  margin-top: 12px;
  background: var(--ui-surface-alt);
}

.moodle-status-grid > div,
.moodle-detail-grid > div {
