  padding: 14px 16px;
  border-right: 1px solid var(--ui-border);
}

.moodle-status-grid > div:last-child,
.moodle-detail-grid > div:last-child {
  border-right: 0;
}

.moodle-status-grid strong,
.moodle-detail-grid strong {
  display: block;
  margin-top: 6px;
  overflow-wrap: anywhere;
}

.moodle-functions {
