}

.moodle-functions > div {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 10px 12px;
  border-bottom: 1px solid var(--ui-neutral-soft);
}

.moodle-functions code {
  overflow-wrap: anywhere;
}

.moodle-badge {
