/* Administración relacionada de dbo.CARRERAS y dbo.PENSUM. */

.career-pensum {
  display: grid;
  gap: 12px;
  min-width: 0;
  margin-top: 12px;
}

.career-pensum__layout {
  display: grid;
  grid-template-columns: minmax(280px, 340px) minmax(0, 1fr);
  min-height: 640px;
  border: 1px solid var(--line-strong);
  border-radius: var(--ui-radius-panel);
  overflow: hidden;
  background: var(--ui-surface);
}

.career-pensum__careers,
.career-pensum__subjects {
  min-width: 0;
}

.career-pensum__careers {
  display: grid;
  grid-template-rows: auto auto minmax(0, 1fr) auto;
  border-right: 1px solid var(--line-strong);
  background: var(--ui-surface-alt);
}

.career-pensum__subjects {
  display: flex;
  flex-direction: column;
  background: var(--ui-surface);
}

.career-pensum__section-head,
.career-pensum__career-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 14px 16px;
  border-bottom: 1px solid var(--line-strong);
}

.career-pensum__section-head > div,
.career-pensum__career-head > div:first-child {
  display: grid;
  gap: 3px;
  min-width: 0;
}

.career-pensum__section-head span,
.career-pensum__career-head span,
.career-pensum__metrics span,
.career-pensum__relation span {
  color: var(--muted);
  font-size: var(--ui-size-11);
  font-weight: var(--ui-weight-bold);
  text-transform: uppercase;
}

.career-pensum__section-head strong {
  color: var(--ink);
  font-size: var(--ui-size-16);
}

.career-pensum__section-head button,
.career-pensum__career-head button,
.career-pensum__search button,
.career-pensum__subject-toolbar button,
.career-pensum__pager button {
  min-height: 38px;
  border: 1px solid var(--line-strong);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface);
  color: var(--ink);
  font: inherit;
  font-size: var(--ui-size-12);
  font-weight: var(--ui-weight-bold);
  padding: 8px 12px;
  cursor: pointer;
}

.career-pensum__section-head .primary-action,
.career-pensum__career-head .primary-action {
  border-color: var(--ui-primary);
  background: var(--ui-primary);
  color: var(--ui-on-primary);
}

.career-pensum__section-head button:disabled,
.career-pensum__career-head button:disabled,
.career-pensum__search button:disabled,
.career-pensum__subject-toolbar button:disabled,
.career-pensum__pager button:disabled {
  cursor: not-allowed;
  opacity: 0.5;
}

.career-pensum__search,
.career-pensum__subject-toolbar {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: end;
  gap: 8px;
  padding: 12px 14px;
  border-bottom: 1px solid var(--line-strong);
}

.career-pensum__search label,
.career-pensum__subject-toolbar label,
.career-pensum__form label {
  display: grid;
  gap: 6px;
  min-width: 0;
  color: var(--ink-soft);
  font-size: var(--ui-size-11);
  font-weight: var(--ui-weight-bold);
}

.career-pensum__search input,
.career-pensum__subject-toolbar input,
.career-pensum__form input,
.career-pensum__form select,
.career-pensum__form textarea {
  width: 100%;
  min-height: 40px;
  border: 1px solid color-mix(in srgb, var(--ui-accent-border) 66%, transparent);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface);
  color: var(--ink);
  font: inherit;
  font-size: var(--ui-size-13);
  padding: 8px 10px;
}

.career-pensum__search input:focus,
.career-pensum__subject-toolbar input:focus,
.career-pensum__form input:focus,
.career-pensum__form select:focus,
.career-pensum__form textarea:focus {
  border-color: var(--ui-accent);
  box-shadow: var(--ui-shadow-sm);
  outline: none;
}

.career-pensum__career-list {
  display: grid;
  align-content: start;
  gap: 0;
  min-height: 0;
  overflow-y: auto;
}

.career-pensum__career-list > button {
  position: relative;
  display: grid;
  gap: 4px;
  width: 100%;
  min-height: 70px;
  border: 0;
  border-bottom: 1px solid color-mix(in srgb, var(--ui-accent-border) 34%, transparent);
  background: transparent;
  color: var(--ink);
  padding: 12px 46px 12px 16px;
  text-align: left;
  cursor: pointer;
}

.career-pensum__career-list > button:hover {
  background: color-mix(in srgb, var(--ui-accent-border) 10%, transparent);
}

.career-pensum__career-list > button.is-active {
  border-left: 4px solid var(--ui-primary);
  background: var(--ui-surface);
  padding-left: 12px;
}

.career-pensum__career-list strong,
.career-pensum__career-list span {
  overflow-wrap: anywhere;
}

.career-pensum__career-list strong {
  font-size: var(--ui-size-13);
  line-height: 1.35;
}

.career-pensum__career-list span {
  color: var(--muted);
  font-size: var(--ui-size-11);
  line-height: 1.35;
}

.career-pensum__career-list em {
  position: absolute;
  top: 13px;
  right: 12px;
  color: var(--ui-accent);
  font-size: var(--ui-size-11);
  font-style: normal;
  font-weight: var(--ui-weight-bold);
}

.career-pensum__career-list > p,
.career-pensum__empty {
  color: var(--muted);
  font-size: var(--ui-size-13);
  padding: 24px 16px;
}

.career-pensum__career-head {
  align-items: flex-start;
  min-height: 88px;
}

.career-pensum__career-head h3 {
  margin: 0;
  color: var(--ink);
  font-size: var(--ui-size-20);
  line-height: 1.25;
  overflow-wrap: anywhere;
}

.career-pensum__career-head p {
  margin: 2px 0 0;
  color: var(--muted);
  font-size: var(--ui-size-12);
}

.career-pensum__career-head > div:last-child {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 8px;
}

.career-pensum__metrics {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  border-bottom: 1px solid var(--line-strong);
  background: var(--ui-surface-alt);
}

.career-pensum__metrics > div {
  display: grid;
  align-content: center;
  gap: 5px;
  min-height: 72px;
  padding: 11px 14px;
  border-right: 1px solid var(--line-strong);
}

.career-pensum__metrics > div:last-child {
  border-right: 0;
}

.career-pensum__metrics strong {
  color: var(--ink);
  font-size: var(--ui-size-14);
  overflow-wrap: anywhere;
}

.career-pensum__subject-toolbar {
  grid-template-columns: minmax(260px, 560px) auto;
  justify-content: space-between;
}

.career-pensum__table-wrap {
  flex: 1;
  max-height: 430px;
  border: 0;
  border-radius: 0;
}

.career-pensum__table {
  min-width: 1240px;
  table-layout: fixed;
}

.career-pensum__table th:nth-child(1) { width: 78px; }

.career-pensum__table th:nth-child(2) { width: 130px; }

.career-pensum__table th:nth-child(3) { width: 260px; }

.career-pensum__table th:nth-child(4) { width: 130px; }

.career-pensum__table th:nth-child(5) { width: 88px; }

.career-pensum__table th:nth-child(6) { width: 88px; }

.career-pensum__table th:nth-child(7) { width: 78px; }

.career-pensum__table th:nth-child(8) { width: 82px; }

.career-pensum__table th:nth-child(9) { width: 82px; }

.career-pensum__table th:nth-child(10) { width: 105px; }

.career-pensum__table th:nth-child(11) { width: 88px; }

.career-pensum__table td {
  overflow-wrap: anywhere;
}

.career-pensum__table .career-pensum__row--created > td {
  background: var(--ui-success-soft);
  box-shadow: inset 0 1px 0 var(--ui-success-border), inset 0 -1px 0 var(--ui-success-border);
}

.career-pensum__table .career-pensum__row--created > td:first-child {
  box-shadow: inset 4px 0 0 var(--ui-success), inset 0 1px 0 var(--ui-success-border), inset 0 -1px 0 var(--ui-success-border);
}

.career-pensum__pager {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  min-height: 58px;
  padding: 10px 14px;
  border-top: 1px solid var(--line-strong);
  background: var(--ui-surface);
}

.career-pensum__pager > span {
  color: var(--muted);
  font-size: var(--ui-size-11);
  font-weight: var(--ui-weight-bold);
}

.career-pensum__pager > div {
  display: flex;
  gap: 6px;
}

.career-pensum__pager button {
  width: 38px;
  min-width: 38px;
  padding: 0;
  font-size: var(--ui-size-18);
  white-space: nowrap;
}

.career-pensum__empty {
  display: grid;
  place-content: center;
  gap: 5px;
  min-height: 420px;
  text-align: center;
}

.career-pensum__empty strong {
  color: var(--ink);
  font-size: var(--ui-size-16);
}

.career-pensum__modal {
  width: min(1120px, 96vw);
  max-width: 1120px;
}

.career-pensum__modal-overlay {
  z-index: 1400;
}

.career-pensum__relation {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 12px;
  margin-bottom: 14px;
  padding: 11px 13px;
  border: 1px solid var(--line-strong);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface-alt);
}

.career-pensum__relation strong {
  color: var(--ink);
  font-size: var(--ui-size-14);
}

.career-pensum__relation em {
  color: var(--ui-accent);
  font-size: var(--ui-size-11);
  font-style: normal;
  font-weight: var(--ui-weight-bold);
}

.career-pensum__modal-error {
  margin: 0 0 14px;
  border-radius: var(--ui-radius-control);
}

.career-pensum__form {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.career-pensum__form .career-pensum__field--wide {
  grid-column: 1 / -1;
}

.career-pensum__form textarea {
  min-height: 100px;
  resize: vertical;
}

@media (max-width: 1180px) {
  .career-pensum__layout {
    grid-template-columns: minmax(250px, 300px) minmax(0, 1fr);
  }

  .career-pensum__metrics {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .career-pensum__metrics > div:nth-child(2) {
    border-right: 0;
  }

  .career-pensum__metrics > div:nth-child(-n + 2) {
    border-bottom: 1px solid var(--line-strong);
  }
}

@media (max-width: 860px) {
  .career-pensum__layout {
    grid-template-columns: minmax(0, 1fr);
  }

  .career-pensum__careers {
    grid-template-rows: auto auto minmax(160px, 280px) auto;
    border-right: 0;
    border-bottom: 1px solid var(--line-strong);
  }

  .career-pensum__form {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 620px) {
  .career-pensum__modal-overlay {
    align-items: stretch;
    padding: 6px;
  }

  .career-pensum__modal {
    width: 100%;
    max-width: 100%;
    max-height: calc(100dvh - 12px);
    border-radius: var(--ui-radius-panel);
  }

  .career-pensum__modal .gestion-sis-modal-actions {
    position: static;
  }

  .career-pensum__section-head,
  .career-pensum__career-head,
  .career-pensum__pager {
    align-items: stretch;
    flex-direction: column;
  }

  .career-pensum__section-head button,
  .career-pensum__career-head button,
  .career-pensum__search button,
  .career-pensum__subject-toolbar button,
  .career-pensum__pager button {
    width: 100%;
  }

  .career-pensum__career-head > div:last-child,
  .career-pensum__pager > div {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .career-pensum__search,
  .career-pensum__subject-toolbar,
  .career-pensum__form,
  .career-pensum__relation,
  .career-pensum__metrics {
    grid-template-columns: minmax(0, 1fr);
  }

  .career-pensum__metrics > div {
    border-right: 0;
    border-bottom: 1px solid var(--line-strong);
  }

  .career-pensum__metrics > div:last-child {
    border-bottom: 0;
  }

  .career-pensum__relation {
    align-items: start;
  }
}

/* Moodle: matrícula manual masiva con resolución explícita de identidades. */

.moodle-manual-enrollment .moodle-section__heading p {
  margin: 6px 0 0;
  color: var(--ui-muted);
}

.moodle-manual-form {
  display: grid;
  grid-template-columns: minmax(320px, 0.9fr) minmax(420px, 1.1fr);
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-panel);
  overflow: hidden;
  background: var(--ui-surface-alt);
}

.moodle-manual-course,
.moodle-manual-names {
  display: grid;
  align-content: start;
  gap: 14px;
  min-width: 0;
  padding: 18px;
}

.moodle-manual-course {
  border-right: 1px solid var(--ui-border);
}

.moodle-manual-step-heading,
.moodle-manual-results > header > div,
.moodle-manual-preview > header > div {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}

.moodle-manual-step-heading > span,
.moodle-manual-results > header > div > span,
.moodle-manual-preview > header > div > span {
  display: inline-flex;
  flex: 0 0 30px;
  align-items: center;
  justify-content: center;
  width: 30px;
  height: 30px;
  border-radius: 50%;
  background: var(--ui-accent);
  color: var(--ui-on-primary);
  font-size: var(--ui-size-13);
  font-weight: var(--ui-weight-bold);
}

.moodle-manual-step-heading > div,
.moodle-manual-results > header > div > div,
.moodle-manual-preview > header > div > div {
  display: grid;
  min-width: 0;
  gap: 3px;
}

.moodle-manual-step-heading small,
.moodle-manual-results header small,
.moodle-manual-preview header small {
  color: var(--ui-chart-neutral);
}

.moodle-manual-form label {
  display: grid;
  gap: 6px;
  min-width: 0;
  color: var(--ui-accent-hover);
  font-size: var(--ui-size-13);
  font-weight: var(--ui-weight-bold);
}

.moodle-manual-form input,
.moodle-manual-form select,
.moodle-manual-form textarea {
  width: 100%;
  min-width: 0;
  min-height: 44px;
  padding: 9px 11px;
  border: 1px solid var(--ui-border-strong);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface);
  color: var(--ui-text);
  font: inherit;
}

.moodle-manual-form textarea {
  min-height: 190px;
  resize: vertical;
  line-height: 1.45;
}

.moodle-manual-form input:focus,
.moodle-manual-form select:focus,
.moodle-manual-form textarea:focus {
  border-color: var(--ui-accent);
  outline: 3px solid color-mix(in srgb, var(--ui-accent) 12%, transparent);
}

.moodle-manual-form input:disabled,
.moodle-manual-form select:disabled,
.moodle-manual-form textarea:disabled {
  background: var(--ui-background);
  cursor: not-allowed;
  opacity: 0.75;
}

.moodle-manual-form label > small {
  color: var(--ui-chart-neutral);
  font-weight: var(--ui-weight-medium);
  overflow-wrap: anywhere;
}

.moodle-manual-names > .moodle-button {
  justify-self: end;
  min-width: 230px;
}

.moodle-manual-results,
.moodle-manual-preview,
.moodle-manual-complete {
  margin-top: 20px;
  padding-top: 20px;
  border-top: 1px solid var(--ui-border);
}

.moodle-manual-results > header,
.moodle-manual-preview > header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 14px;
}

.moodle-manual-summary {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  margin-bottom: 14px;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-panel);
  overflow: hidden;
  background: var(--ui-accent-soft);
}

.moodle-manual-summary > div {
  min-width: 0;
  padding: 12px 14px;
  border-right: 1px solid var(--ui-border);
}

.moodle-manual-summary > div:last-child {
  border-right: 0;
}

.moodle-manual-summary span,
.moodle-manual-summary strong {
  display: block;
  overflow-wrap: anywhere;
}

.moodle-manual-summary span {
  color: var(--ui-chart-neutral);
  font-size: var(--ui-size-11);
  font-weight: var(--ui-weight-bold);
  text-transform: uppercase;
}

.moodle-manual-summary strong {
  margin-top: 5px;
  font-size: var(--ui-size-20);
}

.moodle-manual-query-list {
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-panel);
  overflow: hidden;
}

.moodle-manual-query-list > article {
  padding: 0;
  border-bottom: 1px solid var(--ui-border);
  background: var(--ui-surface);
}

.moodle-manual-query-list > article:last-child {
  border-bottom: 0;
}

.moodle-manual-query-list > article > header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 12px 14px;
  background: var(--ui-surface-alt);
}

.moodle-manual-query-list > article > header > div,
.moodle-manual-candidate-identity,
.moodle-manual-candidate-reference {
  display: grid;
  min-width: 0;
  gap: 3px;
}

.moodle-manual-query-list > article > header strong,
.moodle-manual-candidate-identity strong,
.moodle-manual-candidate-reference strong {
  overflow-wrap: anywhere;
}

.moodle-manual-query-list > article > p {
  margin: 0;
  padding: 14px;
  color: var(--ui-primary-hover);
}

.moodle-manual-candidates > label {
  display: grid;
  grid-template-columns: auto minmax(220px, 1.4fr) minmax(160px, 0.8fr) minmax(110px, auto) minmax(140px, auto);
  align-items: center;
  gap: 12px;
  padding: 12px 14px;
  border-top: 1px solid var(--ui-neutral-soft);
  cursor: pointer;
}

.moodle-manual-candidates > label:first-child {
  border-top: 0;
}

.moodle-manual-candidates > label:has(input:checked) {
  background: var(--ui-accent-soft);
  box-shadow: inset 4px 0 0 var(--ui-accent);
}

.moodle-manual-candidates > label.is-disabled {
  background: var(--ui-surface-alt);
  cursor: not-allowed;
  opacity: 0.75;
}

.moodle-manual-candidates input[type='radio'] {
  width: 18px;
  height: 18px;
  margin: 0;
  accent-color: var(--ui-accent);
}

.moodle-manual-candidate-identity small,
.moodle-manual-candidate-reference small {
  color: var(--ui-chart-neutral);
  overflow-wrap: anywhere;
}

.moodle-manual-status {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: fit-content;
  min-height: 28px;
  padding: 5px 9px;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-control);
  background: var(--ui-surface-alt);
  color: var(--ui-text-secondary);
  font-size: var(--ui-size-11);
  font-weight: var(--ui-weight-bold);
  text-align: center;
}

.moodle-manual-status.is-success {
  border-color: var(--ui-success-border);
  background: var(--ui-success-soft);
  color: var(--ui-success);
}

.moodle-manual-status.is-warning {
  border-color: var(--ui-warning-border);
  background: var(--ui-warning-soft);
  color: var(--ui-warning);
}

.moodle-manual-status.is-error {
  border-color: var(--ui-primary-border);
  background: var(--ui-danger-soft);
  color: var(--ui-primary);
}

.moodle-manual-table {
  min-width: 1080px;
}

.moodle-manual-table strong,
.moodle-manual-table small {
  display: block;
  overflow-wrap: anywhere;
}

.moodle-manual-complete .moodle-table-wrap {
  margin-top: 14px;
}

@media (max-width: 1050px) {
  .moodle-manual-form {
    grid-template-columns: 1fr;
  }

  .moodle-manual-course {
    border-right: 0;
    border-bottom: 1px solid var(--ui-border);
  }

  .moodle-manual-candidates > label {
    grid-template-columns: auto minmax(220px, 1fr) minmax(140px, 0.7fr);
  }

  .moodle-manual-candidates > label > .moodle-manual-status {
    grid-column: span 1;
  }
}

@media (max-width: 720px) {
  .moodle-manual-enrollment {
    padding: 14px;
  }

  .moodle-manual-enrollment .moodle-section__heading,
  .moodle-manual-results > header,
  .moodle-manual-preview > header {
    align-items: stretch;
    flex-direction: column;
  }

  .moodle-manual-enrollment .moodle-section__heading .moodle-button,
  .moodle-manual-results > header .moodle-button,
  .moodle-manual-preview > header .moodle-button,
  .moodle-manual-names > .moodle-button {
    width: 100%;
    min-width: 0;
  }

  .moodle-manual-course,
  .moodle-manual-names {
    padding: 14px;
  }

  .moodle-manual-summary {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .moodle-manual-summary > div {
    border-right: 1px solid var(--ui-border);
    border-bottom: 1px solid var(--ui-border);
  }

  .moodle-manual-candidates > label {
    grid-template-columns: auto minmax(0, 1fr);
    align-items: start;
  }

  .moodle-manual-candidates > label > :not(input) {
    grid-column: 2;
  }
}

/* Aprovisionamiento unificado de credenciales */

.credential-provision-page {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 14px;
  min-width: 0;
}

.credential-provision-page > * {
  grid-column: 1 / -1;
}

.credential-page-summary {
  max-width: 760px;
  margin: 8px 0 0;
  color: var(--ui-muted);
  line-height: 1.45;
}

.credential-process-info-button {
  flex: 0 0 auto;
  min-height: 42px;
  white-space: nowrap;
}

.credential-process-info-backdrop {
  position: fixed;
  inset: 0;
  z-index: 1300;
  display: grid;
  place-items: center;
  padding: 18px;
  background: color-mix(in srgb, var(--ui-text) 56%, transparent);
}

.credential-process-info-dialog {
  width: min(760px, 100%);
  max-height: calc(100dvh - 36px);
  overflow: auto;
  border: 1px solid color-mix(in srgb, var(--ui-accent-border) 78%, transparent);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface);
  box-shadow: var(--ui-shadow-dialog);
}

.credential-process-info-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 18px;
  padding: 20px 22px;
  border-bottom: 1px solid color-mix(in srgb, var(--ui-accent-border) 55%, transparent);
  background: var(--ui-surface-alt);
}

.credential-process-info-head h2,
.credential-process-info-head p {
  margin: 0;
}

.credential-process-info-head h2 {
  margin-top: 4px;
  color: var(--ui-text);
  font-size: var(--ui-size-20);
  line-height: 1.2;
}

.credential-process-info-head p:last-child {
  margin-top: 7px;
  color: var(--ui-muted);
  line-height: 1.45;
}

.credential-process-info-close {
  display: inline-grid;
  flex: 0 0 40px;
  place-items: center;
  width: 40px;
  height: 40px;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-control);
  background: var(--ui-surface);
  color: var(--ui-primary);
  font: 700 25px/1 Arial, sans-serif;
  cursor: pointer;
}

.credential-process-info-close:hover {
  border-color: var(--ui-danger);
  background: var(--ui-danger-soft);
}

.credential-process-details {
  margin: 0;
}

.credential-process-details > div {
  display: grid;
  grid-template-columns: minmax(165px, 0.72fr) minmax(0, 1.6fr);
  grid-template-areas:
    "term value"
    "term help";
  column-gap: 24px;
  row-gap: 4px;
  padding: 17px 22px;
  border-bottom: 1px solid var(--ui-neutral-soft);
}

.credential-process-details dt {
  grid-area: term;
  align-self: center;
  color: var(--ui-muted);
  font-size: var(--ui-size-12);
  font-weight: var(--ui-weight-bold);
}

.credential-process-details dd {
  grid-area: value;
  min-width: 0;
  margin: 0;
  color: var(--ui-text);
  font-size: var(--ui-size-18);
  font-weight: var(--ui-weight-bold);
  overflow-wrap: anywhere;
}

.credential-process-details small {
  grid-area: help;
  min-width: 0;
  color: var(--ui-muted);
  font-size: var(--ui-size-12);
  font-weight: var(--ui-weight-bold);
  line-height: 1.45;
  overflow-wrap: anywhere;
}

.credential-process-info-actions {
  display: flex;
  justify-content: flex-end;
  padding: 16px 22px;
}

.credential-audience-tabs {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
  min-width: 0;
  padding: 10px;
  border: 1px solid color-mix(in srgb, var(--ui-accent-border) 55%, transparent);
