  background: var(--ui-success-soft);
}

.credential-analysis-summary > span.is-danger,
.credential-result-summary > span.is-danger {
  border-left-color: var(--ui-danger);
  background: var(--ui-danger-soft);
}

.credential-analysis-summary > button {
  min-height: 58px;
}

.credential-provision-table-wrap {
  max-width: 100%;
  min-height: 0;
  max-height: min(520px, calc(100dvh - 260px));
  border: 1px solid color-mix(in srgb, var(--ui-border-strong) 82%, transparent);
  border-radius: var(--ui-radius-panel);
  overflow: auto;
}

.credential-analysis-table-wrap {
  max-height: min(430px, calc(100dvh - 300px));
  background: var(--ui-surface);
}

.credential-provision-table,
.credential-result-table,
.credential-history-table {
  width: max-content;
  min-width: 100%;
}

.credential-provision-table {
  min-width: 900px;
}

.credential-analysis-table {
  width: 100%;
  min-width: 780px;
  table-layout: fixed;
}

.credential-analysis-table th,
.credential-analysis-table td {
  padding: 11px 12px;
  vertical-align: middle;
}

.credential-analysis-table th:nth-child(1),
.credential-analysis-table td:nth-child(1) {
  width: 70px;
  text-align: center;
}

.credential-analysis-table th:nth-child(2),
.credential-analysis-table td:nth-child(2) {
  width: 29%;
}

.credential-analysis-table th:nth-child(3),
.credential-analysis-table td:nth-child(3) {
  width: 150px;
}

.credential-analysis-table th:nth-child(4),
.credential-analysis-table td:nth-child(4) {
  width: 30%;
}

.credential-analysis-table th:nth-child(5),
.credential-analysis-table td:nth-child(5) {
  width: 230px;
}

.credential-analysis-table tbody tr {
  box-shadow: inset 3px 0 0 transparent;
  transition: background-color 140ms ease, box-shadow 140ms ease;
}

.credential-analysis-table tbody tr:hover {
  background: var(--ui-surface-alt);
}

.credential-analysis-table tbody tr.is-valid {
  box-shadow: inset 3px 0 0 var(--ui-accent);
}

.credential-analysis-table tbody tr.has-errors {
  background: var(--ui-surface-alt);
  box-shadow: inset 3px 0 0 var(--ui-danger);
}

.credential-analysis-table .credential-email-cell {
  color: var(--ui-accent-hover);
  font-weight: var(--ui-weight-bold);
}

.credential-provision-table th:nth-child(3),
.credential-provision-table td:nth-child(3) {
  min-width: 120px;
  white-space: nowrap;
}

.credential-result-table {
  min-width: 1540px;
}

.credential-history-table {
  min-width: 1740px;
}

.credential-provision-table td,
.credential-result-table td,
.credential-history-table td {
  vertical-align: top;
}

.credential-provision-table td strong,
.credential-result-table td strong,
.credential-history-table td strong,
.credential-result-table td small,
.credential-history-table td small {
  display: block;
}

.credential-email-cell,
.credential-password-cell {
  max-width: 320px;
  overflow-wrap: anywhere;
}

.credential-password-cell {
  font-family: var(--ui-font-mono);
}

.credential-observation-cell {
  min-width: 280px;
  max-width: 380px;
  line-height: 1.4;
  overflow-wrap: anywhere;
}

.credential-observation-cell small {
  display: block;
  margin-top: 6px;
  color: var(--ui-chart-neutral);
  font-weight: var(--ui-weight-bold);
}

.credential-row-error {
  display: block;
  max-width: 360px;
  margin-top: 7px;
  color: var(--ui-danger);
  font-weight: var(--ui-weight-bold);
  line-height: 1.4;
  overflow-wrap: anywhere;
}

.credential-status--success {
  background: color-mix(in srgb, var(--ui-accent) 14%, transparent);
  color: var(--ui-success);
}

.credential-status--warning {
  background: color-mix(in srgb, var(--ui-chart-gold) 16%, transparent);
  color: var(--ui-warning);
}

.credential-status--danger {
  background: color-mix(in srgb, var(--ui-danger) 13%, transparent);
  color: var(--ui-danger);
}

.credential-status--neutral {
  background: color-mix(in srgb, var(--ui-muted) 12%, transparent);
  color: var(--ui-text-secondary);
}

.credential-individual-layout {
  display: grid;
  grid-template-columns: minmax(0, 1.45fr) minmax(300px, 0.75fr);
  gap: 18px;
  margin-top: 12px;
}

.credential-individual-form {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.credential-individual-form label {
  display: grid;
  gap: 6px;
  min-width: 0;
  color: var(--ui-accent-hover);
  font-size: var(--ui-size-12);
  font-weight: var(--ui-weight-bold);
}

.credential-individual-form input {
  width: 100%;
  min-height: 44px;
  border: 1px solid color-mix(in srgb, var(--ui-border-strong) 95%, transparent);
  border-radius: var(--ui-radius-control);
  padding: 10px 12px;
  background: var(--ui-surface);
  color: var(--ui-text);
  font: inherit;
}

.credential-individual-form input:focus,
.credential-file-control input:focus {
  border-color: var(--ui-accent);
  outline: 2px solid color-mix(in srgb, var(--ui-accent) 16%, transparent);
  outline-offset: 1px;
}

.credential-field-full {
  grid-column: 1 / -1;
}

.credential-preview {
  min-width: 0;
  border-left: 4px solid var(--ui-accent);
  padding: 14px 16px;
  background: var(--ui-surface-alt);
}

.credential-preview dl {
  display: grid;
  gap: 12px;
  margin: 12px 0 0;
}

.credential-preview dl div {
  display: grid;
  gap: 4px;
}

.credential-preview dt {
  color: var(--ui-muted);
  font-size: var(--ui-size-11);
  font-weight: var(--ui-weight-bold);
  text-transform: uppercase;
}

.credential-preview dd {
  margin: 0;
  color: var(--ui-text);
  font-weight: var(--ui-weight-bold);
  overflow-wrap: anywhere;
}

.credential-result-actions {
  display: flex;
  align-items: center;
  gap: 10px;
}

.credential-password-toggle {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  min-height: 42px;
  color: var(--ui-accent-hover);
  font-size: var(--ui-size-12);
  font-weight: var(--ui-weight-bold);
}

.credential-report-expiry {
  margin: 10px 0 0;
  color: var(--ui-chart-neutral);
  font-size: var(--ui-size-12);
  font-weight: var(--ui-weight-bold);
  text-align: right;
}

@media (max-width: 1180px) {
  .credential-individual-layout {
    grid-template-columns: 1fr;
  }

  .credential-preview {
    border-top: 1px solid color-mix(in srgb, var(--ui-accent-border) 45%, transparent);
    border-left-width: 4px;
  }
