.moodle-academic-career-selection strong,
.moodle-academic-career-selection small {
  min-width: 0;
  overflow-wrap: anywhere;
}

.moodle-academic-career-selection small {
  color: var(--ui-chart-neutral);
  font-size: var(--ui-size-12);
  line-height: 1.35;
}

.moodle-academic-contexts {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  border-bottom: 1px solid var(--ui-neutral-soft);
}

.moodle-academic-contexts > div {
  display: grid;
  gap: 4px;
  padding: 12px 18px;
  border-right: 1px solid var(--ui-neutral-soft);
}

.moodle-academic-contexts > div:last-child {
  border-right: 0;
}

.moodle-academic-contexts span,
.moodle-academic-teachers h5 {
  margin: 0;
  color: var(--ui-chart-neutral);
  font-size: var(--ui-size-11);
  font-weight: var(--ui-weight-bold);
  text-transform: uppercase;
}

.moodle-academic-contexts strong {
  overflow-wrap: anywhere;
  font-size: var(--ui-size-13);
}

.moodle-academic-teachers {
  display: grid;
  gap: 8px;
  padding: 14px 18px;
  border-bottom: 1px solid var(--ui-neutral-soft);
}

.moodle-academic-teachers > label {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  min-height: 50px;
  padding: 7px 10px;
  border-left: 3px solid var(--ui-success);
  background: var(--ui-surface-alt);
}

.moodle-academic-teachers > label.is-invalid {
  border-left-color: var(--ui-danger);
  background: var(--ui-surface-alt);
}

.moodle-academic-teachers input {
  width: 18px;
  height: 18px;
  margin: 0;
  accent-color: var(--ui-accent);
}

.moodle-academic-teachers label > span:not(.moodle-academic-status) {
  display: grid;
  min-width: 0;
  gap: 3px;
}

.moodle-academic-teachers strong,
.moodle-academic-teachers small {
  overflow-wrap: anywhere;
}

.moodle-academic-students summary {
  padding: 13px 18px;
  color: var(--ui-text);
  font-weight: var(--ui-weight-bold);
  cursor: pointer;
}

.moodle-academic-students[open] summary {
  border-bottom: 1px solid var(--ui-border);
  background: var(--ui-surface-alt);
}

.moodle-academic-students td > strong,
.moodle-academic-students td > small {
  display: block;
  min-width: 0;
  overflow-wrap: anywhere;
}

.moodle-academic-students td .moodle-academic-status {
  margin-bottom: 4px;
}

.moodle-academic-status {
  display: inline-flex;
  min-height: 26px;
  align-items: center;
  justify-content: center;
  padding: 4px 8px;
  border: 1px solid var(--ui-border-strong);
  border-radius: var(--ui-radius-control);
  background: var(--ui-background);
  color: var(--ui-text-secondary);
  font-size: var(--ui-size-11);
  font-weight: var(--ui-weight-bold);
  white-space: nowrap;
}

.moodle-academic-status.is-success {
  border-color: var(--ui-success-border);
  background: var(--ui-success-soft);
  color: var(--ui-success);
}

.moodle-academic-status.is-warning {
  border-color: var(--ui-warning-border);
  background: var(--ui-warning-soft);
  color: var(--ui-warning);
}

.moodle-academic-status.is-error {
  border-color: var(--ui-primary-border);
  background: var(--ui-danger-soft);
  color: var(--ui-primary);
}

.moodle-confirm-dialog.moodle-academic-detail {
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  width: min(1380px, calc(100vw - 32px));
  max-height: calc(100dvh - 32px);
  overflow: hidden;
}

.moodle-academic-detail .moodle-confirm-dialog__header {
  position: relative;
  z-index: 2;
  align-items: center;
}

.moodle-academic-detail .moodle-confirm-dialog__header > div {
  min-width: 0;
}

.moodle-academic-detail .moodle-confirm-dialog__header h2 {
  max-width: 100%;
  overflow-wrap: anywhere;
}

.moodle-academic-detail__body {
  min-height: 0;
  padding: 0;
  overflow: auto;
  scrollbar-gutter: stable;
}

.moodle-academic-detail__context {
  display: grid;
  grid-template-columns: minmax(130px, 0.45fr) minmax(260px, 2fr) minmax(180px, 1fr);
  border-bottom: 1px solid var(--ui-border);
  background: var(--ui-surface-alt);
}

.moodle-academic-detail__context > div {
  display: grid;
  min-width: 0;
  min-height: 70px;
  align-content: center;
  gap: 4px;
  padding: 11px 16px;
  border-right: 1px solid var(--ui-border);
}

.moodle-academic-detail__context > div:last-child {
  border-right: 0;
}

.moodle-academic-detail__context span {
  color: var(--ui-chart-neutral);
  font-size: var(--ui-size-11);
  font-weight: var(--ui-weight-bold);
  text-transform: uppercase;
}

.moodle-academic-detail__context strong {
  min-width: 0;
  overflow-wrap: anywhere;
  color: var(--ui-text);
  font-size: var(--ui-size-14);
}

.moodle-academic-detail__context > div:first-child strong {
  font-size: var(--ui-size-20);
}

.moodle-academic-detail__table {
  min-width: 1080px;
}

.moodle-academic-detail__table td {
  vertical-align: top;
  line-height: 1.4;
}

.moodle-academic-detail__table td > strong,
.moodle-academic-detail__table td > small {
  display: block;
  min-width: 0;
  overflow-wrap: anywhere;
}

.moodle-academic-detail__table td > small {
  margin-top: 4px;
  color: var(--ui-chart-neutral);
}

.moodle-academic-detail__table td .moodle-academic-status {
  margin-bottom: 2px;
}

@media (max-width: 900px) {
  .moodle-academic-summary {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .moodle-academic-summary > div {
    border-bottom: 1px solid var(--ui-border);
  }

  .moodle-academic-summary > button {
    border-bottom: 1px solid var(--ui-border);
  }
