@media (max-width: 760px) {
  .credential-mode-tabs,
  .credential-upload-row,
  .credential-analysis-summary,
  .credential-result-summary,
  .credential-individual-form {
    grid-template-columns: 1fr;
  }

  .credential-mode-tabs button {
    border-right: 0;
    border-bottom: 1px solid color-mix(in srgb, var(--ui-accent-border) 45%, transparent);
  }

  .credential-mode-tabs button:last-child {
    border-bottom: 0;
  }

  .credential-mode-tabs button.is-active {
    box-shadow: inset 4px 0 0 var(--ui-accent);
  }

  .credential-field-full {
    grid-column: auto;
  }

  .credential-result-head,
  .credential-result-actions {
    display: grid;
    grid-template-columns: 1fr;
    width: 100%;
  }

  .credential-result-actions button,
  .credential-upload-row > button,
  .credential-analysis-summary > button,
  .credential-actions button {
    width: 100%;
  }

  .credential-analysis-table-wrap {
    max-height: none;
    overflow: visible;
  }

  .credential-analysis-table,
  .credential-analysis-table tbody,
  .credential-analysis-table tr,
  .credential-analysis-table td {
    display: block;
    width: 100%;
    min-width: 0;
  }

  .credential-analysis-table thead {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip: rect(0 0 0 0);
    clip-path: inset(50%);
    white-space: nowrap;
  }

  .credential-analysis-table tbody tr {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 11px 16px;
    padding: 13px 14px;
    border-bottom: 1px solid color-mix(in srgb, var(--ui-accent-border) 50%, transparent);
  }

  .credential-analysis-table tbody tr:last-child {
    border-bottom: 0;
  }

  .credential-analysis-table td,
  .credential-analysis-table td:nth-child(n) {
    display: grid;
    gap: 4px;
    width: auto;
    padding: 0;
    border: 0;
    text-align: left;
    white-space: normal;
  }

  .credential-analysis-table td::before {
    content: attr(data-label);
    color: var(--ui-chart-neutral);
    font-size: var(--ui-size-11);
    font-weight: var(--ui-weight-bold);
    text-transform: uppercase;
  }

  .credential-analysis-table td:nth-child(1) {
    grid-column: 1;
    grid-row: 1;
  }

  .credential-analysis-table td:nth-child(3) {
    grid-column: 2;
    grid-row: 1;
  }

  .credential-analysis-table td:nth-child(2) {
    grid-column: 1 / -1;
    grid-row: 2;
  }

  .credential-analysis-table td:nth-child(4) {
    grid-column: 1 / -1;
    grid-row: 3;
  }

  .credential-analysis-table td:nth-child(5) {
    grid-column: 1 / -1;
    grid-row: 4;
  }

  .credential-analysis-table .credential-row-error {
    max-width: none;
    margin-top: 2px;
  }
}

@media (max-width: 520px) {
