/* Vista compacta del estudiante en practicas institucionales. */

.practicas-hero__copy {
  min-width: 0;
}

.practicas-hero {
  grid-template-columns: minmax(0, 1fr);
}

.practicas-hero__copy h1,
.practicas-hero__copy p {
  max-width: 100%;
  overflow-wrap: anywhere;
}

.practicas-overview-layout,
.practicas-navigation-layout {
  display: contents;
}

.practicas-page--student {
  display: grid;
  gap: 10px;
  align-content: start;
}

.practicas-page--student > * {
  min-width: 0;
}

.practicas-page--student .practicas-hero {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  min-height: 0;
  padding: 12px 16px;
}

.practicas-page--student .practicas-hero small {
  margin: 0;
  font-size: var(--ui-size-12);
  letter-spacing: 0;
}

.practicas-page--student .practicas-hero h1 {
  margin: 3px 0 5px;
  font-size: var(--ui-size-32);
  line-height: 1.08;
}

.practicas-page--student .practicas-hero p {
  font-size: var(--ui-size-14);
  line-height: 1.35;
}

.practicas-page--student .practicas-overview-layout {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 480px), 1fr));
  gap: 10px;
  align-items: stretch;
}

.practicas-page--student .practicas-process-selector,
.practicas-page--student .practicas-summary,
.practicas-page--student .practicas-enrollment-boundary,
.practicas-page--student .practicas-workspace-tabs,
.practicas-page--student .practicas-ops {
  margin-top: 0;
}

.practicas-page--student .practicas-process-selector {
  height: 100%;
  gap: 8px;
}

.practicas-page--student .practicas-process-selector button {
  min-height: 76px;
  gap: 2px;
  padding: 9px 11px;
}

.practicas-page--student .practicas-process-selector button > strong {
  font-size: var(--ui-size-14);
  line-height: 1.2;
}

.practicas-page--student .practicas-process-selector button > small {
  font-size: var(--ui-size-11);
  line-height: 1.3;
}

.practicas-page--student .practicas-summary {
  grid-template-columns: minmax(210px, 1.55fr) repeat(2, minmax(105px, 0.7fr));
  gap: 0;
  height: 100%;
  overflow: hidden;
  border: 1px solid var(--line-strong);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface);
}

.practicas-page--student .practicas-summary article {
  align-content: center;
  gap: 3px;
  padding: 9px 12px;
}

.practicas-page--student .practicas-summary article + article {
  border-left: 1px solid var(--line-strong);
}

.practicas-page--student .practicas-summary span {
  font-size: var(--ui-size-11);
  letter-spacing: 0;
}

.practicas-page--student .practicas-summary strong {
  font-size: var(--ui-size-18);
  line-height: 1.2;
}

.practicas-page--student .practicas-summary p {
  color: var(--ink-soft);
  font-size: var(--ui-size-12);
  line-height: 1.3;
}

.practicas-page--student .practicas-navigation-layout {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 480px), 1fr));
  gap: 10px;
  align-items: stretch;
}

.practicas-page--student .practicas-enrollment-boundary {
  height: 100%;
}

.practicas-page--student .practicas-enrollment-boundary > div {
  display: grid;
  align-content: center;
  padding: 9px 12px;
}

.practicas-page--student .practicas-enrollment-boundary strong {
  font-size: var(--ui-size-12);
}

.practicas-page--student .practicas-enrollment-boundary span {
  margin-top: 2px;
  font-size: var(--ui-size-11);
  line-height: 1.3;
}

.practicas-page--student .practicas-workspace-tabs {
  grid-template-columns: repeat(2, minmax(0, 1fr));
  height: 100%;
  gap: 8px;
}

.practicas-page--student .practicas-workspace-tabs button {
  min-height: 64px;
  gap: 2px;
  padding: 9px 11px;
}

.practicas-page--student .practicas-workspace-tabs button > strong {
  font-size: var(--ui-size-14);
}

.practicas-page--student .practicas-workspace-tabs button > small {
  font-size: var(--ui-size-11);
  line-height: 1.3;
}

.practicas-page--student .practicas-ops {
