/* Registro previo guiado: mantiene el formulario compacto y ordenado por etapa. */

.preinscripcion-registration-steps {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  margin: 0 0 18px;
  overflow: hidden;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface);
}

.preinscripcion-registration-steps button {
  min-width: 0;
  min-height: 72px;
  padding: 12px 14px;
  display: grid;
  grid-template-columns: 30px minmax(0, 1fr);
  grid-template-rows: auto auto;
  column-gap: 10px;
  align-items: center;
  border: 0;
  border-radius: 0;
  background: var(--ui-surface);
  color: var(--ui-text-secondary);
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.preinscripcion-registration-steps button + button {
  border-left: 1px solid var(--ui-border);
