/* Asignacion de pantallas: lectura alfabetica y estados de seleccion. */

.screen-access-selection-bar {
  display: flex;
  flex-wrap: wrap;
  gap: 10px 16px;
  align-items: center;
  justify-content: space-between;
  margin: 0 0 12px;
  border: 1px solid color-mix(in srgb, var(--ui-accent-border) 52%, transparent);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface);
  padding: 10px 12px;
}

.screen-access-selection-filters {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
  align-items: center;
}

.screen-access-selection-filters > span {
  margin-right: 2px;
  color: var(--ui-muted);
  font-size: var(--ui-size-11);
  font-weight: var(--ui-weight-bold);
  letter-spacing: 0;
  text-transform: uppercase;
}

.screen-access-selection-filters button {
  display: inline-flex;
  min-height: 38px;
  gap: 8px;
  align-items: center;
  justify-content: center;
  border: 1px solid color-mix(in srgb, var(--ui-accent-border) 62%, transparent);
  border-radius: var(--ui-radius-panel);
  background: var(--surface-tint);
  color: var(--ink);
  padding: 7px 10px;
  font: inherit;
  font-size: var(--ui-size-12);
  font-weight: var(--ui-weight-bold);
}

.screen-access-selection-filters button b {
  display: inline-grid;
  min-width: 24px;
  height: 24px;
  place-items: center;
  border-radius: 50%;
  background: color-mix(in srgb, var(--ui-muted) 12%, transparent);
  color: var(--ui-text-secondary);
  padding: 0 6px;
  font-size: var(--ui-size-11);
}

.screen-access-selection-filters button.is-active {
  border-color: color-mix(in srgb, var(--ui-accent) 70%, transparent);
  background: color-mix(in srgb, var(--ui-accent) 11%, transparent);
  color: var(--ui-accent-hover);
  box-shadow: inset 0 -3px 0 color-mix(in srgb, var(--ui-accent) 72%, transparent);
}

.screen-access-selection-filters button.is-active b {
  background: var(--ui-accent);
  color: var(--ui-on-primary);
}

.screen-access-selection-bar > p {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
  margin: 0;
}

.screen-access-selection-key {
  display: inline-flex;
  min-height: 30px;
  gap: 7px;
  align-items: center;
  border: 1px solid color-mix(in srgb, var(--ui-border-strong) 80%, transparent);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface);
  color: var(--ui-muted);
  padding: 5px 9px;
  font-size: var(--ui-size-11);
  font-weight: var(--ui-weight-bold);
}

.screen-access-selection-key::before {
  width: 9px;
  height: 9px;
  flex: 0 0 auto;
  border: 1px solid var(--ui-border-strong);
  border-radius: 50%;
  background: var(--ui-surface);
  content: '';
}

.screen-access-selection-key--assigned {
  border-color: color-mix(in srgb, var(--ui-accent) 34%, transparent);
  background: color-mix(in srgb, var(--ui-accent) 7%, transparent);
  color: var(--ui-accent-hover);
}

.screen-access-selection-key--assigned::before {
  border-color: var(--ui-accent);
  background: var(--ui-accent);
}

.screen-access-selection-key--restricted {
  border-color: color-mix(in srgb, var(--ui-warning) 36%, transparent);
  background: var(--ui-warning-soft);
  color: var(--ui-warning);
}

.screen-access-selection-key--restricted::before {
  border-color: var(--ui-warning);
  background: var(--ui-warning);
}

.screen-access-selection-filters button.is-active.is-restricted {
  border-color: color-mix(in srgb, var(--ui-warning) 62%, transparent);
  background: var(--ui-warning-soft);
  color: var(--ui-warning);
  box-shadow: inset 0 -3px 0 color-mix(in srgb, var(--ui-warning) 78%, transparent);
}

.screen-access-selection-filters button.is-active.is-restricted b {
  background: var(--ui-warning);
  color: var(--ui-on-primary);
}

.screen-access-group__head > div {
  display: grid;
  min-width: 0;
  gap: 3px;
}

.screen-access-group__head > div > span {
  color: var(--ui-chart-neutral);
  font-size: var(--ui-size-11);
  font-weight: var(--ui-weight-bold);
}

.screen-access-group__toggle {
  min-height: 36px;
  flex: 0 0 auto;
  border: 1px solid color-mix(in srgb, var(--ui-accent-border) 62%, transparent);
  border-radius: var(--ui-radius-panel);
  background: var(--surface-tint);
  color: var(--ink);
  padding: 7px 10px;
  font: inherit;
  font-size: var(--ui-size-11);
  font-weight: var(--ui-weight-bold);
}

.screen-access-group__toggle:hover:not(:disabled),
.screen-access-selection-filters button:hover:not(:disabled) {
  border-color: color-mix(in srgb, var(--ui-accent) 70%, transparent);
  background: color-mix(in srgb, var(--ui-accent) 10%, transparent);
}

.screen-access-group__toggle:disabled {
  cursor: not-allowed;
  opacity: 0.5;
}

.screen-access-item {
  position: relative;
  transition: border-color 140ms ease, background-color 140ms ease, box-shadow 140ms ease;
}

.screen-access-item__copy {
  display: grid;
  min-width: 0;
  align-content: start;
}

.screen-access-item .screen-access-item__status {
  display: inline-flex;
  width: fit-content;
  min-height: 22px;
  align-items: center;
  margin: 0 0 6px;
  border: 1px solid color-mix(in srgb, var(--ui-border-strong) 45%, transparent);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface-alt);
  color: var(--ui-chart-neutral);
  padding: 3px 8px;
  font-size: var(--ui-size-11);
  font-weight: var(--ui-weight-bold);
  letter-spacing: 0;
  line-height: 1;
  text-transform: uppercase;
}

.screen-access-item .screen-access-item__status.is-assigned {
  border-color: color-mix(in srgb, var(--ui-accent) 40%, transparent);
  background: color-mix(in srgb, var(--ui-accent) 12%, transparent);
  color: var(--ui-accent-hover);
}

.screen-access-item--checked {
  border-left: 4px solid var(--ui-accent);
  box-shadow: var(--ui-shadow-sm);
}

.screen-access-item--restricted {
  cursor: not-allowed;
  border-color: color-mix(in srgb, var(--ui-warning) 38%, transparent);
  background: var(--ui-danger-soft);
  box-shadow: none;
}

.screen-access-item--restricted input {
  cursor: not-allowed;
}

.screen-access-item .screen-access-item__status.is-restricted {
  border-color: color-mix(in srgb, var(--ui-warning) 42%, transparent);
  background: var(--ui-warning-soft);
  color: var(--ui-warning);
}

.screen-access-item .screen-access-item__restriction {
  color: var(--ui-warning);
  font-weight: var(--ui-weight-bold);
}

@media (max-width: 720px) {
  .screen-access-selection-bar {
    align-items: stretch;
    flex-direction: column;
  }

  .screen-access-selection-bar > p {
    justify-content: flex-start;
  }
}

@media (max-width: 560px) {
  .screen-access-selection-filters > span {
    width: 100%;
  }

  .screen-access-selection-filters button {
    flex: 1 1 calc(50% - 4px);
  }

  .screen-access-selection-bar > p {
    display: grid;
  }

  .screen-access-group__toggle {
    width: 100%;
  }
}

