  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
  width: 100%;
  max-width: none;
  border-radius: var(--ui-radius-panel);
  box-shadow: none;
}

.teacher-evaluation-history .teacher-evaluation__hero > div {
  min-width: 0;
}

.teacher-evaluation-history__header-actions {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 10px;
}

.teacher-evaluation-history__header-actions .teacher-evaluation__summary-pill {
  width: auto;
  margin-right: 0;
}

.teacher-evaluation.teacher-evaluation-history .teacher-evaluation__hero h1 {
  font-size: var(--ui-size-28);
  line-height: 1.2;
  letter-spacing: 0;
}

.teacher-evaluation-history h2,
.teacher-evaluation-history h3 {
  margin: 0;
  font-size: var(--ui-size-16);
  line-height: 1.4;
  letter-spacing: 0;
}

.teacher-evaluation-history__tabs {
  display: flex;
  border-bottom: 1px solid var(--ui-border);
  background: var(--ui-surface);
}

.teacher-evaluation-history__tabs button,
.teacher-evaluation-history__selection-actions button,
.teacher-evaluation-history__pagination button {
  padding: 10px 16px;
  border: 0;
  background: transparent;
  color: var(--ui-accent-hover);
  font: inherit;
  font-size: var(--ui-size-13);
  font-weight: var(--ui-weight-bold);
  cursor: pointer;
}

.teacher-evaluation-history__tabs button[aria-selected="true"] {
  box-shadow: inset 0 -3px var(--ui-accent);
  color: var(--ui-accent);
  background: var(--ui-accent-soft);
}

.teacher-evaluation-history__notice {
  margin-bottom: 14px;
  padding: 12px 16px;
  border-left: 3px solid var(--ui-danger);
  background: var(--ui-surface);
  color: var(--ui-text-secondary);
  font-size: var(--ui-size-13);
  line-height: 1.5;
}

.teacher-evaluation-history__generation-progress {
  margin-bottom: 14px;
  padding: 14px 16px;
  background: var(--ui-surface);
  border-block: 1px solid var(--ui-border);
  font-size: var(--ui-size-13);
}

.teacher-evaluation-history__generation-progress > div {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 8px;
}

.teacher-evaluation-history__generation-progress progress {
  display: block;
  width: 100%;
  height: 12px;
  margin-block: 10px;
  accent-color: var(--ui-accent);
}

.teacher-evaluation-history__progress-access {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 14px;
  padding: 12px 16px;
  border-block: 1px solid var(--ui-border);
  background: var(--ui-surface);
  font-size: var(--ui-size-13);
}

.teacher-evaluation.teacher-evaluation--compact .teacher-evaluation-history__progress-modal {
  width: min(620px, calc(100vw - 24px));
  max-width: none;
  max-height: calc(100dvh - 24px);
  margin: auto;
  padding: 0;
  box-sizing: border-box;
  border: 1px solid var(--ui-border);
  border-radius: var(--ui-radius-panel);
  background: var(--ui-surface);
  color: inherit;
  box-shadow: var(--ui-shadow-dialog);
}

.teacher-evaluation.teacher-evaluation--compact .teacher-evaluation-history__progress-modal:not([open]) {
  display: none;
}

.teacher-evaluation-history__progress-modal::backdrop {
  background: color-mix(in srgb, var(--ui-text) 56%, transparent);
}

.teacher-evaluation-history__progress-modal .teacher-evaluation__modal-header > div {
  min-width: 0;
}

.teacher-evaluation-history__progress-modal h2 {
  font-size: var(--ui-size-18);
  line-height: 1.4;
  overflow-wrap: anywhere;
}

.teacher-evaluation-history__progress-modal .teacher-evaluation__modal-header > button {
  flex-shrink: 0;
}

.teacher-evaluation-history__progress-modal .teacher-evaluation-history__generation-progress {
  margin-bottom: 0;
  padding: 0;
  border: 0;
}

.teacher-evaluation-history__progress-percent {
  font-size: var(--ui-size-24);
  font-weight: var(--ui-weight-bold);
  color: var(--ui-accent);
  font-variant-numeric: tabular-nums;
}

.teacher-evaluation-history__progress-modal .teacher-evaluation__message {
  overflow-wrap: anywhere;
}

.teacher-evaluation-history__success-summary {
  display: grid;
  gap: 6px;
  min-width: 0;
  border-radius: var(--ui-radius-panel);
  font-weight: var(--ui-weight-normal);
  line-height: 1.5;
  white-space: normal;
  overflow-wrap: anywhere;
}

.teacher-evaluation-history__success-summary > * {
  min-width: 0;
}

.teacher-evaluation-history__success-batch {
  display: grid;
  gap: 2px;
}

.teacher-evaluation-history__success-batch code {
  color: inherit;
  font-size: var(--ui-size-12);
  line-height: 1.5;
  white-space: normal;
  overflow-wrap: anywhere;
}

.teacher-evaluation-history__selectors {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  background: var(--ui-surface);
  border-block: 1px solid var(--ui-border);
}

.teacher-evaluation-history__selector {
  min-width: 0;
}

.teacher-evaluation-history__selector + .teacher-evaluation-history__selector {
  border-left: 1px solid var(--ui-border);
}

.teacher-evaluation-history__selector header,
.teacher-evaluation-history__preview > header,
.teacher-evaluation-history__answers > header,
.teacher-evaluation-history__toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 14px 16px;
}

.teacher-evaluation-history__selector header {
  min-height: 76px;
  box-sizing: border-box;
}

.teacher-evaluation-history__selector h2 {
  white-space: nowrap;
}

.teacher-evaluation-history__selector h2 span {
  margin-left: 6px;
  font-size: var(--ui-size-13);
  color: var(--ui-chart-neutral);
}

.teacher-evaluation-history__selector header input,
.teacher-evaluation-history__selector header select {
  width: min(280px, 60%);
  min-width: 0;
  height: 40px;
  padding: 8px 10px;
  border-radius: var(--ui-radius-control);
  font-size: var(--ui-size-13);
}

.teacher-evaluation-history__selection-actions {
  display: flex;
  flex-wrap: wrap;
  border-block: 1px solid var(--ui-neutral-soft);
  background: var(--ui-surface-alt);
}

.teacher-evaluation-history__options {
  height: 340px;
  overflow-y: auto;
}

.teacher-evaluation-history__options label {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  min-height: 64px;
  padding: 12px 16px;
  border-bottom: 1px solid var(--ui-neutral-soft);
  box-sizing: border-box;
  cursor: pointer;
}

.teacher-evaluation-history__options label:has(input:checked) {
  background: var(--ui-accent-soft);
}

.teacher-evaluation-history input[type="checkbox"] {
  width: 17px;
  height: 17px;
  flex: 0 0 17px;
  margin: 2px 0 0;
  padding: 0;
  accent-color: var(--ui-accent);
}

.teacher-evaluation-history__options label span {
  min-width: 0;
  font-size: var(--ui-size-13);
  overflow-wrap: anywhere;
}

.teacher-evaluation-history small {
  display: block;
  margin-top: 4px;
  font-size: var(--ui-size-11);
  color: var(--ui-chart-neutral);
  line-height: 1.5;
  overflow-wrap: anywhere;
}

.teacher-evaluation-history__options > p {
  padding: 12px 16px;
  color: var(--ui-chart-neutral);
}

.teacher-evaluation-history__toolbar,
.teacher-evaluation-history__preview > header {
  font-size: var(--ui-size-13);
  background: var(--ui-surface);
  border-bottom: 1px solid var(--ui-border);
}

.teacher-evaluation-history__preview {
  margin-top: 16px;
  background: var(--ui-surface);
}

.teacher-evaluation-history__instrument {
  margin: 0;
  padding: 10px 16px;
  font-size: var(--ui-size-12);
  color: var(--ui-chart-neutral);
  border-bottom: 1px solid var(--ui-border);
}

.teacher-evaluation-history__table-wrap {
  overflow-x: auto;
}

.teacher-evaluation-history table {
  width: 100%;
  min-width: 900px;
  table-layout: fixed;
  border-collapse: collapse;
  font-size: var(--ui-size-12);
}

.teacher-evaluation-history th,
.teacher-evaluation-history td {
  padding: 12px;
  text-align: left;
  vertical-align: top;
  border-bottom: 1px solid var(--ui-neutral-soft);
  overflow-wrap: anywhere;
  line-height: 1.5;
}

.teacher-evaluation-history th {
  background: var(--ui-background);
  font-size: var(--ui-size-11);
}

.teacher-evaluation-history tbody tr:nth-child(even) {
  background: var(--ui-surface-alt);
}

.teacher-evaluation-history__status {
  display: inline-block;
  padding: 3px 7px;
  border-radius: var(--ui-radius-sm);
  color: var(--ui-accent);
  background: var(--ui-success-soft);
  font-size: var(--ui-size-11);
  font-weight: var(--ui-weight-bold);
}

.teacher-evaluation-history__status--existing {
  color: var(--ui-muted);
  background: var(--ui-background);
}

.teacher-evaluation-history__pagination {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
  padding: 12px 16px;
  font-size: var(--ui-size-12);
}

.teacher-evaluation-history__pagination > span {
  margin-right: auto;
  color: var(--ui-chart-neutral);
}

.teacher-evaluation-history__answers {
  border-top: 1px solid var(--ui-border);
}

.teacher-evaluation-history__answers ol {
  margin: 0;
  padding: 0 16px 16px;
  list-style: none;
  counter-reset: historical-question;
}

.teacher-evaluation-history__answers li {
  display: grid;
  grid-template-columns: 24px minmax(0, 1fr) 48px;
  align-items: start;
  gap: 10px;
  padding: 10px 0;
  border-top: 1px solid var(--ui-neutral-soft);
  font-size: var(--ui-size-13);
  line-height: 1.5;
}

.teacher-evaluation-history__answers li::before {
  counter-increment: historical-question;
  content: counter(historical-question) ".";
  color: var(--ui-chart-neutral);
}

.teacher-evaluation-history__answers li strong {
  text-align: right;
  white-space: nowrap;
}

.teacher-evaluation-history__confirmation {
  display: grid;
  gap: 14px;
  padding: 16px;
  border-top: 1px solid var(--ui-border);
  font-size: var(--ui-size-13);
}

.teacher-evaluation-history__confirmation textarea {
  margin-top: 8px;
  box-sizing: border-box;
  border-radius: var(--ui-radius-control);
  resize: vertical;
}

.teacher-evaluation-history__acknowledgment {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  line-height: 1.5;
}

.teacher-evaluation-history__confirmation > button {
  justify-self: end;
}

.teacher-evaluation-history button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.teacher-evaluation-history button:focus-visible,
.teacher-evaluation-history input:focus-visible,
.teacher-evaluation-history select:focus-visible,
.teacher-evaluation-history textarea:focus-visible {
  outline: 2px solid var(--ui-accent);
  outline-offset: 3px;
}

@media (max-width: 860px) {
  .teacher-evaluation-history__selectors {
    grid-template-columns: minmax(0, 1fr);
  }

  .teacher-evaluation-history__selector + .teacher-evaluation-history__selector {
    border-left: 0;
    border-top: 1px solid var(--ui-border);
  }

  .teacher-evaluation-history__options {
    height: 260px;
  }
}

@media (max-width: 520px) {
  .teacher-evaluation-admin-navigation {
    align-items: stretch;
    flex-direction: column;
    gap: 0;
    padding: 0;
  }

  .teacher-evaluation-admin-navigation > span {
    padding: 10px 16px;
    border-bottom: 1px solid var(--ui-neutral-soft);
  }

  .teacher-evaluation-admin-navigation > div {
    flex-direction: column;
  }

  .teacher-evaluation-admin-navigation button {
    width: 100%;
    text-align: left;
  }

  .teacher-evaluation.teacher-evaluation-history .teacher-evaluation__hero,
  .teacher-evaluation-history__toolbar,
  .teacher-evaluation-history__preview > header,
  .teacher-evaluation-history__answers > header {
    align-items: flex-start;
    flex-direction: column;
  }

  .teacher-evaluation-history__selector header {
    flex-wrap: wrap;
  }

  .teacher-evaluation-history__selector header input,
  .teacher-evaluation-history__selector header select {
    width: 100%;
  }

  .teacher-evaluation-history__pagination {
    flex-wrap: wrap;
  }

  .teacher-evaluation-history__pagination > span {
    width: 100%;
  }

  .teacher-evaluation-history__confirmation > button,
  .teacher-evaluation-history__toolbar > button {
    width: 100%;
  }
}
}
